window.HARDTRP.receive("84658",[[84659,"2026-06-30T20:08:03",9,"Начало темы.\n\nHard Master — Дм этой темы.",84658,null],[84660,"2026-06-30T20:08:41",32,"Я тут",84658,null],[84661,"2026-06-30T20:08:47",9,"// @Xaosick @Jak_Zak скиньте арт ваших персов с коротким описанием и я начну",84658,null],[84664,"2026-06-30T20:10:13",9,"//Ебать что за нах!",84658,null],[84666,"2026-06-30T20:10:23",9,"//Нахрена анкету)",84658,null],[84667,"2026-06-30T20:11:05",9,"//Просто картинки с нескол кими словами об персе и именем хватило бы, нахер мне анкета)))",84658,null],[84668,"2026-06-30T20:11:34",32,"Маг волшебник, принц клана в свободном плаванье. Хаотично Добрый по мировоззрению",84664,null],[84670,"2026-06-30T20:15:47",42,"Майло",84658,null],[84671,"2026-06-30T20:18:26",9,"*Поск дракона привёл героев в деревушку у самых драконьих гор. Королевство Кравлости Темноград процветало под гнётом рыцарей, раздолье для героев из народа. Направил сюда именно слушок что появился дракон и требует дань с местных. А Темноградских вольных рыцарей что были бы достойными противниками рядом не оказалось, несколько оруженосцев что решились сразить дракона исчезли.*",84658,null],[84672,"2026-06-30T20:21:34",32,"//Я если что в таверне купил самой крепкой бормотухи (\"закалённое\" четыре галона )перед выходом.",84671,null],[84673,"2026-06-30T20:22:48",32,"И собственно. Двинулись мы разузнать когда и где дракон будет забирать дань",84658,null],[84674,"2026-06-30T20:23:44",9,"//Я хз что это даже, без разницы)",84672,null],[84675,"2026-06-30T20:24:23",32,"//крайне крепкий напиток по типу самогона. По 5 зм за галон",84674,null],[84676,"2026-06-30T20:24:43",32,"//меня привлекла крепость. Есть пара идей",84658,null],[84677,"2026-06-30T20:25:13",9,"//Да оке, уменя на квесте профита 0, я не знаю о таком предмете, сорян",84658,null],[84678,"2026-06-30T20:25:50",9,"//В таверне то для таверны чисто Инсайд придумад, даже не проверял чё там",84658,null],[84679,"2026-06-30T20:26:30",32,"//не поверишь но в идём на дракона но скорее всего не охотится и Арминар подумал \"а что если споить дракона?\"",84658,null],[84680,"2026-06-30T20:27:53",32,"//Потому и брал именно самое крепкое. И собственно брал впринципе",84658,null],[84681,"2026-06-30T20:29:01",32,"Арминар, прийдя по слухам в деревню. Двинулся к старосте. Так как он не знал кто это, двинулся в самый богато выглядящий дом.",84658,null],[84684,"2026-06-30T20:29:49",9,"*Вас встречает деревушка, с именем \"Дракеризада\" от словосочитайния \"в драконьей заднице\". На первый взгляд все спокойно, но со стороны гор старые полуразрушенные крепости и есть несколько сигнальных башен. В теории здесь можно было бы сдержать дракона некоторое время.*",84658,null],[84685,"2026-06-30T20:31:17",9,"*Никто ничего не боится, люди выглядит спокойно только очень касятся на драконида, словно готовые схватиться за оружие в любой момент. Их скорее останавливает только то что Аминар выглядит внушительно и рядом с ним Майло.*",84658,null],[84688,"2026-06-30T20:32:31",42,"— мда.. Гостеприимство на высшем уровне\n°прохрустывает костяшками пальцев смотря на людей у которых читается в глазах страх или ненависть к спутнику°",84658,null],[84689,"2026-06-30T20:33:35",9,"Местный храбрец — Чо туты дела дракониде?",84658,null],[84690,"2026-06-30T20:33:49",32,"-Мне кажется или тут не знают что драконорожденные и драконы не очень дружат за редкими исключениями?",84688,null],[84691,"2026-06-30T20:34:17",9,"*Какой-то мужик с вилами что перекидывал солому спросил без страха.*",84689,null],[84692,"2026-06-30T20:35:25",32,"(Арминар окинул храбреца взглядом потомственного аристократа и сказал)\n- я слышал у вас тут дракон завелся и дань требует. Ищу того кто знает как будет собираться дань",84689,null],[84711,"2026-06-30T20:40:44",9,"Местный храбрец — Холд? Рытари придоут а драк буде ве сре в пещери костями и кревью. — *Он вообще не боится, ждёт рыцарей которые дадут дракону по первое число. Люди под защитой жили всю жизнь, страна где сила личности превыше, честь рыцарство. Народ боевой, небоязливый.*",84658,null],[84713,"2026-06-30T20:42:16",32,"//почему у него почти нечитаемая речь?",84711,null],[84715,"2026-06-30T20:42:38",42,"— ну чтож.. Дракон говорите. А если мы решим проблему с ними до прибытия рыцарей? Что нам будет? \n°хватается за свой подбородок и улыбается°",84658,null],[84716,"2026-06-30T20:43:05",32,"-Я сомневаюсь что мы потянем дракона даже в двоем",84715,null],[84717,"2026-06-30T20:43:08",9,"//Акцент сельский",84713,null],[84719,"2026-06-30T20:43:40",32,"//можно его убрать пожалуйста. Понятно что акцент мне текст сложно читать",84717,null],[84721,"2026-06-30T20:44:51",42,"— убивать не обязательно. Хотя я был бы рад отведать дракотины. Кхехе\n°внимательно осматриваю напарника°\n— но я люблю горячее мясо)",84716,null],[84722,"2026-06-30T20:44:58",9,"Местный храбрец — То же добре, можете се стат рытарем а за все це дают злато.",84715,null],[84726,"2026-06-30T20:45:58",9,"*Местный прилаживает руку к груди, удар кулаком, гордость за защитников крошечной страны.*",84658,null],[84727,"2026-06-30T20:46:04",42,"— рыцарство меня не привлекает. Мне лишь бы денег на одну вещь, да и по зарез. Слышал драконы имеют сокровищницы",84722,null],[84732,"2026-06-30T20:47:18",32,"- я Арминар принц клана Каррелон. Я маг.\nТак где должен появиться дракон или где его логово?",84711,null],[84736,"2026-06-30T20:49:19",9,"Местный храбрец — А я шо ведаю? Цепте все в хосподне. — *Показывает куда-то, похоже на местную корчму или таверну, она не примечательна, спряталась меж строениями.*",84732,null],[84737,"2026-06-30T20:49:53",9,"//Мучтесь с акцентом, он слегка Чешкий)))",84658,null],[84738,"2026-06-30T20:50:38",32,"//не мучайся от него прямо не удобно всем",84737,null],[84740,"2026-06-30T20:51:12",9,"//Сорян, люблю такое, стараюсь щас менее выраженым его сделать",84658,null],[84750,"2026-06-30T20:54:20",32,"- не поверишь но изначально туда направлялся.",84658,null],[84753,"2026-06-30T20:55:16",32,"-До свидания. \n(По прощался с селянином и двинулся куда послали. Держа аристократическую осанку и вид хозяина положения",84658,null],[84761,"2026-06-30T20:57:22",42,"°ходит рядом, руки в карманах, идëт безоботной походкой°\n— и тааак.. Сэээр Ариинар великий. Есть план по уничтожению чудовища?",84658,null],[84763,"2026-06-30T20:57:51",9,"*Таверна? Скорее корчма, людей сейчас тут мало, но вот корчмарь на месте. Он взглянул на гостей и назмурил брови увилев драконида.*\n\nКорчмарь — Добре. Драконыда пустылы. Ты ш наверне с другом. — *У корчмаря акцент менее выражен, общается часто с путниками наверное.*",84658,null],[84764,"2026-06-30T20:58:04",32,"-По уничтожению? Нет. По унижению, вполне",84658,null],[84768,"2026-06-30T20:59:56",42,"— о! Выпивка.. Добрый господин, что у вас есть? \n°жадно выглядывает алкогольные напитки°",84658,null],[84769,"2026-06-30T21:00:08",32,"-Доброе я Арминар. Из клана Керрилон. А это мой товарищ...(Перебирает в памяти ища имя тифлинга) Майло.\nМы тут не далеко сидели как узнали о том что тут дракон где-то объявился. Вот ищем",84763,null],[84770,"2026-06-30T21:00:28",9,"Корчмарь — Ешть, отчшего бы не быть.",84768,null],[84775,"2026-06-30T21:01:18",42,"— мне пожалуйста самое горячее что у вас есть\n°сел за барный столик°",84770,null],[84776,"2026-06-30T21:02:00",9,"Корчмарь — От чего се, не помощь драку часом? — *Крутит ус, с подозрением, а потом приносит чё поесть.*",84769,null],[84777,"2026-06-30T21:02:43",9,"*Тебе ставят какую-то настойку с травами, он слегка красновата.*",84775,null],[84778,"2026-06-30T21:03:23",32,"- у вас молоко есть? (Спросил драконорожденный) Я бы попил",84776,null],[84779,"2026-06-30T21:03:49",42,"°беру и выпиваю°",84777,null],[84781,"2026-06-30T21:05:59",32,"-Ну и собственно о драконе рассказ послушал. \nЦвет чешуи, форма морды, размер и характер. Где примерно обитает и куда прилетит за данью",84778,null],[84782,"2026-06-30T21:06:08",9,"*Тебе ставляют стаканище молока.*",84778,null],[84783,"2026-06-30T21:06:52",9,"*Печет неймоверно, точно самое горячее, та ещё дурь, кожа стала краснее, да и похмелеешь скоро, хоть и не сильно.*",84779,null],[84784,"2026-06-30T21:07:00",32,"(Арминар принялся медленно и с достоинством лакать молоко.)",84782,null],[84785,"2026-06-30T21:07:06",9,"Крчмарь — Да, горяще. — *Одобрительно кивает когда видит как за раз выхлебали напиток.*",84779,null],[84786,"2026-06-30T21:10:26",9,"Корчмарь — Так шош, в печере, в горах говорят дракон сидит, не бык, не два, как три не меньша. Крупный гадость. Где не знаю, но хитрый он сжёг пару сараев и чурам людэй отдать ему всё злато. В дячве тыхо, их превосходства небыло, тошько их преимущество, да не сдюжели искать пошли парни.",84658,null],[84791,"2026-06-30T21:13:22",32,"-Три не меньше. Это в ряд или по весу",84786,null],[84792,"2026-06-30T21:13:37",32,"Так как разница примерно в дохрена раз",84658,null],[84793,"2026-06-30T21:14:06",9,"Кормарь — Ток слыхал, что сказали. Сам не видывал, ребят.",84791,null],[84794,"2026-06-30T21:14:58",32,"- понятно если говорили про то что видели то скорее всего размер описывали. А это взрослый дракон по размеру",84658,null],[84795,"2026-06-30T21:15:42",32,"(Арминар задумался. Взрослого они точно не вытянут ,ну никак)",84658,null],[84801,"2026-06-30T21:17:19",42,"°почëвывает кулаки и пытается максимально громко ими прохрустеть в знак готовности к битве°\n— ух.. Чтож я буду первый в истрии тифлингом что избил дракона голыми кулаками)",84793,null],[84802,"2026-06-30T21:17:23",9,"*Дядька улыбнулся.*\n\nКормарь — Ешть у нас настоящий драк ящо адин. — *Корчмарь хитро улыбнулся, скорее с чего-то смеяшь. — Шастает он вязде, коли прибьёте его али збавитесь, и деняк дам немнога и за еду не взять.",84658,null],[84803,"2026-06-30T21:17:24",32,"(драконорожденный медленно длинным языком лакал молоко. И думал что влетели они по крупному)",84658,null],[84804,"2026-06-30T21:17:45",42,"/r 1d20 +6 сила на то как громко прохрустит кулак",84658,null],[84806,"2026-06-30T21:17:59",42,"// как раз избавлюсь от рака кубов",84658,null],[84808,"2026-06-30T21:18:31",42,"// чувствовал пидора, прятался за броском",84805,null],[84809,"2026-06-30T21:18:34",32,"//а кстати мне знамения кинуть. 2 д20",84658,null],[84811,"2026-06-30T21:18:55",32,"/roll 2d20",84658,null],[84813,"2026-06-30T21:19:03",9,"*Тифлинг ушёл в скрытность.*",84805,null],[84814,"2026-06-30T21:19:26",32,"//разве?",84813,null],[84815,"2026-06-30T21:19:28",42,"// нехрена себе)",84813,null],[84816,"2026-06-30T21:19:55",9,"//Ну он пытался быть громким и выбросил 1)))",84814,null],[84817,"2026-06-30T21:20:05",32,"//Отличные кубы кстати. Два промаха по мне",84812,null],[84818,"2026-06-30T21:20:33",32,"/значит не получилось у него похручтеть руки не хотят и все",84816,null],[84820,"2026-06-30T21:20:55",32,"//причем тут скрытность не понял честно",84658,null],[84821,"2026-06-30T21:21:12",42,"// ладно, пошли на дракона",84658,null],[84822,"2026-06-30T21:21:34",32,"// единички кстати от меня",84805,null],[84824,"2026-06-30T21:21:53",32,"-Слабоумие и отвага",84821,null],[84825,"2026-06-30T21:21:53",42,"— вот и отлично, пошли мой дворянский друг, надо избавиться от огнедышащей проблемы",84658,null],[84826,"2026-06-30T21:22:03",9,"//что ему скажите?",84802,null],[84827,"2026-06-30T21:22:25",32,"-Ну мы пойдем, подумаем что сможем сделать",84658,null],[84832,"2026-06-30T21:23:41",42,"— это чудно, господин ждите от нас хороших вестей",84802,null],[84834,"2026-06-30T21:24:02",32,"(мы идём искать дракона. Кину природу на поиск направления)",84658,null],[84835,"2026-06-30T21:24:02",42,"°потопал вперëд по наводке°",84658,null],[84836,"2026-06-30T21:24:11",9,"*Когды вы доели тот вышел вместе с вами и показал на кучу из дерева и хлама за домами.*\n\nКорчмарь — Тама наш маленький драк, ворюга и дебошир",84658,null],[84837,"2026-06-30T21:24:27",32,"/roll d20+3",84834,null],[84839,"2026-06-30T21:24:38",9,"//Киньте лучше анализ)",84658,null],[84840,"2026-06-30T21:25:03",42,"// ну типо тоже интелект, думаю не надо перекидывать",84838,null],[84841,"2026-06-30T21:25:04",32,"//ну тогда+2 а не +3",84839,null],[84842,"2026-06-30T21:26:26",9,"*Кормарь просит избавится от какой-то местной мелкой проблемы похожей на дракона что у них на свалке живёт.*\n\n//Понял Аминар",84802,null],[84844,"2026-06-30T21:27:09",42,"// думаю это не виверна или василиск с которыми часто путают с драконами)",84842,null],[84845,"2026-06-30T21:27:10",32,"//точнее да +3 у меня интелект. Я торможу. 21 на анализ без владения",84841,null],[84846,"2026-06-30T21:27:45",32,"//а почему мелкой?",84842,null],[84847,"2026-06-30T21:28:31",9,"//Он сам не воспринимает её слишком всерьёз, типа не с серьёзным видом просит",84846,null],[84848,"2026-06-30T21:29:34",32,"-Отлично, тогда идём мой инфернальный друг творить зло и практиковать разврат",84658,null],[84849,"2026-06-30T21:30:22",32,"(в шутку бросил Арминар и двинул в указанные направление",84658,null],[84850,"2026-06-30T21:30:25",42,"— это по адресу. Разврат и зло это для меня)",84658,null],[84853,"2026-06-30T21:31:41",32,"//дуэт на одной волне",84658,null],[84854,"2026-06-30T21:33:28",9,"*На свалке разбитые телеги, прогнившее дерево и всякий хлам, но выделяется куча что напоминает гнездо или хатку бобра, судя по всему уже не первая ведь рядом есть места где горели большие костры. Что-бы там ни жило селяни не могли это выкурить сами. Из кучи были видны норы, пролезет туда едва существо маленького размера, пока тихо.*",84658,null],[84855,"2026-06-30T21:35:07",32,"-у меня есть план! Давай его позовём.\n(Распечатывает несколько своих пайков с сушеным мясом)",84658,null],[84856,"2026-06-30T21:35:49",42,"— ну давай\n°малой иллюзией создаю запах от пайков на много вкуснее и свежее°",84658,null],[84857,"2026-06-30T21:35:51",32,"(и выставляет бухлишко накрывая поляну)",84658,null],[84858,"2026-06-30T21:36:57",9,"*Пока тихо, из кучи нет и звука.*\n\n//Вы шумите или ждёте с моря погоды тихо?",84658,null],[84859,"2026-06-30T21:37:29",32,"//Шумим и ждём с моря погоды. \nДолгий отдых",84658,null],[84861,"2026-06-30T21:38:09",32,"Развели костерок и занимаюсь готовкой за одно толкая мотивирующие речи.\n/Воодушевляющий лидер+4 временных ХП",84658,null],[84862,"2026-06-30T21:38:09",9,"//Ну, не понимаю, вы пытаетесь позвать кого-то? Именно звук",84658,null],[84864,"2026-06-30T21:38:40",32,"//Запах в первую очередь. Рептили ОЧЕНЬ чувствительны на запах.",84658,null],[84865,"2026-06-30T21:39:26",42,"//да вы шарите в рептилиях. Моë почтение",84864,null],[84866,"2026-06-30T21:40:02",32,"//Он тут был по гнездам и туннелям понятно. Что мы там не пролезем но там обитаемо",84862,null],[84869,"2026-06-30T21:40:23",42,"— чтож, приманка есть, я еë усилил запахом, осталось только ждать\n°отошëл и спрятался за мусором°",84658,null],[84873,"2026-06-30T21:41:17",42,"— если это вирм. Будет тяжко друг мой, мелкие.. Но очень опасны слышал такой повалил наших двух монахов в одиночку",84658,null],[84875,"2026-06-30T21:41:52",32,"-Ели будет вирм я его просто покормлю. Не собой естественно",84658,null],[84876,"2026-06-30T21:42:33",32,"-У меня ещё мясо есть а ещё возможность поговорить",84658,null],[84878,"2026-06-30T21:42:56",42,"— пхпхп.. я не вкусный сразу скажу. Зубы повыбиваю обоим\n°тихо и едино смеëтся Майло°",84875,null],[84895,"2026-06-30T21:47:38",32,"//это кто?",84894,null],[84896,"2026-06-30T21:47:40",9,"*Дело заняло около часа пока хозяин кучи проснулся от дрёмы и учуял запах с шумом, послышался шум, некто вылез на кучу, гордо, на четвереньках, а потом стал и пошёл на своих двоих медленно слезая.*\n\nБагровый кобольд (Иму) — Агггрррррр!!! Вы принесли дань дракону! Смертные не такие глупые как казалось, наконец-то познали величие великого Иму... — *Медленно спускается с кучи, гордо, его глаза блестят интересом, воодушевлением и верой в собственные силы.*\n\n*Часто кобольды имеют крылья или их залатки, этот же... был без них вообще, будто их небыло никогда. Взглянув ближе виднополную наивность в глазах и раны, похоже его шпыняют.*",84658,null],[84897,"2026-06-30T21:49:09",32,"(Арминар открыл рот. Закрыл ещё раз открыл и всё-таки задал вопрос) ааа. дракон где?",84658,null],[84898,"2026-06-30T21:49:57",42,"°увидев эту картину Майло начал угарать как не в себя°\n—КОБОЛЬД?!? ЫХЫХЫХЫЭЭВЭАЭАЭАЭПЭАЭАЭАЭАЭ",84658,null],[84900,"2026-06-30T21:50:34",32,"-Рааа (взревел Арминар вполне драконим рыком)\n//Запугивание",84658,null],[84901,"2026-06-30T21:50:44",32,"/roll d20+2",84658,null],[84903,"2026-06-30T21:51:19",32,"-Я задал вопрос!? Где дракон!\n(Надавил на кобольда)",84658,null],[84904,"2026-06-30T21:51:27",42,"— ух бля.. Не зря ты вожак у себя. От дракона не отлечить",84658,null],[84907,"2026-06-30T21:52:10",42,"// кстати можешь на драконем, я его понимаю",84658,null],[84909,"2026-06-30T21:52:34",32,"(указывает пальцем напротив себя чтобы Кобольд сел)",84903,null],[84911,"2026-06-30T21:52:54",9,"//Ну, ща сек",84658,null],[84912,"2026-06-30T21:52:55",32,"//можешь на инфернальной я его понимаю",84907,null],[84916,"2026-06-30T21:56:44",9,"/roll +d20+4 попадание по Арминару из за расовой абилки рёв с преимуществом",84658,null],[84918,"2026-06-30T21:56:50",9,"*Ты видишь только внезапную агрессию, думаю стало ясно, запугивание не сработало, это не простой кобольд, а тот кто не подчиняется... никому и никогда.*\n\nБагровый кобольд (Иму) — АААПГГГГГГГГААААААААГГГРОААА. — *Раздается рёв, СИЛЬНЫЙ, ГОРДЫЙ, НЕПРЕКЛОННЫЙ, СЛОВНО В ЕГО ТЕЛЕ СКРЫТ НАСТОЯЩИЙ МАЛЕНЬКИЙ ДРАКОН.*\n\n//Рёв дракона, неповиновение и сори у этого кобольда имун к испугу и чувству самосохранения",84658,null],[84920,"2026-06-30T21:57:45",9,"*Кобольд бросается и пролетает мимо в прыжке, озлобленный, словно увидел конкурента, зверь у которого пришли отжать територию.*",84658,null],[84921,"2026-06-30T21:57:54",9,"//Если сражаемся — иня",84658,null],[84928,"2026-06-30T21:59:18",9,"//Не заметили как слишком уверенно он себя вёл кстати?)",84896,null],[84933,"2026-06-30T22:00:20",32,"-Слушай ещё раз. Ты кто?\n(Спокойно ответил сидящий Арминар лениво отклонил кривой удар)\n(Ещё раз попытается атаковать отложенное действие громовая волна)",84658,null],[84935,"2026-06-30T22:01:01",32,"//Арминар не настроен на бой но если будешь бросать иню за кобольда то у него 4 знамение однако",84658,null],[84937,"2026-06-30T22:01:16",42,"°встаю в стойку и делаю распряжку, заслоняя своего напарника своим телом°\n— вижу ты предпочитаешь кулаки, выбор истинного мужчины",84658,null],[84942,"2026-06-30T22:02:13",32,"(телепатия)-Лучше стань сбоку от меня. Иначе магией задеть могу",84937,null],[84943,"2026-06-30T22:02:38",9,"Багровый кобольд (Иму) — Я Иму... зачем ты пришёл в логово дракона. — *Гарчит, по нему видно что он истинно верит в свои слова. На вид этому кобольду лет так под 19 что доволе много.*",84658,null],[84947,"2026-06-30T22:03:38",32,"-Ладно продемонстрируй дракона. Кобольда я слушать не буду.",84658,null],[84950,"2026-06-30T22:04:28",42,"(Голосом искренним от радости) — Уж не.. Видно и так что он борец по жизни, магия лишь оскорбит поединок сильнейших. Да? Иму.",84942,null],[84951,"2026-06-30T22:05:15",9,"//Цель? Спровоцировать?)",84947,null],[84952,"2026-06-30T22:05:54",32,"//не реально прошу его показать вдруг дракон в гуманоидом облике",84951,null],[84953,"2026-06-30T22:06:36",32,"//пусть запрос этот.\nАрминар сидит на старом поломаном кресле как на троне",84658,null],[84956,"2026-06-30T22:07:28",9,"//Я опять путаюсь, ладно, пусть и кольльд тоде, иня так иня)",84658,null],[84957,"2026-06-30T22:07:48",42,"// кх кх, ответ будет от моего оппонента?",84950,null],[84958,"2026-06-30T22:07:50",32,"Как я уже заявлял у кобольда 4 иня",84658,null],[84959,"2026-06-30T22:08:01",9,"*Видя провоцирующее поведение он настроился на сражение.*",84953,null],[84961,"2026-06-30T22:08:10",9,"//А ваша?)",84958,null],[84962,"2026-06-30T22:08:39",32,"/roll d20+2",84658,null],[84965,"2026-06-30T22:08:42",42,"// я побеседывать хотел немного с Иму перед боем",84658,null],[84966,"2026-06-30T22:08:53",42,"/r 1d20 -1",84658,null],[84968,"2026-06-30T22:09:19",9,"//Инициатива:\n\nАминар 22\nМайло 6\nИму 4",84658,null],[84975,"2026-06-30T22:10:45",9,"//Это он сейчас, раздраконеный)",84974,null],[84976,"2026-06-30T22:11:08",42,"// кобольдов мы за драконов не воспринимаем)",84975,null],[84978,"2026-06-30T22:11:34",9,"//Иму пох,он искренне верит что дракон)",84658,null],[84979,"2026-06-30T22:11:50",9,"//Аминар?",84658,null],[84981,"2026-06-30T22:12:07",42,"// надеюсь не будет как с орками из вахи.. Верит что дракон и рил со статами дракона",84978,null],[84984,"2026-06-30T22:12:52",32,"-Ладно. В нашем бою действительно магия будет лишней. \n(Арминар срывается с места неуловимым глазу движением и пытается сбить с ног и захватить)\n(Действие захват)",84658,null],[84985,"2026-06-30T22:13:05",32,"/roll d20 -1",84658,null],[84989,"2026-06-30T22:13:24",32,"?",84986,null],[84990,"2026-06-30T22:13:51",32,"Если что попытка вырваться у иму будет 5 если у меня получилось схватить",84658,null],[84991,"2026-06-30T22:14:00",9,"//это эффект что двигает или сбивает с ног?",84658,null],[84993,"2026-06-30T22:14:22",9,"//А, тогда получилось, опиши",84658,null],[84994,"2026-06-30T22:14:28",32,"Я хочу его заломать",84658,null],[84996,"2026-06-30T22:15:05",42,"// какая вкусняшка.. У меня преимущество по захваченным врагам)",84658,null],[84997,"2026-06-30T22:15:09",9,"/roll 1d20+4 сопротивление захвату атлетика",84658,null],[84999,"2026-06-30T22:15:25",32,"/ Арминар срывается с места как дракон в броске мгновенно неожиданно и с силой которую не ожидаешь от мага. Проскальзывает за спину и заламывает руки",84658,null],[85000,"2026-06-30T22:15:34",32,"Сопротивление захвату",84990,null],[85001,"2026-06-30T22:15:43",32,"У него 5 я это заявлял",84658,null],[85002,"2026-06-30T22:16:07",9,"Багровый кобольд (Иму) — Грррррр...",84658,null],[85003,"2026-06-30T22:16:20",32,"Опрокидывает на живот и вцепляется клыками пасти в шею.\nУкус",84999,null],[85004,"2026-06-30T22:16:30",32,"(урон ?",84658,null],[85005,"2026-06-30T22:16:37",9,"//Это разве не действие?",85003,null],[85006,"2026-06-30T22:16:48",9,"//Захват это действие",84658,null],[85007,"2026-06-30T22:17:01",32,"А опрокидывание то же?",84658,null],[85008,"2026-06-30T22:17:08",9,"//Да",84658,null],[85009,"2026-06-30T22:17:08",42,"// да, действие. Только с моей чертой это бонусное",85006,null],[85010,"2026-06-30T22:17:14",9,"//Что то одно ток)",84658,null],[85011,"2026-06-30T22:17:15",32,"Не знал тогда не опрокидывает",84658,null],[85012,"2026-06-30T22:17:42",42,"// захвати просто, будут приколы от Майло",84658,null],[85013,"2026-06-30T22:17:47",32,"А именно захватывает и кусает. Показывая доминирование",84658,null],[85015,"2026-06-30T22:18:37",9,"*Кобольд лишь сильнее злится.*",85013,null],[85016,"2026-06-30T22:19:02",32,"(укус наносит урон? Или то же отдельное действие",85015,null],[85017,"2026-06-30T22:19:13",42,"// действие",85016,null],[85018,"2026-06-30T22:19:25",32,"Ну и пох пусть будет косметики ради",84658,null],[85019,"2026-06-30T22:19:27",42,"// у дампиров это бонусное",84658,null],[85020,"2026-06-30T22:19:48",32,"//не кровосись становится не хочу",84658,null],[85021,"2026-06-30T22:19:50",9,"//У людоящеров вродь тоже, не помню",84658,null],[85022,"2026-06-30T22:20:00",9,"//Ход?",85020,null],[85023,"2026-06-30T22:20:24",32,"Да у меня нечем реализовать дополнительное",84658,null],[85024,"2026-06-30T22:20:50",9,"//Пиши когда ход оканчиваешь, мы не умеем читать мысли",84658,null],[85025,"2026-06-30T22:21:11",32,"Пардон забыл маленько",85024,null],[85026,"2026-06-30T22:21:13",42,"// так, готовы к ora ora ora?",84658,null],[85027,"2026-06-30T22:21:20",32,"Ходи",85026,null],[85028,"2026-06-30T22:21:43",32,"//делай эму стайное доминирование",84658,null],[85030,"2026-06-30T22:22:02",32,"Я жду",84658,null],[85034,"2026-06-30T22:22:45",42,"°подходя к кобольду Майло разминает плечи и кулаки°\n— так.. Глаза, горло, пах.. А вось с драконами это прокатит",84658,null],[85035,"2026-06-30T22:22:59",9,"//Где мои двойки ^^",84658,null],[85036,"2026-06-30T22:23:38",42,"/r +d20 +6 удар в корпус\n/r +d20 +6 бонусным удар в шею локтëм",84658,null],[85039,"2026-06-30T22:24:02",9,"//Бонусным ты как ударил?",84658,null],[85040,"2026-06-30T22:24:23",42,"//у меня уровень монаха после удара кулаком могу ещë раз",84658,null],[85041,"2026-06-30T22:24:36",9,"//Бонусный попал",84658,null],[85042,"2026-06-30T22:24:41",32,"/Град ударов? Так это две бонусных атаки даёт",85039,null],[85043,"2026-06-30T22:25:00",42,"/r 1d8 +4",84658,null],[85045,"2026-06-30T22:25:23",42,"// у меня первый уровень монаха и воина",85042,null],[85046,"2026-06-30T22:25:30",9,"*Кобольд чуть не потерял сознание, но всё ещё огрызается.*",84658,null],[85047,"2026-06-30T22:25:33",32,"//А не дохрена у кобольда без брони КД?",84658,null],[85048,"2026-06-30T22:25:55",42,"// у него класс монаха стопудово, защита без доспехов",85047,null],[85049,"2026-06-30T22:26:26",9,"//Кинь анализ, ты еготщупаешь",85047,null],[85050,"2026-06-30T22:26:30",42,"// смотри чтобы он тебя в захват не перехватил, а то будет больно",85047,null],[85051,"2026-06-30T22:26:37",32,"/Сейчас на сопротивление захвату тебя твои двойки догонят",85046,null],[85052,"2026-06-30T22:26:56",32,"/roll d20+3",85049,null],[85054,"2026-06-30T22:27:24",32,"//В любом случае сначала хожу я.",84658,null],[85055,"2026-06-30T22:28:53",9,"*Его чешуя слишком крепка для кобольда, блестит и отливает багровым, в генах явно затесалось что-то от красного дракона.*\n\n//Черта драконья шкура",85053,null],[85056,"2026-06-30T22:29:11",9,"//Почему? Ход иму теперь)",85054,null],[85058,"2026-06-30T22:29:39",9,"/roll 1d20+4 безоружный по дракониду",84658,null],[85060,"2026-06-30T22:30:24",9,"/roll 2d4+3 урон когтями, крепкими, раздирающими шкуру",84658,null],[85064,"2026-06-30T22:30:48",9,"/roll 1d20+4 бонусным делает захват в ответ, черта драчун",84658,null],[85070,"2026-06-30T22:31:38",9,"*Кобольд сильнее, намного В НЁМ БЕЩМЕРНАЯ МОЩЬ ДРАКОНА!*\n\nБагровый кобольд (Иму) — АГГГГГРРРАААА, ТЫ УСОМНИЛСЯ В МОЕЙ СИЛЕ!",84658,null],[85071,"2026-06-30T22:31:46",32,"//Она доступна (черта) только драконорожденым. Я могу скрин с книги скинуть",85055,null],[85072,"2026-06-30T22:31:47",9,"//Ход закончен",84658,null],[85076,"2026-06-30T22:32:19",32,"Но вообще похрен",85071,null],[85077,"2026-06-30T22:32:19",9,"//Произвол мастерской, а я могу скинуть правила у нас, если логично описанно кобольж тоже может взять",85071,null],[85079,"2026-06-30T22:32:28",42,"// походу у него просто в отличии от кобольдов других больше драконей воли и крови",85071,null],[85080,"2026-06-30T22:32:53",42,"// + лорно изгнаные кобольды сильны как драконорождëнные",84658,null],[85083,"2026-06-30T22:33:30",32,"//Ладно мой ход. Как он меня держит и где находится",85077,null],[85085,"2026-06-30T22:33:59",9,"*Он вшрызается в тебя в ответ и тгже берет в захват.*\n\n//Пока всё",84658,null],[85086,"2026-06-30T22:34:12",9,"//Ну и 7 урона от крита",85061,null],[85087,"2026-06-30T22:35:01",9,"//Не, ну сомневаюсь что ты перекинешь 23, можешь попытаться атлетика или акробатика против захвата",85065,null],[85088,"2026-06-30T22:35:04",32,"//как именно захват меня ограничивает ,я могу двигать головой?",85085,null],[85089,"2026-06-30T22:35:29",32,"//У меня максимум 19 потому даже пытаться не буду",85087,null],[85090,"2026-06-30T22:36:11",32,"Я просто дыхну в него драконим дыханием (бонусное кстати)",84658,null],[85091,"2026-06-30T22:37:42",9,"//Ебашь, наверное, захват делает скорость 0 просто",84658,null],[85092,"2026-06-30T22:37:43",9,"//Хотя , наверное майло прямо перед тобой тоже)",84658,null],[85093,"2026-06-30T22:38:05",32,"//Он же мне заспину переместился чтобы заломать?",84658,null],[85094,"2026-06-30T22:38:32",9,"//Ты его держишь ещё, он просто в ответ тоде сделал",84658,null],[85095,"2026-06-30T22:38:53",9,"//Он у тебя в захвате, ты у него. Вы крепко обнимаетесь )",84658,null],[85096,"2026-06-30T22:39:23",42,"// захват ещë и заклинания не даëт делать которые требуют голоса если захват был объявлен как удушающий",85091,null],[85097,"2026-06-30T22:39:42",9,"//Как удушающий не обьявлен",84658,null],[85098,"2026-06-30T22:39:52",32,"//Ну тогда я к нему лицом и против товарища так как изначально мы напротив стояли",84658,null],[85099,"2026-06-30T22:39:53",32,"//я потому и спрашивал но у меня дыхание и без компонентов",84658,null],[85100,"2026-06-30T22:39:53",9,"//Кобольд слишком туп для тактики",84658,null],[85101,"2026-06-30T22:40:04",32,"/roll d10",84658,null],[85104,"2026-06-30T22:40:13",42,"// ну в общем ситуация что и ты в его захвате тебе не выгадна, так что ситуация такая",84658,null],[85106,"2026-06-30T22:40:30",9,"//Спас ловкости?)",85102,null],[85107,"2026-06-30T22:40:41",32,"А смысл? 13",85106,null],[85108,"2026-06-30T22:40:45",9,"/roll 1d20",84658,null],[85110,"2026-06-30T22:41:33",32,"Дыхание лицо в лицо но у меня основное действие укус",84658,null],[85111,"2026-06-30T22:41:40",32,"Ещё есть",84658,null],[85112,"2026-06-30T22:41:42",9,"*Кобольд лишь шипит.*",84658,null],[85113,"2026-06-30T22:41:57",9,"//Укус? Го безоружное. Оно через силу",84658,null],[85114,"2026-06-30T22:42:04",32,"/roll d20-1",84658,null],[85116,"2026-06-30T22:42:23",32,"/roll к4",84658,null],[85118,"2026-06-30T22:42:27",9,"//Попал, урон 1 + модификатор силы вродь)",84658,null],[85119,"2026-06-30T22:42:46",9,"//У тебя есть природное или черта?",84658,null],[85120,"2026-06-30T22:42:57",32,"Укус к4 вродь. Как минимум это логично считать как природное оружие",85118,null],[85121,"2026-06-30T22:43:07",32,"Мастерский произвол",84658,null],[85122,"2026-06-30T22:43:34",9,"//Ну, не, у кобольда черта дает д4 урон, а у тебя?)",84658,null],[85124,"2026-06-30T22:44:07",32,"А у меня нет природного оружия из-за чего помнится даже ты сокрушался когда анкету принимал",85122,null],[85125,"2026-06-30T22:44:34",9,"*Зубы на шее лишь раздражают кобольда.*",84658,null],[85126,"2026-06-30T22:44:39",9,"//Майло",84658,null],[85127,"2026-06-30T22:45:13",32,"/Ну 3 урона я нанес",85125,null],[85128,"2026-06-30T22:45:41",9,"//Даже если 2 то + мод силы то 1",84658,null],[85129,"2026-06-30T22:45:46",42,"— повторение мать.. УЧЕНИЕ!\n°Наносит опять два удара, в дыхало, а после в лбом об лоб бонусным (кучный урон) °",84658,null],[85130,"2026-06-30T22:46:21",42,"/r +d20 +6 в дыхало\n/r +d20 +6 лбом об лоб",84658,null],[85132,"2026-06-30T22:46:55",9,"//Обе попали, даже без урона 5 будет точно, ты его собираешься убить или вырубить?",84658,null],[85133,"2026-06-30T22:47:34",42,"°ударом лбом об лоб я его вырубаю и его глаза закатились в веки в знак того что он не в сознании°",84658,null],[85134,"2026-06-30T22:49:24",9,"*Даже не смотря на то что кобольд потерял сознание, когти его всё ешё слабо сжимают Арминара.*",84658,null],[85135,"2026-06-30T22:49:39",9,"//Нарративно чисто",84658,null],[85136,"2026-06-30T22:49:49",32,"Скинул обмякшего кобольда с себя. Накинул на себя \"псевдожинь\"",84658,null],[85137,"2026-06-30T22:50:00",32,"/roll d4+4",84658,null],[85139,"2026-06-30T22:50:40",32,"Бонусных хита. Сейчас 9 родных+7",84658,null],[85140,"2026-06-30T22:51:06",42,"// 24 родных)",84658,null],[85141,"2026-06-30T22:51:27",32,"/Осматриваю кобольда и беру его кровь в пробирку сцеживаю склянку.",84658,null],[85142,"2026-06-30T22:51:37",32,"Аккуратно чтобы не добить",84658,null],[85143,"2026-06-30T22:52:00",32,"//на первом уровне?\nИ 4 бонусных от моего вдохновения",85140,null],[85144,"2026-06-30T22:52:28",42,"// не, у меня уже уровень монаха и воина, я второй лвл",85143,null],[85145,"2026-06-30T22:52:50",32,"//А точняк пардон... А нахрена?",85144,null],[85146,"2026-06-30T22:53:08",32,"/Хотя не важно.",84658,null],[85147,"2026-06-30T22:53:27",32,"/Что дальше?",84658,null],[85148,"2026-06-30T22:53:30",42,"// воин стиль боевой на кулаки, монах чтобы чаще ими стукать",84658,null],[85149,"2026-06-30T22:53:58",32,"//Так монах второго уровня был бы сильнее из-за Ки",85148,null],[85150,"2026-06-30T22:54:17",42,"// урон, в флуде это обсудим",84658,null],[85151,"2026-06-30T22:55:10",42,"— так.. Нууу всë? Хотя честно, я желал с ним 1 на 1 сразиться. Ну ладно. Есть верëвка?",84658,null],[85152,"2026-06-30T22:55:10",32,"Драконорожденный сцеживал собирал в пробирку кровь кобольда.\n-И что дальше, с ним делать?",84658,null],[85153,"2026-06-30T22:55:28",32,"-Держи (передаю моток)",84658,null],[85154,"2026-06-30T22:55:48",42,"°связываю кобольда на крепкие узлы°",84658,null],[85155,"2026-06-30T22:56:37",42,"— что дальше. А тут два пути, либо мой азарт возьмëт вверх или сдадим его жителям",84658,null],[85157,"2026-06-30T22:58:05",32,"-Азарт? давай бери! \nЯ отдаю его на твои... Что бы ты там не задумал",84658,null],[85158,"2026-06-30T22:58:51",42,"— пхпхпхехе.. Он меня заинтересовал. Хочу реванш, 1 на 1",84658,null],[85159,"2026-06-30T22:59:25",32,"(Касаюсь товарища применяя и на него псевдожинь)",85158,null],[85161,"2026-06-30T22:59:42",42,"°связав его я привожу его в чувства и набором травника отхаживаю синяки от моих ударов°",84658,null],[85162,"2026-06-30T23:00:00",32,"/roll d4+4",85159,null],[85164,"2026-06-30T23:00:05",42,"/r 1d20 +5 набор травника медицина",84658,null],[85166,"2026-06-30T23:00:28",9,"//Псевдожизнь ток на себя, к сожалению",84658,null],[85167,"2026-06-30T23:01:07",42,"// да и Майло бы отказался, бить нечестно одно, но так жульничать не позволит себе",84658,null],[85168,"2026-06-30T23:01:25",9,"//Цель?",85165,null],[85169,"2026-06-30T23:02:34",42,"// лечение от травм набором травника, то есть хилю его на фулл хп или от болезней и недугов лечу если это было сделано за отдых, какой, не важно",85168,null],[85170,"2026-06-30T23:03:03",9,"//1 хит когда встанет",85169,null],[85171,"2026-06-30T23:03:07",9,"/roll 1d20+4 первое что сделал Иму когда очнулся попытался разорвать верёвки",84658,null],[85173,"2026-06-30T23:03:54",9,"*Кобольд очнулся только спустя час, и первое что он предпринял — попытка вырваться. А сейчас он всё ещё связанный недобро на вас смотрит.*",84658,null],[85174,"2026-06-30T23:05:04",42,"— иму? Хорошее имя для дракона. В моих глазах ты заслуживаешь этот титул. \n°продолжаю обрабатывать его синяки°",84658,null],[85175,"2026-06-30T23:05:55",9,"*Молчит, не вырывается. Явно обиделся, очень.*",84658,null],[85176,"2026-06-30T23:06:03",32,"Посмотрел да на себя",85166,null],[85177,"2026-06-30T23:07:08",32,"-Слушай Майло а у тебя кинжал есть?",84658,null],[85178,"2026-06-30T23:07:25",42,"— знаешь, я обычно предпочитаю драться за еду.. Но как займусь с твоими травмами я обещаю. Как подобает дракону и монаху что был в храме и чтил их я поднесу тебе дары",85175,null],[85179,"2026-06-30T23:07:28",32,"Мне бы не помешал",84658,null],[85180,"2026-06-30T23:09:00",42,"— я презираю холодное оружие. Есть только лëгкие молоты в случае если я вправду попаду в передрягу \n°заканчивает лечение лба, натирая его травами что смягчает боль и восстанавливает то кожу, то чешую°",85177,null],[85181,"2026-06-30T23:09:53",9,"*Выражения лица не поменялось, но видя что его не бьют успокоился. Видно что не сильно сообразительный малый.*",85178,null],[85182,"2026-06-30T23:10:43",9,"//Я могу хиты кобольжа за корокий кинуть, если это цель",85180,null],[85183,"2026-06-30T23:10:46",32,"-Ну ок. \n(Спокойной пожал плечами драконорожденный и развалился на чем-то подходящем для отдыха лёжа.)\nЕсли что отложенное действие погребальный звон в кобольда если нападет на меня",84658,null],[85184,"2026-06-30T23:11:06",42,"// давай и добавь ему мой модификатор медицины +5",85182,null],[85185,"2026-06-30T23:11:15",42,"// это от набора травника",84658,null],[85186,"2026-06-30T23:11:28",9,"/roll 2d6+2+5",84658,null],[85188,"2026-06-30T23:12:07",32,"//Хе-хе-хе. Драконья стойкость говорите?",84658,null],[85189,"2026-06-30T23:12:54",42,"// да у мастера рак кубов)",84658,null],[85190,"2026-06-30T23:13:00",9,"*Раны всё ещё тревожат его, на теле видны соеды от вил, старые ожоги, шрамы где немного отсутствует чешуя. Вы не первые.*",84658,null],[85191,"2026-06-30T23:13:47",32,"//ну он сам напросился",84658,null],[85192,"2026-06-30T23:13:48",9,"Иму — Настоящий дракон не попадает в плен...",84658,null],[85193,"2026-06-30T23:14:22",32,"Ты не дракон дебила кусок. Ты Кобольд пусть и повезло тебе с природной броней.",85192,null],[85194,"2026-06-30T23:14:34",32,"(убеждение есть смысл кидать?)",84658,null],[85195,"2026-06-30T23:15:03",9,"*Недобро смотрит.*\n\nИму — Я дракон! Так было написанно в книге.",85193,null],[85196,"2026-06-30T23:15:34",42,"— потрепали тебя дружище. Извиняй что так, нам сказали что ты местному люду спокойной жизни не даëшь и пугаешь их. Чем ты не дракон если заставил их нанять людей на тебя охоту? Гордись и не слушай его. Шумиху ты создал как настоящий дракон",84658,null],[85198,"2026-06-30T23:15:49",32,"-Какой книге? (Подобрался драконорожденный и заметно оживился хоть так и не встал с лежанки)",85195,null],[85199,"2026-06-30T23:16:03",9,"Иму — Папа.",85198,null],[85200,"2026-06-30T23:16:46",9,"Иму — У него было много книг на столе. Я смог достать одну и читал.",84658,null],[85201,"2026-06-30T23:17:58",32,"-Да неужели ты умеешь читать? (Ирония так и лилась в ядовитый сарказм) Ты выделяешься среди большинства молодых драконов таким навыком",84658,null],[85202,"2026-06-30T23:18:20",32,"//(но не озвучил) в худшую сторону",84658,null],[85203,"2026-06-30T23:18:57",32,"Покажешь книгу? И кто твой папа?",85200,null],[85204,"2026-06-30T23:18:57",9,"Иму — Умею. — *Вообще ноль в подтексте сказанного, похоже принял за похвалу.*",85201,null],[85205,"2026-06-30T23:20:00",9,"Иму — Всё осталось дома. Я ушёл чтобы вырасти настоящим драконом, дом стал слишком мал.",85203,null],[85206,"2026-06-30T23:20:05",32,"//на то и был расчет Арминара он проверяет интелект и соображалку кобольда и пока получается что-то в районе 6",85204,null],[85207,"2026-06-30T23:20:23",42,"— Иму, знаешь почему я тебя вырубил и не убил?\n°резко остановил лечение как будто у него серьëзные намерения°",84658,null],[85208,"2026-06-30T23:21:00",9,"Иму — У меня нет в плену принцессы?",85207,null],[85209,"2026-06-30T23:21:40",32,"-Кажется я понял что это за книга",85208,null],[85210,"2026-06-30T23:21:45",9,"*Прозвучало как то стыдливо даже, кажется он немного стеснялся что не соответствует.*",85208,null],[85211,"2026-06-30T23:21:52",32,"(сделал Арминар фейспам)",84658,null],[85212,"2026-06-30T23:22:16",42,"— пхах.. Нет. У меня есть одна мечта подраться с драконом 1 на 1. Ты же поможешь еë исполнить? \n°начал развязывать верëвку°",85208,null],[85213,"2026-06-30T23:22:59",32,"-Если что я не участвую до последнего. Но добить товарища не дам",84658,null],[85214,"2026-06-30T23:23:39",9,"*Иму не вставал, он присел и начаш разминаться.*\n\nИму — Нет! Великий красный дракон Иму устал и хочет есть!",85212,null],[85215,"2026-06-30T23:23:41",32,"(сказал и развалился по удобнее Арминар все ещё держа некроманский заговор на готове для атаки)",84658,null],[85216,"2026-06-30T23:24:24",32,"- твоего мнения похоже не спрашивали. (Отвечаю иму)",84658,null],[85217,"2026-06-30T23:25:00",9,"Иму — Дракон требует подношений! Платите дань.",85216,null],[85218,"2026-06-30T23:25:28",42,"— справедливое требование.. Поэтому\n°развязал и тут же достал 3 рациона с мясными блюдами°\n— если ты дракон, докажи. Слышал у вас неутолимый аппетит. Если всë съешь до конца отдыха, то без сомнений я тебя буду считать драконом",85214,null],[85219,"2026-06-30T23:26:20",32,"//у нас получается классическая версия хороший и плохой но почему-то исчадие хорошее",84658,null],[85220,"2026-06-30T23:26:20",42,"// 3 отдал потому что мелкий и видно что вряд ли и 2 потянет)",84658,null],[85221,"2026-06-30T23:26:25",9,"*Хррррр. Он не знал обидать ли, злиться или радоваться еде, просто заграбастал и с недовольным лицом ест.*",85218,null],[85222,"2026-06-30T23:27:02",32,"- у драконов кстати есть этикет и манеры как принимать пищу",84658,null],[85223,"2026-06-30T23:27:07",9,"//Что же, попытка съесть рационы, 2 он с голодухи осилит, а вот 3й",84658,null],[85224,"2026-06-30T23:27:32",9,"/roll 1d20+1 телосложение чтоли на попытку сожрать",84658,null],[85226,"2026-06-30T23:27:34",32,"(решил я подразнится) великий Сардиор завещал как правильно есть.",84658,null],[85227,"2026-06-30T23:27:42",42,"// ну пускай выкручивается. Если он дракон пускай докажет это себе и мне",85223,null],[85228,"2026-06-30T23:28:38",32,"- а он был красным драконом (то что рубиновый опустим за скобки)",85226,null],[85229,"2026-06-30T23:28:57",42,"— фе.. Ваш этикет, дракон ест потому что хочет, а если хочет значит пускай рвëт, дербанит. Драконы сверх хищники и им этикет не указ. Да? Иму",84658,null],[85230,"2026-06-30T23:29:08",9,"*Иму кажется слишком обиделся на драконорожденного, даже ухом не ведёт. Спустя аж пол часа он елва но осилил 3й рацион.*\n\nИму — Я силён, настоящий дракон... — *Бурчит еле дыша.*",85226,null],[85231,"2026-06-30T23:30:11",9,"*Кивает, кажется он сейчас и не встанет, его обкормили.*",85229,null],[85232,"2026-06-30T23:31:00",32,"(телепатия только тифлинг)\n- в этом и был твой план?",84658,null],[85233,"2026-06-30T23:31:29",42,"— чтож, отдыхай. Хоть внешне ты кобольд, но скажу так.. В моëм монастыре чтят драконов и кобальдов, драконы понятно почему. А вот с кобальдами поинтереснее. Сказать почему?",85231,null],[85234,"2026-06-30T23:32:05",9,"Иму — Я дракон... — *Упёрт на 100% в своём мнении.*",85233,null],[85235,"2026-06-30T23:32:07",42,"— мой план в том, чтобы убедиться что он соответствует легендам моего бывшего монастыря",85232,null],[85236,"2026-06-30T23:32:49",32,"-Ну подыгрываю в меру сил)",85235,null],[85237,"2026-06-30T23:33:20",42,"— правильно, у нас было сказано что кобольд имеет потенциал стать драконом. Лишь сильнейшие и самые приспособленные на это способны. Так что для меня ты точно дракон",85234,null],[85238,"2026-06-30T23:35:25",9,"Иму — Грррр... я дракон... всегда. Не называй меня кобудом, что это такое? — *Он поднял палец и показал на Арминара.* — Он дракон, чешуя, хвост, зубы. Я тоже дракон, настоящий.",85237,null],[85239,"2026-06-30T23:36:00",32,"-Вроде как были легенды на это тему, но я в них не верю.\n(Использует свой отрицательный авторитет чтобы подтолкнуть уверенность кобольда что он дракон в правильном направлении)",84658,null],[85240,"2026-06-30T23:36:25",42,"— А я разве отрицал что ты дракон? Забыл что я тебе сказал. Моя мечта подраться с драконом и ты как дракон можешь мне помочь",85238,null],[85242,"2026-06-30T23:38:28",9,"*Он кивнул, попытался встать и кое как поднялся на ноги и плюхнулся назад.*\n\nИму — Грррр... — *Злится на себя, что обьелся.*",85240,null],[85243,"2026-06-30T23:39:12",9,"*Кажется вашему дракону стало немного плохо.*",84658,null],[85244,"2026-06-30T23:39:58",32,"/да и похрен. Если что могу добить из жалости",85243,null],[85245,"2026-06-30T23:40:24",9,"//Такое разное отношение 😂👍",84658,null],[85246,"2026-06-30T23:40:32",42,"°делаю чай мекстуру которая должна помочь от боли в животе°\n/r 1d20 +5 медицина травника",85242,null],[85247,"2026-06-30T23:40:48",42,"/r 1d20 +5 медицина травника",84658,null],[85249,"2026-06-30T23:40:54",32,"(Арминар спокойно лежит и даже не шевелится в сторону \"дракона\")",84658,null],[85250,"2026-06-30T23:41:08",42,"// получилось?",85248,null],[85251,"2026-06-30T23:42:15",9,"*Всё хорошо, вроде бы Иму стало получше. Вы таким образом провозились почти до вечера, и вскоре, вспышка на краю деревни и тень в небе.*",85248,null],[85252,"2026-06-30T23:43:35",9,"*Теперь уже точно настоящий дракон и рёв, Иму поднялся на ноги, даже чешуя стала дыбом, но это не страх, скорее, он хочет туда... но сейчас он ещё не совсем пришёл в себя.*",84658,null],[85253,"2026-06-30T23:43:39",32,"-Мечты имеют свойство сбываются друг.",85251,null],[85254,"2026-06-30T23:44:26",32,"-Вон твой дракон взрослый как я и обещал. И сильный и явно точно дракон. В общем ты иди я тебя здесь подожду",84658,null],[85255,"2026-06-30T23:44:38",9,"//?",85254,null],[85256,"2026-06-30T23:44:40",42,"— иму.. Знаешь почему вдвоëм мы справились с тобой.. А потому что ты ещë юнный дракон.. А вот он уже взрослый",85251,null],[85257,"2026-06-30T23:45:32",9,"Иму — Я знаю. У меня ещё крылья не выросли... — *Похоже он уверен что вырастут.*",85256,null],[85258,"2026-06-30T23:45:42",32,"(смеётся Арминар с \"я тебя тут подожду\" явно не намерен оставаться здесь но шутит. \n//А за одно кастую черту \"воодушевляющий лидер+4 временных хита))",84658,null],[85259,"2026-06-30T23:46:44",32,"//да я обещал эму взрослого дракона полистай в таверне рассуждал о размере трёх быков",85255,null],[85260,"2026-06-30T23:47:20",9,"//Я теряюсь сильно",85259,null],[85261,"2026-06-30T23:48:00",32,"//чего так?",85260,null],[85262,"2026-06-30T23:48:04",9,"//Обьясняйте, я щас сам туплю)",84658,null],[85263,"2026-06-30T23:48:57",32,"//там какого цвета тень? Или она просто огнем дышит?",84658,null],[85264,"2026-06-30T23:49:13",42,"— в общем, устроим с тобой договор? Обычно драконы бывают покровителями колдунов, так вот. Хотел бы ты себе последователя? Если я тебя выйграю пообещай что когда станешь сильным драконом ты станешь моим покровителем, обычно у драконов их целая куча. А если ты меня, тооо ты сам выбираешь условие",85257,null],[85265,"2026-06-30T23:49:22",9,"//Не вижу действий персонажа, сори",85263,null],[85266,"2026-06-30T23:50:20",9,"/roll 1d20-1 инта, попытка понять что ты хочешь",85264,null],[85268,"2026-06-30T23:50:52",42,"// понимает, походу у меня будет покровитель кобольд)",84658,null],[85269,"2026-06-30T23:50:57",9,"*Иму в общих чертах понял что ему надо победить.*\n\nИму — Я не проиграю.",85264,null],[85270,"2026-06-30T23:51:36",32,"//ты сам описал что мы видели. Я у тебя уточняю что именно за вспышку видели мы которая вспышка",85265,null],[85271,"2026-06-30T23:51:49",42,"— тогда сможешь рассказать какое у тебя требование если ты победишь?",85269,null],[85272,"2026-06-30T23:52:01",9,"//Вы всматриваетесь?",84658,null],[85273,"2026-06-30T23:52:09",32,"//Потому принципиально кидать не буду. Ведь ты уже начал это описывать.",84658,null],[85274,"2026-06-30T23:52:20",42,"// если что так к слову.. Видно что у меня много золота, и я его не прячу",84658,null],[85275,"2026-06-30T23:52:25",32,"//да куда блин ещё смотреть?",85272,null],[85276,"2026-06-30T23:52:27",9,"*Прикинул, подумал.*\n\nИму — Еда! Сокровища!",85271,null],[85277,"2026-06-30T23:52:58",32,"//Конечно смотрим с самого начала фейерверка. Пассивная 12",85275,null],[85278,"2026-06-30T23:53:01",9,"//Ну, привыкайте описывать, темнеет я писал",85275,null],[85279,"2026-06-30T23:53:49",9,"*В закате не совсем понятно, но тень красная и не очень то и крупная, кажется взрослый дракон покрупнее был бы.*",84658,null],[85280,"2026-06-30T23:53:56",42,"— договор\n°потянул руку для рукопожатия и принятия такого договора°",85276,null],[85281,"2026-06-30T23:54:37",9,"*Пожимает руку, он видел как такое делают. Осторожно правда, для него это новый опыт.*",85280,null],[85282,"2026-06-30T23:54:55",42,"// будет смешно если он выйграет мои 228 золотых)",84658,null],[85283,"2026-06-30T23:55:52",42,"— ну всë. Тогда спать я ложусь. С утра после завтрака решим как наш уговор пойдëт",85281,null],[85284,"2026-06-30T23:56:27",32,"-А разве мы не идём в деревню?",84658,null],[85285,"2026-06-30T23:56:40",9,"*Пока вы болтали и любовались видом на краю деревни уже горело несколько домов. А тень в небе улетела обратно. Шум, местные недовольные, с вилами и вёдрами идут тушить пожары.*",84658,null],[85286,"2026-06-30T23:57:29",32,"//Я слежу куда он/она улетела",85285,null],[85287,"2026-06-30T23:57:32",42,"— что поделаем? Иму тяжëлый. Как ни как дракон объевшиеся. Да и с деревней вряд-ли что сделаем. Ты сам говорил, с драконом нам не справиться",85284,null],[85288,"2026-06-30T23:58:20",32,"/roll d20+3 анализ",84658,null],[85290,"2026-06-30T23:58:34",9,"*Иму встал на ноги, ему уже полегчало немного.*\n\nИму — Я дойду сам!",84658,null],[85291,"2026-06-30T23:58:58",9,"//Опиши что ты анализируешь?",85289,null],[85292,"2026-06-30T23:59:40",9,"//Если это, то вообще не собираюсь душнить, без броска ясно",85286,null],[85293,"2026-06-30T23:59:45",42,"— дружище. Хоть ты дракон.. Но ты юн, твоя цель не идти на убой, а выжить чтобы стать моим покровителем. Пхпх..",85290,null],[85294,"2026-07-01T00:00:56",9,"Иму — Дракон никогда не убегает, даже от смерти. — *Видна полная уверенность в своих силах.*",85293,null],[85295,"2026-07-01T00:01:26",32,"//Ну ок тогда бросок в пустоту",85292,null],[85296,"2026-07-01T00:01:56",9,"*Это явно не взрослый дракон, по крайней мере, так кажется. Маловат будто бы.*",85295,null],[85297,"2026-07-01T00:03:18",42,"— Нам тоже это читали когда вращивали в наши души дракона. Так что считай мы все тут драконы, но я только духовно. Поспи, всем известно что во сне рост идëт быстрее [пытаюсь ему внушить идею с быстрым ростом во сне чтобы вызвать интерес на сон]",85294,null],[85298,"2026-07-01T00:04:12",32,"- как думаешь кузнец в деревне возьмётся за наш заказ? У меня есть пара идей того что мне надо",84658,null],[85299,"2026-07-01T00:04:19",9,"Иму — Драконы спят на сокровищах в своём логове.",85297,null],[85300,"2026-07-01T00:04:51",32,"(драконорожденный закинул руки за голову и расслабился)",84658,null],[85301,"2026-07-01T00:05:20",42,"°встал и высапал ему все свои сбережения и кучкую и у меня много денег чтобы сделать мини гнëздышко°\n— вот тебе ночлег на день",84658,null],[85302,"2026-07-01T00:05:32",9,"//Тупой кобольд да ещё и без инсктинта самосохранения — горе в семье",85300,null],[85303,"2026-07-01T00:05:58",42,"— так ещë настоящее злато",84658,null],[85304,"2026-07-01T00:06:12",9,"//Ты ему отдал свои сбережения?",85301,null],[85305,"2026-07-01T00:06:48",32,"//если нападёт буду считать попыткой суицида.",85302,null],[85306,"2026-07-01T00:08:10",32,"-Идём в село может поможем пожар тушить если там без нас не управчтся\n(Произнес Арминар лениво. Вставать не хотелось но и идти если что надо)",84658,null],[85307,"2026-07-01T00:09:05",42,"// нет, завтра соберу всë",85304,null],[85308,"2026-07-01T00:09:16",9,"//Ну щас то?)",85307,null],[85309,"2026-07-01T00:09:37",9,"//Что ты сделал 😏",84658,null],[85310,"2026-07-01T00:09:58",42,"// щас просто сделал ему ночлег из золота, у нас уговор. Если выйграет отдам сокровища и еду",85309,null],[85311,"2026-07-01T00:10:35",9,"//Он понял только то что вы подерётесь и скорее всего не сильно заполнил условия, ну щас",85310,null],[85312,"2026-07-01T00:11:20",9,"*Видя столь щедрое подношение... Иму выглядел так словно его купили с потрохами, просто за золото которого у него небыло.*",84658,null],[85313,"2026-07-01T00:11:26",32,"//Так ну все\nЯ спать пойду мне завтра рано вставать",84658,null],[85314,"2026-07-01T00:11:35",9,"Иму — Дар! Ты теперь мой друг!",84658,null],[85315,"2026-07-01T00:12:01",9,"*Иму будто что-то вспоминает и стаёт серьёзным.*",84658,null],[85316,"2026-07-01T00:12:23",9,"Иму — Дар, дар другу! Дар дракона, дар крови",84658,null],[85318,"2026-07-01T00:13:13",9,"*Он царапает себе руку до крови.*\n\nИму — Ешь, пей, дар дракона",84658,null],[85319,"2026-07-01T00:13:27",42,"// отмена",84658,null],[85320,"2026-07-01T00:14:09",42,"— пх.. Ну чтож, от даров дракона нельзя отказываться\n°налил крови себе в ладонь и выпил°",85318,null],[85321,"2026-07-01T00:14:11",9,"//Он себе 4 урона нанёс этим, с его то силой)",84658,null],[85322,"2026-07-01T00:14:22",42,"// надеюсь не заболею спидом",84658,null],[85323,"2026-07-01T00:14:36",9,"*Тело жжёт, странное чувство будто кровь немного кипит.*",85320,null],[85324,"2026-07-01T00:14:44",32,"//Хмм а может и мне выпить? Что даст испитие его крови?",85318,null],[85325,"2026-07-01T00:15:07",9,"//А ты откуда знаешь? Что за метагейм)))",85324,null],[85326,"2026-07-01T00:15:38",32,"/Аркану бросить? Да и я наблюдаю что с ним происходит",84658,null],[85327,"2026-07-01T00:16:23",42,"°ноу реакшн на лицо, тифлинг и так сопротивляем к огню°",85323,null],[85328,"2026-07-01T00:16:23",32,"Могу даже чувство магии кастануть",84658,null],[85329,"2026-07-01T00:16:54",9,"//Нус, вот что\n\n\"Невероятно малое благословение драконьей крови.*\n\nВы испили кровь в ходе ритуала, в ней есть кровь дракона хоть и сильно разбавленная. Ваш максимум хитов увеличивается на 1. (Аналог метки, очень слабый)",85323,null],[85330,"2026-07-01T00:17:57",42,"// это стоило 228 золотых, и жаль что после квесте кобольд исчезнет из жизни Майло)",84658,null],[85332,"2026-07-01T00:18:12",9,"//Да? Если ток умрёт)))",85330,null],[85333,"2026-07-01T00:19:11",42,"// ну я гнида.. Но это совсем не морально здорово выпить крови и убить",85332,null],[85334,"2026-07-01T00:19:50",32,"//Ладно реально до завтра",84658,null],[85335,"2026-07-01T00:19:52",9,"*Кобольд нырнул себе в нору, но золото не трогал, он достал оттуда мешок, маленький с всяким хламом и серебром.*",84658,null],[85336,"2026-07-01T00:20:52",42,"// я как надеялся что он не совсем кобольд, так и надеюсь",85335,null],[85337,"2026-07-01T00:21:14",9,"*Иму походе был намерен собрать все свои пожидки и идти за Майло хоть в огонь, хоть в воду. Дракона подкупили златом да ещё количеством которое он видел ращве что в книжках.*",84658,null],[85338,"2026-07-01T00:21:50",42,"// Ура у меня есть пет фамильяр",85337,null],[85340,"2026-07-01T00:22:24",42,"// не гоблин по имени Боблин, но не хуже",85338,null],[85341,"2026-07-01T00:23:01",42,"// уже оправдывает свои траты",85338,null],[85701,"2026-07-01T14:56:41",9,"// @Jak_Zak @Xaosick готов продолжать в любой момент, еси чо",84658,null],[85705,"2026-07-01T15:02:12",32,"Я чуть занят но буду готов в течение получаса",85701,null],[85743,"2026-07-01T15:44:57",32,"//я тут",84658,null],[85849,"2026-07-01T19:16:03",42,"/я тут",84658,null],[85850,"2026-07-01T19:18:29",9,"//Оба тут?",84658,null],[85851,"2026-07-01T19:22:38",42,"// я тута",84658,null],[85856,"2026-07-01T19:29:41",32,"//Я тут",84658,null],[85857,"2026-07-01T19:30:05",32,"//как появились и начнём пингуйте",84658,null],[85858,"2026-07-01T19:30:33",42,"// Hard всë мы тута",84658,null],[85874,"2026-07-01T20:12:07",9,"// @Xaosick @Jak_Zak что вы делаете господа",84658,null],[85875,"2026-07-01T20:13:02",32,"//в селе горят домики потому Арминар идёт туда помогать",84658,null],[85876,"2026-07-01T20:15:03",32,"//дракон пару штук поджёг ты вроде описывал",84658,null],[85877,"2026-07-01T21:08:24",42,"°Майло лëг спать°",84658,null],[85878,"2026-07-01T21:08:57",9,"*Рядышком, клубком скрутился Иму.*",85877,null],[85885,"2026-07-01T21:21:51",32,"(Арминар пошёл в деревню помогать тушить пожары. И за одно собственно после этого у меня будет возможность заказать пару игрушек для дракона)",84658,null],[85886,"2026-07-01T21:23:57",32,"(предмет. \n\"Игрушка для дракона\" \nПрямой стальной штырь с конусовидный остриём.\nДлина 20 сантиметров, ширина 3 в диаметре. \nСуть как колтроп но бальшой!\nЗакапывать в землю для аналога волчьей ямы)",84658,null],[85887,"2026-07-01T21:25:38",9,"*Вечерело, такак как Аминар пошел один, какой-то залётный крестьянин даже пригрозил ему вилами. Люди здесь уж больно боевые, даже дракона не испугались, ополчение выглядело так словно они толпой пойдут дракона бить, ток знать бы где он. Страна рыцарей.*\n\nКорчмарь — Пмешек, кыш. Давеча гость это. — *Тебя встретил знакомый усатый дядька из таверны, что спасло от нехорошей участи. Он спросил:* — Шо забув здеся?",85885,null],[85888,"2026-07-01T21:26:37",32,"(можно модифицировать конструкцию трехлепестеым остриём, зазубринами или как минимум кровостоком)",84658,null],[85889,"2026-07-01T21:27:57",9,"//Кинджал интересной формы типа? Пока разберись со сценой и спроси гдэ кузнец)",85888,null],[85890,"2026-07-01T21:29:08",32,"(Арминар немного отдышался от пробежки так как двигал в деревню в темпе) - я прибыл на помощь. Хух, Как только увидел, что дракон налетел и устроил поджоги бежал. К вам на помощь.",85887,null],[85891,"2026-07-01T21:29:33",32,"//типо просто штырь заточенный круглый прут",85889,null],[85892,"2026-07-01T21:30:34",32,"-Но видимо немного опоздал.\nЕсть пострадавшие? Я владею врачеванием, могу помочь",85890,null],[85893,"2026-07-01T21:32:13",9,"Корчмарь — Поди не мяшай. Народ злой, всех не успокоишь. — *Достал ключ из кармана и дал тебе.* — В коршме моей. Третья комната наверх, деняг не вязьму. Тако легше чем следить за всемь.",85892,null],[85894,"2026-07-01T21:34:04",32,"- спасибо тебе.\n(Арминар не глубоко поклонился выказывая максимальное возможное уважение)\nА где у вас кузнец? Мне бы заказ эму сделать, есть пара задумок по охоте на дракона",85893,null],[85895,"2026-07-01T21:35:36",9,"*Показал на какого-то мужика в фартуке что материл дракона на чем свет стоит и клялся сшить доспех из шкуры жопы этого дракона всем богам.*\n\nКорчмарь — Мятлик занят. Домъ его подожло драк как рас.",85894,null],[85896,"2026-07-01T21:39:07",32,"-Если поговоришь и скажешь эму что исторически драконорожденные и драконы слегка не в ладах и лично я хочу устроить охоту на ту зажигалку то я буду капитально должен.\n(Киваю корчмарю) Может нужна какая помощь? На кухне например или ещё что",85895,null],[85897,"2026-07-01T21:40:49",9,"Корчмарь — Завтра поговорим, пора мне. — *Похоже дядько намерен проследить здесь за всем, выглядит ответственным.*",85896,null],[85898,"2026-07-01T21:42:39",32,"-Удачи вам (киваю и иду в комнату. Нужно и самому отдохнуть)",85897,null],[85899,"2026-07-01T21:44:44",32,"Долгий отдых",84658,null],[85900,"2026-07-01T21:44:56",9,"*Утром народ подуспокоился, внизу за стойкой небольшого завидения уже стоял тот самый дядька, слегка невыспанный и уставший. Посетителей было немного.*\n\n//Да, долгий",84658,null],[85901,"2026-07-01T21:46:53",42,"// хочу заявку. Можно я проснусь раньше всех и поищу там ягоды и что-то вкусное",84658,null],[85902,"2026-07-01T21:47:02",42,"// так как лëг раньше всех",84658,null],[85903,"2026-07-01T21:47:33",9,"*Майло проснулся, ему грел спину немного колючий клубок, сам Иму, досыпал и сопел.*",84658,null],[85904,"2026-07-01T21:48:19",9,"*Самый настоящий дракон, чуть больше метра ростом, свернулся как кот.*",84658,null],[85905,"2026-07-01T21:48:24",42,"°погладил слегка по спинке Иму аккуратно чтобы его не разбудить и потопал в поисках еды°",84658,null],[85907,"2026-07-01T21:49:54",42,"/r +d20 +3 выживание примущество от набора травника на поиск съесного",84658,null],[85909,"2026-07-01T21:50:52",9,"*Корешки и травы, яблоки и земляника. Природа здесь богата на всякое, а ещё, ты заприметил змею в кустах.*",84658,null],[85910,"2026-07-01T21:51:11",42,"//инициатива?)",84658,null],[85911,"2026-07-01T21:53:22",9,"*А змея Майло пока не заметила.*",85909,null],[85912,"2026-07-01T21:54:10",42,"°тогда достаю лëгкий молот и бросаю его в неë в надежде прикончить броском°",84658,null],[85913,"2026-07-01T21:54:22",42,"/r 1d20 +6",84658,null],[85915,"2026-07-01T21:54:52",42,"/r 1d4 +4",84658,null],[85917,"2026-07-01T21:57:02",9,"*С утра пораньше, внезапно молотом прилетело в ничего не подозревающую змею. Слегка разыбало ей череп, самую малость. Тело корчится в конвульсиях и крутится, но это лишь остатки рефлексов умирающей нервной системы. Достойная добыча.*",84658,null],[85918,"2026-07-01T21:57:19",9,"//Напомни мне, твой перс же учился в монастыре? Если правильно то проверка истории сложность 11",84658,null],[85919,"2026-07-01T21:58:43",42,"/r 1d20 -1",84658,null],[85921,"2026-07-01T21:58:59",42,"// да он учился монастыре",85918,null],[85922,"2026-07-01T21:59:17",9,"*Змеиный суп, его часто варят монахи. Со змеи лишь снимают кожу, а яд оставляют, он вываривается но придаёт особый вкус.*",85920,null],[85923,"2026-07-01T22:00:36",42,"// чтож",84658,null],[85924,"2026-07-01T22:01:39",42,"°иду с добычей готовя этот суп используя корешки и травы как усилитель вкуса, яблоки порезал и вместе с яблоками землянику положил как диссерд°",84658,null],[85925,"2026-07-01T22:02:23",9,"//Я одного не пойму только, где мы сейчас, явно не в таверне. На свалке за селом чёль?",84658,null],[85926,"2026-07-01T22:02:35",42,"// да",84658,null],[85927,"2026-07-01T22:02:40",42,"// я там спал",84658,null],[85928,"2026-07-01T22:03:51",9,"*Кобольд проснулся, и сел у котелка, греется. Молчит, сонный ещё.*",84658,null],[85929,"2026-07-01T22:04:25",9,"*Но мешок с сокровищами подле себя держит.*",84658,null],[85930,"2026-07-01T22:06:22",42,"— что за мешочек у тебя? \n°продолжает варить суп добавляя разные травы для вкуса°",84658,null],[85931,"2026-07-01T22:08:20",9,"*Протирает глаза.*\n\nИму — Сокровища. Сокровищница дракона. — *Повторил, он, явно уточняя что именно там.*",84658,null],[85932,"2026-07-01T22:16:39",42,"— ну чтож.. Теперь видно что ты богатый дракон. В таком возрасте больше сотни вдове золота у тебя. Другие молодые драконы тебе бы завидовали\n°взял и налил порцию супа для Иму, после для дракона по круче и после для себя°",84658,null],[85933,"2026-07-01T22:17:27",42,"— пх.. Но как видишь ты уже побогаче этого дракона\n°с лëгкой насмешкой сказал это°",84658,null],[85934,"2026-07-01T22:17:39",32,"(тем временем Арминар) проснулся рано как приучили уроки.\nИ сделав зарядку, вышел в зал.\n-Доброе утро. Можно у вас что-нибудь поесть? Желательно мясного",85900,null],[85935,"2026-07-01T22:18:36",32,"Собственно будет завтракать и спросит.\n-Где тут у вас можно помыться? (И пойдет купаться куда пошлют",85934,null],[85936,"2026-07-01T22:18:47",9,"Иму — Могу показать, у меня есть сокровища ещё. Помимо золота.",85933,null],[85937,"2026-07-01T22:20:01",9,"*Купаться показал где, бочки с водой ща углом. Да и поесть насыпал.*\n\nКорчмарь — Утра то добра. Новости хорошия принесли. Завтра рыцари приедют, загасят змяюку. — *У дядька настроение хорошее, он рад новости.*",85935,null],[85938,"2026-07-01T22:20:41",42,"— вот завтрак\n°взял и отдал Иму порцию супа и после отложил себе и положил на земле подольце с яблоками и земляникой°",85934,null],[85939,"2026-07-01T22:21:26",9,"//Вродь Арминар в таверне, а ты на свалке, вы немного в местах разных)",85938,null],[85940,"2026-07-01T22:21:37",42,"— пх.. Ну давай, показывай. Мне безумно любопытно что у тебя за сокровища",85936,null],[85941,"2026-07-01T22:21:51",42,"// знаю, случайно это смахнул а не ответ иму",85939,null],[85942,"2026-07-01T22:22:33",32,"-новость действительно хорошая.\nЛадно я к кузнецу и похоже срочно.\n(Кивнул и после купания и ухода за собой через час с небольшим от завтрака двинулся к кузнецу)",85937,null],[85943,"2026-07-01T22:23:48",32,"//кстати утро у меня броски знамения",84658,null],[85944,"2026-07-01T22:24:00",32,"/roll 2d20",84658,null],[85946,"2026-07-01T22:26:37",9,"*Он прищурился на мгновение, словно думая, а потом кивнул, решился. Достал он значица цветные стекляшки, колбы и мелочушку всякую как металические шарики или несколько отдельных калтропов, немного серебра. Среди этого всего выделялось золото что было завернуто в несколько мешков ещё раз, точно то что Майло дал. А так странная монета что подсвечивала и стекляный шарик размером с глаз.*\n\nИму — Смотри! Стрела, её нельзя сломать. — *Он достал стелу, немного старую на вид и напряг все силы и сломать не смог, дал её Майло.* — Ты тоде не сможешь!",85940,null],[85947,"2026-07-01T22:28:12",9,"*Кузнеца небыло на месте, вместо него был подмастерье, молодой парень.*\n\nПодмастерье — Батька занет, сматри шо надо, посмотрю шо слелаю. — *Сказал он вытирая руки что почернели от обработки металла.*",85942,null],[85948,"2026-07-01T22:28:28",42,"°ну пробует поломать, но в случае если почувствует треск остановится чтобы не сломать игрушку милого дракончика°",85946,null],[85949,"2026-07-01T22:28:41",42,"/r 1d20 +6 атлетика",84658,null],[85951,"2026-07-01T22:28:52",9,"*Стрелу невозможно сломать.*",85948,null],[85952,"2026-07-01T22:29:30",9,"Иму — Ни у кого такой нет. — *Задрал нос, хвастун.*",84658,null],[85953,"2026-07-01T22:29:39",42,"— УХХХХ!.. Да ты прав. Не сломаю\n°отдал стрелу обратно°",85951,null],[85954,"2026-07-01T22:31:17",42,"— да все вы драконы хвастуны знатные, поешь. Тебе надо много сил, а рецепт супчика прямиком из моего монастыря, возможно драконам это и нравится\n°хлебает супчик°",84658,null],[85955,"2026-07-01T22:32:04",9,"*Тоже ест, предварительно упаковав всё, бережно.*",85954,null],[85956,"2026-07-01T22:32:09",32,"- здрасьте. Мне нужны мм. Вот такой длины (показыват примерно 20 сантиметров на руке кузнеца) и толщиной с большой палец.\nШтыри, скруглённые остриё с одной стороны и аналог шляпки гвоздя с другой.\nВ доль заострения выбить несколько канавок, если будут зазубрины или заусиницы хорошо их не нужно шлифовать или обрезать. \nМне надо таких штук двадцать желательно до вечера.\nСколько за штуку возьмёшь?",85947,null],[85957,"2026-07-01T22:32:59",9,"//Вопрос уже от меня, а что ты хочешь получить в итоге",85956,null],[85958,"2026-07-01T22:34:45",32,"//лепкой земли закопать в землю. В полости как у всадника скрытая яма с кольями. У логова дракона. Или там где подобное можно провернуть. И заманить дракона. Лапа тяжёлая напороться и капитально повредится. Это тебе не маленькие колтропы",84658,null],[85959,"2026-07-01T22:35:09",32,"//но вообще увидишь как это применю",84658,null],[85960,"2026-07-01T22:35:20",32,"//(или не применю)",84658,null],[85961,"2026-07-01T22:36:35",9,"*Он вытирает раки и достаёт ящик.*\n\nПодмастерье — Дроты, по пять медях за штука. Аль надо полностью металическия?",84658,null],[85962,"2026-07-01T22:36:50",9,"//Посмотри дротики)",84658,null],[85963,"2026-07-01T22:37:45",32,"//какой примерно у нашего дракона вес? Модели на 4 лапы и получишь силу сжатия в тоннах. Подсказка. Мне кажется он и стальные раздавит если у него прочность на прокол меньше чем у стали на изгиб будет",85962,null],[85964,"2026-07-01T22:38:31",9,"//Нужны калтропы на дракона?)",84658,null],[85965,"2026-07-01T22:38:48",32,"Да",84658,null],[85966,"2026-07-01T22:39:10",32,"//В общем но немного пересмотрел дизайн и отказался от противотанковых ежей",84658,null],[85967,"2026-07-01T22:40:57",9,"Полмастерье — Магу наклепать, десятка два. Коли батька придёт, паможет, то пять дясятин к вечару. По семь злотых за десять.",84658,null],[85968,"2026-07-01T22:42:50",32,"Выкладывает 21 монету и говорит.\n-Больше трёх десятин я не унесу физически. Потому столько. Спасибо за помощь.",84658,null],[85969,"2026-07-01T22:44:07",42,"— Иму если так подумать. Ты назвал меня другом, а знаачит.. Будет сложно, с друзьями я не дерусь. А наоборот защищаю",85955,null],[85970,"2026-07-01T22:44:28",9,"Подмастерье — Сделаю, не сделаю деньгу вярну.",85968,null],[85971,"2026-07-01T22:46:14",9,"Иму — Драконы сильнее всех! Им не нужна помощь. — *Потом задумался, и добавил:* — Хотя рыцари сильнее.\n\n*Явно вдохновившийся сказками о драконах уже и ежу понятно.*",85969,null],[85972,"2026-07-01T22:47:23",32,"(Арминар тепло распрощался с подмастерьем и двинулся к напарнику на свалку.)",85970,null],[85973,"2026-07-01T22:48:19",9,"*Застал Иму и Майло, сидят и доедают змеиный суп.*",85972,null],[85974,"2026-07-01T22:50:13",42,"— пхпхпххпахахаха..! Не смеши меня с утра Иму.. \n°протирает слезу от смеху и патает по голове°\n— рыцари не сильнее взрослого дракона. Я сам могу рыцаря с лëгкостью избить кулаками, а прям дракона не смогу. Вот задумайся",85971,null],[85975,"2026-07-01T22:51:29",32,"-Кстати насчёт рыцарей...\nПриятного аппетита ребята.\nЗавтра рыцари прибудут и я хочу сегодня до логова добраться. У нас получается гонка со временем.",84658,null],[85976,"2026-07-01T22:52:07",32,"-Но пока не спешите сначала в кузне мой заказ заберём а потом на дело",84658,null],[85977,"2026-07-01T22:52:31",42,"— таак.. Получается у нас в планах одолеть этого гиганта?",84658,null],[85978,"2026-07-01T22:53:23",9,"Иму — Забрать сокровища и принцессу себе — *Жадина мелкий строит планы.*",85977,null],[85979,"2026-07-01T22:53:27",32,"-Как минимум сразиться \n(Плотоядно оскалился Арминар) И не сдохнуть в процессе. А значит задача минимум к бою. Победить",85977,null],[85980,"2026-07-01T22:55:06",42,"— ну чтож.. Тогда к бою, я стал в разы быстрее чем был раньше. Так что его костям не поздоровится",84658,null],[85981,"2026-07-01T22:55:08",32,"(Арминар очень много хотел сказать мелкому но решил проигнорировать)",85978,null],[85982,"2026-07-01T22:55:10",9,"Иму — Дракона может победить рыцарь и другой дракон. — *Показал на себя и на Арминара.* — А нас... два.",85979,null],[85983,"2026-07-01T22:56:15",32,"-Ты меня бесишь. Я старший в стае, понял!?",84658,null],[85984,"2026-07-01T22:56:39",32,"(Арминар начал закипать его аристократическое эго было задето)",84658,null],[85985,"2026-07-01T22:56:40",9,"Иму — Грррр. Что такое стая?",85983,null],[85986,"2026-07-01T22:57:49",32,"-Это когда несколько драконов под предводительством самого большого объединяются в группу чтобы грабить тех кого по одиночку нереально из-за слишком большого количества врагов",85985,null],[85987,"2026-07-01T22:58:26",32,"(дал по максимуму простое и главное не противоречащее правде объяснение. В правильном свете)",84658,null],[85988,"2026-07-01T22:58:38",9,"Иму — Стая это друзья?",85986,null],[85989,"2026-07-01T23:01:24",9,"//Майло просто за перепалкай наблюдает)",84658,null],[85990,"2026-07-01T23:01:29",32,"-Это больше чем друзья. \n(И Арминар подвис пытаясь придумать описание не скатываясь в банальное \"мы семья\" и соответственно не желая описывать что такое семья) -Это друзья очень крепкие и связанные общей целью у стаи есть лидер. Самый умный, сильный и зачастую потому что самый старый и большой дракон. Его все слушаются",85988,null],[85991,"2026-07-01T23:01:57",42,"// жду пока приемлемо, чуть что вмешаюсь",85989,null],[85993,"2026-07-01T23:02:57",9,"Иму — Драконы не слушаются никого, они делают что хотят.",85990,null],[85994,"2026-07-01T23:03:35",9,"Иму — Ты не дракон? — *Подозрительно смотрит на Ааминара.*",84658,null],[85995,"2026-07-01T23:03:45",42,"— а ещё слышал что показатель могущества дракона это его богатство, ну а я вижу у Иму куча золота",85990,null],[85997,"2026-07-01T23:04:24",42,"°подмигнул иму с ехидной улыбкой°",84658,null],[85998,"2026-07-01T23:04:58",32,"-Это не совсем так.\nДраконы потому и улетают из своих гнезд и появляется такие одиночки как тот которого мы видели и крутого в ближайшее дни убьют рыцари. Что никого не слушает и слушать не хочет а старшие эму говорили не жги людей и дань не завышай",85993,null],[85999,"2026-07-01T23:06:03",32,"-Я дракон. Попробуй докажи обратное",85994,null],[86000,"2026-07-01T23:07:24",32,"-Ага и надетое на мне стоит дороже. \n(Показывает кулон с топазом) Магический предмет от двухсот и до пятисот золотых, цены на такие безделушки.\nПлюс по карманам мелочь завалялась",85995,null],[86001,"2026-07-01T23:08:20",32,"-Потому я круче.\n(И гордо задрал нос)",84658,null],[86002,"2026-07-01T23:10:05",42,"— Ладно, хватит спорить о драконих темах, а то я подниму тему об иерархии исчадий и узнаем кто демон, а кто лимур",84658,null],[86003,"2026-07-01T23:11:15",32,"-Я не исчадие. И уж тем более не демон. Может дьявол может даже ботезу но точно не демон.\n(Осадил тифлинга запутавшегося в терминологии)\nДемоны это исчадия бездны.",84658,null],[86004,"2026-07-01T23:11:42",9,"*Иму смотрит на свой мешок, апотом на топаз. В ценах он не разбирается, но его куча сокровищ выглядит внушительнее на его взгляд.*\n\nИму — У меня больше сокровищь! Я круче.",86001,null],[86006,"2026-07-01T23:14:47",32,"-Ладно не буду спорить с тем кто не знает цены ничему кроме золота.\nА кстати сколько его у тебя в монетах? Просто интересно насколько ты крут.\n(Испытание на пересчёт с учётом интелекта кобольда)",86004,null],[86007,"2026-07-01T23:16:53",42,"— у него уже есть мои 228 золотых 8 серебряных и 8 медиков",86006,null],[86008,"2026-07-01T23:16:57",9,"Иму — Много. — *Он показал как рыбак прказывает вот такую рыбу поймал. А потом ему будто пришла мысль, иму выглядел так.* — Ты сильнее? Сломай тогда стрелу!\n\n*Иму достал стрелу и протянул её Ааминару.*",86006,null],[86009,"2026-07-01T23:17:41",32,"(Арминар берёт стрелу и использует чувство магии чтобы попробовать опознать предмет)",86008,null],[86010,"2026-07-01T23:17:56",32,"(как заклинание с ячейки)",84658,null],[86011,"2026-07-01T23:18:33",9,"*Чувствуется отголосок магии ограждения.*",86009,null],[86012,"2026-07-01T23:19:04",32,"(Источник? Вся стрела или какой-то её элемент",86011,null],[86013,"2026-07-01T23:19:10",9,"//Опознаёт предмет заклинание опознания, тут ток школа",84658,null],[86014,"2026-07-01T23:19:22",9,"//Вся стрела.",86012,null],[86015,"2026-07-01T23:20:03",9,"Иму — Я не смог её сломать. Никто не сможет.",84658,null],[86016,"2026-07-01T23:21:05",42,"— ну малыш Иму прав",84658,null],[86017,"2026-07-01T23:21:46",9,"//Чем мы занимаемся 😂👍",84658,null],[86018,"2026-07-01T23:21:56",32,"(Арминар задумчиво крутит её в руках а потом достает два кусочка магнетита и использует починку)\n//Ты говорил что стрела потрёпанная временем привожу в идеальное состояние",86013,null],[86019,"2026-07-01T23:22:04",9,"//Надеюсь вам хотя бы интересно ~",84658,null],[86020,"2026-07-01T23:22:16",32,"//конечно интересно",86019,null],[86021,"2026-07-01T23:22:44",9,"*Магнетит не работает, этот предмет похоже полностью магический.*",86018,null],[86022,"2026-07-01T23:23:21",32,"//магнетит это материальный компонент заговора \"починка\"",86021,null],[86023,"2026-07-01T23:23:48",9,"//Починка вродь чинит немагические предметы? Или ошибаюсь",84658,null],[86024,"2026-07-01T23:25:00",32,"//\nЭто заклинание чинит одно повреждение или разрыв на предмете, которого касаетесь, например, разорванное звено цепи, две половинки сломанного ключа, порванный плащ или протекающий бурдюк. Если повреждение или разрыв не больше 1 фута в любом измерении, вы чините его, не оставляя следов.\n\nЭто заклинание может физически починить магический предмет или Конструкта, но не может восстановить магию в таких предметах.",86023,null],[86025,"2026-07-01T23:25:42",32,"//я потому и говорил именно о физической починке",84658,null],[86026,"2026-07-01T23:25:58",9,"*Зазабрина на наконечнике и древке чинится, оперение выровнялось.*",84658,null],[86027,"2026-07-01T23:26:06",32,"-Я может быть и не могу сломать, \nчары не выветрились ещё но могу починить.",84658,null],[86028,"2026-07-01T23:26:58",9,"*Он выхватывает стрелу, потом смотрит на неё, потом на тебя, потом на стрелу.*\n\nИму — Ты мудрец! Как папа.",86027,null],[86029,"2026-07-01T23:27:08",32,"-Иногда умение строить и чинить сильнее чем умение ломать.\n(Возвращаю стрелу кобольду)",84658,null],[86030,"2026-07-01T23:28:11",9,"*Наставления кобольд уже неслышал похоже на фоне осознания и удивления.*",86029,null],[86031,"2026-07-01T23:29:06",32,"-Хех (драконорожденный весело пыхнул магической дымкой из ноздрей) может и как папа а может и нет. Но в любом случае, я маг",86028,null],[86032,"2026-07-01T23:29:20",42,"— Мне кажется время зря теряем, хотя я рад что ты обрадовал моего друга",84658,null],[86033,"2026-07-01T23:30:10",32,"-Ну а какой у тебя план действий? Мои игрушки для дракона ещё куются в кузне. Потому я и не спешу",84658,null],[86034,"2026-07-01T23:31:45",42,"— план простой\n°ударил ближайшие дерево создав на ней трещину°\n— переломать ему крылья, а после ноги, и раздавить его сердце",84658,null],[86035,"2026-07-01T23:32:26",32,"-Знаешь что такое естественный отбор? Это когда идиотов едят",84658,null],[86036,"2026-07-01T23:32:50",9,"*Судя по горящим глазам Иму — план был одобрен.*",86034,null],[86037,"2026-07-01T23:32:58",32,"-А если серьёзно, он тебя буквально сожрёт за пару секунд",84658,null],[86038,"2026-07-01T23:34:03",32,"И именно потому я и хочу сначала лишить его лап своей кустарной разработкой а уже тогда ты переломаешь крылья",84658,null],[86039,"2026-07-01T23:35:07",32,"//ладно Жака ты как спать не хочешь? Ещё немного поиграем и я в гнездо",84658,null],[86040,"2026-07-01T23:35:52",42,"— Ну ладно.. Тогда пойду с иму в магазины купим чего-нибудь",86037,null],[86041,"2026-07-01T23:36:11",42,"// ну хз, желательно бы лечь спать перед рабочим днëм",86039,null],[86042,"2026-07-01T23:36:46",9,"//Да можете, эт я долбонавт днём спал",84658,null],[86043,"2026-07-01T23:37:05",32,"//тогда спокойной ночи",84658,null],[87236,"2026-07-02T18:22:09",32,"-Удачи (искренне пожелал драконорожденный) с учётом того что драконы свое не отдают то платить не Иму",86040,null],[87449,"2026-07-02T19:02:35",42,"// так все тут?",84658,null],[87462,"2026-07-02T19:04:35",42,"— научу как раз Иму что вкуснее и радостнее злата. Да? Но для начала тебя надо спрятать.. \n°смотрит на свой рюкзак думая поместится туда он или нет°",87236,null],[87477,"2026-07-02T19:06:36",9,"Иму — Дракон никогда не прятался и не будет!",87462,null],[87500,"2026-07-02T19:09:37",42,"— нууу.. Ладно. Я драконам не указ, пошли в поселение что-то да найдëм\n°взял рюкзак и потопал в сторону поселения°",84658,null],[87541,"2026-07-02T19:15:41",9,"//Я щас на своей игре разберусь и посмотрим",84658,null],[88214,"2026-07-02T21:40:23",9,"*В деревне развлечений не то чтобы много. Дети играют в рыцарей и монстрой, люди ебашат в плях, отстраивают дома. Та самая корчма, молодые парочки иногда седят на лавах.*",87500,null],[88215,"2026-07-02T21:42:58",9,"Иму — Меня не любят, прогоняют. — *Честно сказал он, даже кормарь вас же послал избавится от него с концами или прогнать со свалки.*",87500,null],[88258,"2026-07-02T23:33:59",32,"Арминар двинулся к кузне смотреть как происходит процесс. Раз делать все равно не чего",84658,null],[88259,"2026-07-03T00:19:15",42,"— Иму, честно. Меня тоже люди не любят, они чëртовы расисты. Если начнут гнать на тебя, я им по двум сценариям покажу почему ты хороший, иииии.. Второй им не понравится\n°словно как дьявол улыбнулся в сторону Иму°",88215,null],[88260,"2026-07-03T00:20:13",9,"*Наклонил голову не поняв намёка.*\n\nИму — Ну, ладно.",88259,null],[88261,"2026-07-03T00:22:48",42,"— нууу ладно, вкусности любишь?",84658,null],[88262,"2026-07-03T00:25:58",9,"Иму — Булки. — *Похоже он не пробовал ничего серьёзнее булки.*",84658,null],[88263,"2026-07-03T00:27:17",42,"— сегодня твой счастливый день, купим булки с каким-то вкусным варением внутри",84658,null],[88264,"2026-07-03T00:30:16",9,"*Виляет хвостом, явно довольный. Пока вы идёте по улице люди косятся на Иму, явно знакомый им вредитель, но так как он рядом с не очень доброжелательным на вид рогатым — не лезут.*",88263,null],[88265,"2026-07-03T00:31:15",42,"°иду в пекарню с Иму°",84658,null],[88266,"2026-07-03T00:32:27",9,"*Есть небольшая лавка, прямо в доме пекаря, он живет через пару стеночек сам суорей всего, пахнет свежим хлебом. Но чтобы сладких булок?.*",84658,null],[88267,"2026-07-03T00:32:35",9,"/roll 1d20 везение",84658,null],[88269,"2026-07-03T00:33:07",9,"*Из готового всего несколько плюшек что плмащанны мёдомч не то чтобы много.*",88268,null],[88270,"2026-07-03T00:35:41",42,"— Иму, дай монетку золотую, обменяем монетку на сладкий дар",84658,null],[88271,"2026-07-03T00:36:16",9,"*Из под прилавка выглянул пекарь, хмурым взглядом на Иму.*\n\nПекарь — Мелкий драк, снова красти? Кыш отселе, а то мётлу достану.",84658,null],[88272,"2026-07-03T00:36:27",9,"*Иму вообще не испугался.*",84658,null],[88273,"2026-07-03T00:36:54",9,"Иму — Зачем отдавать сокровище. — *Насторожился.*",88270,null],[88274,"2026-07-03T00:37:52",42,"— Не, я его перевоспитываю. Вот учу его щас покупать, а не красть",88271,null],[88275,"2026-07-03T00:39:12",42,"— Здесь так положено в этом мире, Драконы едят золото только когда взрослые, ты юн и золото не переваришь. Поэтому на монетку ты можешь очень хорошо поесть",88273,null],[88276,"2026-07-03T00:39:41",9,"*На тебя скептически посмотрели, очень. Но ниче не сказал.*",88274,null],[88277,"2026-07-03T00:40:03",9,"//Ебашь убеждение)",88275,null],[88278,"2026-07-03T00:40:19",42,"/r 1d20 +6",88277,null],[88280,"2026-07-03T00:40:37",42,"// ой просто д20",84658,null],[88281,"2026-07-03T00:40:40",42,"// 18",84658,null],[88282,"2026-07-03T00:41:09",9,"/roll -d20 он наивен и у него помеха)",84658,null],[88284,"2026-07-03T00:42:05",9,"*Всё же он достал монетку, золотой, и протянул тебе. Внимательно наблюдает.*",84658,null],[88285,"2026-07-03T00:42:55",9,"*У пекаря аж брови на лысину полезли.*\n\nПекарь — Ну чертяка, учишь драка.",84658,null],[88287,"2026-07-03T00:46:42",42,"// вот так выглядит пекарь?)",84658,null],[88288,"2026-07-03T00:49:48",42,"— так Иму следи, вот как выглядит выгода. Сэр, видел у вас плюшки   помацыллы с мëдом. Заверните за золотой нам с собой пожалуйста\n°кладëт монетку на кассу и следит чтобы драк учился выгоде от монет°",88284,null],[88289,"2026-07-03T00:55:33",9,"*Пекарь прикинулв уме.*\n\nПекарь — Мало их, трех серебрющек хватить. — *Сгрёб, вывалил сдачу и упаковал в платок из мешковины чистой. Решил отдать прямо Иму, прямо выйти из за прилавка.* — Дяржи малой драк, чертяка хорошему учит.",88288,null],[88290,"2026-07-03T00:56:46",9,"*Иму просто рястерянно взял, и вообще кажется словил несколько тяжёлых мыслей, пытался их переварить, аж лоб вспотел.*",84658,null],[88291,"2026-07-03T00:58:42",42,"— Ладно Иму, пойдëм. Как посидим и поедим я тебе покажу на ощущениях, а не на словах то, что только мы сделали\n°взял Иму не крепко за руку и отвëл куда-то где можно опробовать вкусности°",84658,null],[88292,"2026-07-03T00:59:59",9,"*На поетёном крепком заборе за хатами сесть есть где.*\n\nИму — Мы, поменялись? — *Самвя близкая ассоциация из тех что он нашёл.*",88291,null],[88293,"2026-07-03T01:01:16",42,"— да, поменялись. Если хочешь понять в чëм выгода.. Укуси золотую монету",84658,null],[88294,"2026-07-03T01:06:49",9,"*Насупился, не стал делать.*\n\nИму — Я знаю. — *Просто начал наминать плюшки, их все-го то немного было.*\n\n*После, когда умял половину, взглянул на Майло, решил. Он взял пару и протянул тифлингу.*\n\nИму — Делюсь. Ты не только друг дракона, тоже мудрец, как папа или тот злой не дракон что постоянно злится. — *Похоже пришло сравнение с Арминаром.*",88293,null],[88296,"2026-07-03T01:11:16",42,"— пхпх.. Кушай, дракону нужны силы. В отличии от этого дракона ты мне нравишься тем что напоминаешь меня в юности\n°словно старший брат почесасал кулаком ему макушку°",84658,null],[88297,"2026-07-03T01:14:01",9,"*Немного дёрнулся от внезапного контакта, потом постарался не подавать вида, хотя весь напрягся как пружина. Иму явно было не уютно, плохой опыт.*",88296,null],[88315,"2026-07-03T07:26:21",9,"//Мог ответить на пост, я продолжаю могу когда",88296,null],[88323,"2026-07-03T07:47:31",42,"— ну ладно. Извени, видно что тебе не приятно. Кстати \n°перестал так делать и принял угощение от дракона которое сразу же начал есть°",88297,null],[88324,"2026-07-03T07:48:01",9,"*Успокоился немного, слушает.*",88323,null],[88331,"2026-07-03T08:16:09",42,"— Когда ты повзрослеешь какие планы на будущее?",84658,null],[88334,"2026-07-03T08:22:57",9,"Иму — Гора сокровищь, украсть принцессу сжечь злых рыцарей что прийдут грабить моё логово. — *Словно со страниц сказкок о драконах. До этого момента, всё упорство, упрямство и даже отсутствие страха навеянно простой верой в сказку.*",88331,null],[88339,"2026-07-03T08:48:29",42,"— Ого, какие драконьи цели",84658,null],[88340,"2026-07-03T08:50:05",9,"*Гордо задрал нос, словно хвалили.*",88339,null],[88341,"2026-07-03T08:56:27",42,"°смотрю на раны, шрамы Иму°\n— а от куда у тебя эти раны? Они тебя обидели? \n°показал пальцем на случайного человека как бы говоря что в принципе, \"это люди с тобой сделали?\"°",84658,null],[88344,"2026-07-03T09:04:01",9,"Иму — Да, но я их прогнал! Моё логово никто не смог ограбить. А ещё собираю дань. — *Похоже данью он называл то что подворовывал булки из пекарни или чет такое.*",84658,null],[88357,"2026-07-03T09:31:43",42,"— ну чтож. Мне далеко до вас сэр могучий дракон. Хотя мы с тобою похожи, я так же прогнал с монастыря всех слабых, да и дань собираю с тех кто меня хочет ограбить\n°вспоминает историю с плутом°",84658,null],[88359,"2026-07-03T09:34:23",42,"— хоть я тебе и друг, но порою я.. Пхах.. Бываю и пострашнее дракона, но в последнее время я начинаю жалеть о своих поступках.. Хотелось бы и дальше жить в неданьи\n°смотрит на свои перебентованные кулаки вспоминая кровь не винных что впитала повязка°",84658,null],[88364,"2026-07-03T09:39:01",9,"Иму — Дракону нет дела до слабых. Они не стоять его внимания. — *По своему трактовал он признание.*",84658,null],[88378,"2026-07-03T09:49:15",42,"— ну есть тебе такое предложение, как тебе такая идея. Как прикончим это чудовище, может будем путешествовать вместе? Вижу ты любишь цености и сокровища, а мне как раз та ки не помешает друг что будет охранять наше добро. Я порою иду на разные задания и там платят золотом и ценностями. К тому же, пх.. сильные должны держаться вместе чтобы быть ещë сильнее",84658,null],[88386,"2026-07-03T09:52:32",9,"*Задумался, тут было егогнездо, логово уде некоторое время, но.*\n\nИму — Пойду! Но потом мы сделаем логово, настоящее большое, обещаешь?",88378,null],[88395,"2026-07-03T09:58:36",42,"— Обещаю\n°поставляем ему вытапаренный мизинец, что-то вроде клятва на мизинце°",88386,null],[88412,"2026-07-03T10:06:40",9,"*Ноль понимания, наклонил голову, не понимает что Майло хочет показать этим жестом.*",88395,null],[89699,"2026-07-03T14:21:01",32,"(Арминар как раз появился под конец взаимных обещаний о гнезде сложил пальцы сердечком так чтобы в прорезь попали обо)\n-Любовь, какая страшная сила. Она и дракона золото отдать заставит. Хе-хе.\n(Сам жуёт купленную булку)",84658,null],[89703,"2026-07-03T14:21:36",9,"//Бля. Рил как романтичная сцена 😂👍",84658,null],[90006,"2026-07-03T15:32:48",42,"// это мужская дружба, вы не понимаете",84658,null],[90207,"2026-07-03T16:07:42",32,"//все понимаю но не подколоть о слишком большом количестве романтики не могу)",90006,null],[90224,"2026-07-03T16:10:17",42,"// да ты просто ревнуешь меня к НПС)",90207,null],[90233,"2026-07-03T16:11:19",32,"//скорее наоборот, но ладно😁",90224,null],[90240,"2026-07-03T16:13:19",42,"°заскалил зубы и глаза стали ещë более адского оттенка°\n— за такие шутки меж клыков бывают промежутки",89699,null],[90249,"2026-07-03T16:15:34",32,"Ха-ха-ха (весело рассмеялся Арминар хохоча вполне беззлобно)\nДа ладно я ж не со зла. Так любя.\nХи-хи.\nИдём в кузню там заберём игрушки и поделим. Устроим дракону очень много острых ощущений.\n(Собственно Арминар от кухни пришёл потому что заказ готов и сам он не унесет)",90240,null],[90263,"2026-07-03T16:18:39",42,"— Ага.. Ну ладно будем действовать по твоему плану. Любовничек ты наш, но если помрëм заберу тебя с собою в ад, а то скучно будет одному\n°потопал за тобою в кузню°",84658,null],[90296,"2026-07-03T16:23:33",32,"- тебе дьяволов из ада не жалко?\n(Протянул Арминар шутливо) \nА я и не обещал что мы выживем. Изначально говорил что дракону мы на один зуб",84658,null],[90308,"2026-07-03T16:26:05",9,"*Иму до сих пор ни капли не боялся Арминара, но пепепалке не быть. Кузнец же, весь в поте лица вытер пот и выдал всего два набора крупных треугольников (калтропы на дракона).*\n\nПодмастерье — Батьки небыла, красный драк спалил дом, он с мужиками пошёл его искать чтобы хвост крутить. — *Отдаёт семь золотых вместо третьего набора который не успел.*",84658,null],[90354,"2026-07-03T16:31:11",32,"//каких треугольников?",90308,null],[90355,"2026-07-03T16:31:42",32,"//я же прямые штыри с шляпкой как большой гвоздь заказывал",84658,null],[90359,"2026-07-03T16:31:58",9,"//ты ж их заказывал, не? Кадтропы на дракона",90354,null],[90364,"2026-07-03T16:33:15",32,"//я тебе два раза описывал заказ и ты сказал \"зачем тебе они?\" \"Лапы чтобы дракон дырявил\" \"Как кадтропы на дракона?\"",90359,null],[90366,"2026-07-03T16:33:35",32,"//просто перечитай чат",90359,null],[90371,"2026-07-03T16:36:03",32,"Арминар как услышал что кузнец и другие мужики на дракона пошли за сердце схватился \n-еб#*@й рот да *'\"#@... \n(и вспомнив куда дракон улетел сам трусцой двинул туда же.)\n//Ускоренный марш",90308,null],[90380,"2026-07-03T16:36:49",9,"//Я хуй знает что ты описал,но пусть будет оно",84658,null],[90401,"2026-07-03T16:42:40",9,"//Мнебы в картинках в след раз)",84658,null],[90403,"2026-07-03T16:43:41",32,"//большой гвоздь короче но с скругленной головкой",84658,null],[90421,"2026-07-03T16:47:09",9,"//Сказал бы шлямбуры",84658,null],[90431,"2026-07-03T16:50:01",9,"//Вот их тебе 14 шт",84658,null],[90435,"2026-07-03T16:52:41",9,"*Путь пролегал дальше, меж остатками старых кпепостей к горам. Но куда дальше идти? Хотя и направление примерное Арминар помнил куда улетел дракон это не даёт гарантии найти место обитания летающей рептилии.*",84684,null],[90438,"2026-07-03T16:56:56",32,"Тогда возвращай мне 12 золотых.",90431,null],[90439,"2026-07-03T16:57:26",32,"У меня их 20 штук два комплекта",90431,null],[90440,"2026-07-03T16:57:34",42,"// а вроде богатый дракон)",90438,null],[90441,"2026-07-03T16:57:53",9,"//Ты дал 21 золотой. Он дал 14 таких и 7 вернул. Не успел",90438,null],[90443,"2026-07-03T16:58:12",32,"Мои штыри с шляпкой для того чтобы их можно было банально поставить или закопать в землю",90431,null],[90445,"2026-07-03T16:58:35",32,"1 золотой ЗА 10 ШТУК",90441,null],[90446,"2026-07-03T16:58:35",9,"//Оки, я ж дам это сделать",90443,null],[90447,"2026-07-03T16:58:43",9,"//А надо сколько?",84658,null],[90448,"2026-07-03T16:58:56",9,"//Столько возьми и вычти",84658,null],[90449,"2026-07-03T16:59:10",32,"20 штырей 2 золотых",84658,null],[90450,"2026-07-03T16:59:11",9,"//Не больше 14 ти связок",84658,null],[90452,"2026-07-03T16:59:25",32,"Мне хватит",84658,null],[90453,"2026-07-03T16:59:35",9,"//.",90435,null],[90458,"2026-07-03T17:00:56",32,"Хрен с ним идём мы в первую очередь искать куда селяне ушли а толпа людей оставит видимые следы. Потому движемся примерно к логову по дорогам. Будем искать куда селяне двинули",90435,null],[90465,"2026-07-03T17:04:17",42,"— Ну чтож.. Переломать крылья будет легче. На земле у нас будет приимущество благодаря твоей магии.. Иииии.. \n°смотрит на Иму не зная что сказать°\n— ииии.. Храбрости Иму",84658,null],[90467,"2026-07-03T17:05:13",9,"*Троп в горы полно, и ходят по ним часто, так сразу и не определись куда бесстрашные Темноградцы попиздячили.*\n\n//Выживание на поиск следов, слодность 17",84658,null],[90470,"2026-07-03T17:05:49",32,"//Можно кинуть анализ?",84658,null],[90473,"2026-07-03T17:06:17",32,"/roll d20+1",84658,null],[90475,"2026-07-03T17:06:35",32,"//Я точно не нахожу",84658,null],[90477,"2026-07-03T17:06:38",42,"/r 1d20 +5",84658,null],[90481,"2026-07-03T17:06:54",9,"/roll 1d20+1 иму пусть",84658,null],[90485,"2026-07-03T17:07:22",32,"//иму взял след",84658,null],[90492,"2026-07-03T17:10:23",9,"*Иму смотрит не вниз а вверх, на вершины холмов близлежащих у гор. Он думал вы ищите не людей а дракона.*\n\nИму — Логово дракона, на самом высоком холме. — *Он показывает на частично выпирающий с подгорья выступ изземли и камней, кажется там виднеется пара пещер, пещер неестественного происхождения, но и не рукотворного как у человека.*",84658,null],[90493,"2026-07-03T17:11:38",32,"-Тогда идём туда. Нам нужно поймать и перехватить крестьян чтобы не дать им свершить коллективное самоубийство",84658,null],[90494,"2026-07-03T17:12:21",32,"(сказал Арминар и двинулся к логову дракона.)",84658,null],[90500,"2026-07-03T17:14:11",42,"— а может используем их тела чтобы дракона чутка утомить и чтобы было легче его того.. \n°сжимает кулаки перед собою изображая картину как будто отрывает голову°",90493,null],[90501,"2026-07-03T17:14:22",9,"*По пути вы встретили следы костища, явно люди отобедали, передохнули.*",84658,null],[90502,"2026-07-03T17:14:47",9,"*Место едва тёплое.*",84658,null],[90504,"2026-07-03T17:16:57",9,"//Заявки там или чёт такое?",84658,null],[90505,"2026-07-03T17:17:04",9,"//Я тут если что)",84658,null],[90507,"2026-07-03T17:17:36",42,"°иду дальше по следу°",84658,null],[90510,"2026-07-03T17:19:54",32,"-Ну кажется не мы одни нашли логово дракона.\n(Арминар посмурнел) -логово не так далеко а костер прогорел. Значит селяне уже почти наверняка мертвы",84658,null],[90512,"2026-07-03T17:21:48",42,"— чтож.. Их сокровища будут наши. Да Иму?",84658,null],[90513,"2026-07-03T17:22:06",32,"-Ладно идём. Это ещё надо подтвердить",84658,null],[90514,"2026-07-03T17:22:36",9,"Иму — Хм. А кто будет платить дань дракону? — *В этом случае следственные связи стыковались.*",84658,null],[90515,"2026-07-03T17:23:30",42,"— ну всегда можно добить чтобы не мучались, а с иму найдëм тех кто богаче и дань будет соответствующей\n°идëт к логову дракона°",84658,null],[90519,"2026-07-03T17:24:24",32,"-ты действительно думаешь что с нравом дракона напавшие на него букашки не будут убиты? \n(Арминар горько улыбнулся)\nЛадно, вполне возможно их просто взяли в рабство. Хе",84658,null],[90520,"2026-07-03T17:25:31",32,"(Арминар движется вперёд напряжён и сконцентрирован.) \n-готов к бою",84658,null],[90526,"2026-07-03T17:29:47",42,"— да раньше бы это сказал\n°разминает спину и руки°",90520,null],[90531,"2026-07-03T17:33:29",32,"На подходе я запахиваю свою мантию с нашитой сетью и лепкой земли налепливаю на неё грязь пыль и впринципе привожу в состояние булыжник обоснованный. Тело открытые участки то же покрыть грязью и пылью затвердеть залепить.\nИ я готов маскировка под булыжник.",84658,null],[90536,"2026-07-03T17:34:45",32,"Одни глаза выдают что это аметистовый драконорожденный",84658,null],[90552,"2026-07-03T17:38:32",9,"//ирл разгребу чуток и будем)",84658,null],[90580,"2026-07-03T18:05:38",9,"*Час пути, вас ожидают мужики. Дюжина мужиков у самого входа, много с ожогами, пару мёртвых тел обожжённых до неузнаваемости, раненые поминают умерших.*\n\n— Коваля сьёл гад.\n\n— Мастифо бы натянул драка.\n\n— Покойси брат.",84658,null],[90582,"2026-07-03T18:06:33",9,"*Не то чтобы они сдались, раненные сидели у самого входа и готовились ко второму заходу. Взгляды упали на новые лица.*",84658,null],[90583,"2026-07-03T18:06:53",9,"— Чейси забыли здеся окаянные?",84658,null],[90586,"2026-07-03T18:08:19",9,"*Сам холм выглядит разрытым как решето, дракон явно умел копать, выходов минимум дюжина откуда угодно, а внутри скорей всего лабиринт.*",84658,null],[90587,"2026-07-03T18:08:37",42,"(Шëпотом) — Арми, может давай их используем как живой щит? Выйграем время благодаря их тушкам для установки ловушки?",84658,null],[90588,"2026-07-03T18:10:08",9,"Иму — Мы пришли бить другого дракона. — *Вообще не задумываясь ответил.*",90583,null],[90589,"2026-07-03T18:12:07",42,"— вот это настой! \n°по дружески коснулся кулаком по плечу°",90588,null],[90590,"2026-07-03T18:16:48",9,"*От неожиданности напрягся, казалось хотел царапнуть, но сдержался. Мелкому прийдётся долго привыкать к близкому контакту и чудя по его взгляду очень странно и непривычнодля него.*",90589,null],[90591,"2026-07-03T18:18:44",42,"— привыкнешь Иму, это знак того что я доверяю тебе и хочу взбодрить перед великой битвой",84658,null],[90596,"2026-07-03T18:28:10",9,"*Всё равно насторожен, хотя и обьяснение поумерило пыл.*\n\n//Арминара ждём, чё",90591,null],[90598,"2026-07-03T18:35:26",32,"Телепатией отвечаю.\n-Идём ты со своими гениальными планами.(Без злобы но явно не согласно ответил Арминар)",90587,null],[90599,"2026-07-03T18:36:59",32,"(достаточно громко чтобы слышали все) -Распоковывай свой набор целителя. Будем эту толпу лечить и физически этим займёмся оба и ментально последнее беру на себя",84658,null],[90601,"2026-07-03T18:45:16",32,"(а теперь обращаясь к селянам)\n-Так дебилы через чур храбрые. Я так понимаю отступать не намерены?\nЛадно тогда нам нужно дальнобойное оружие и подготовленные позиции. \nЯ возьму командование и организацию",84658,null],[90602,"2026-07-03T18:45:26",32,"//убеждение",84658,null],[90603,"2026-07-03T18:45:37",32,"/roll d20+4",84658,null],[90605,"2026-07-03T18:47:40",9,"//а где помеха?",90604,null],[90606,"2026-07-03T18:47:57",32,"//какая помеха. Почему?",90605,null],[90607,"2026-07-03T18:48:03",9,"//Они не оч жалуют драконоподобных",84658,null],[90608,"2026-07-03T18:48:14",32,"/roll d20+4",84658,null],[90610,"2026-07-03T18:49:59",9,"Местный — Умнай — сам пади. Коваль бачину вилами драку накуканил, Семён травами курил, мы чуть ему писды не дали, но тварина огнем пёрнула.",84658,null],[90611,"2026-07-03T18:50:51",9,"Второй — Хади сам, драку могу ток дубиной приложить.",84658,null],[90613,"2026-07-03T18:51:28",32,"-Я честно думал он сам всех на месте порвёт. Потому что удар вилами дракона даже не замедлит. Эму таких ударов под пол сотни надо",84658,null],[90614,"2026-07-03T18:52:03",32,"-А вот стрела в глаз или нос всяко эффективнее и не настолько разменная",84658,null],[90615,"2026-07-03T18:52:20",9,"Иму — Может это слабый дракон, тоже не настоящий.",90613,null],[90616,"2026-07-03T18:52:49",32,"-Скорее играется просто. Как кошка с мышкой",90615,null],[90617,"2026-07-03T18:54:09",9,"*Крестьяне настроенны скептически, даже очень. Помогать будут? Вряд-ли.*",84658,null],[90618,"2026-07-03T18:54:30",32,"-Хотя Коваль крут. Пробил чешую, или просто в стык попасть повезло",84658,null],[90619,"2026-07-03T18:54:59",32,"-Вы ещё раз внутрь идти будете?",90617,null],[90620,"2026-07-03T18:55:10",32,"(просто задаю вопрос на это ответят точно)",84658,null],[90621,"2026-07-03T18:58:01",9,"Первый — Канешна.\n\nВторой — Неа, сгинем Пауло, лыцарей ждать надо.\n\n*Начали ругаться и ещё пару человек подключилось. Коваль кажется был тот самый кузнец, он их привёл, бочину смог проткнуть тоже он и помер тоже. Сейчас они не могут решить потому что главного нет.*",90619,null],[90624,"2026-07-03T18:59:38",32,"- я изначально спешил чтобы вас отговорить от нападения на дракона.\nПотому уходите ребята, прошу вас.",90621,null],[90625,"2026-07-03T18:59:57",42,"°заступается за своего товарища°\n— Так?! Я не пойму?? Вы же не абы кто, а люди с рыцарской честью! Подумайте о ваших жëнах и детей. Вы дальше хотите надеятся на рыцарей сто придут. Пока они дойдут от ваших ценностей и всего что вам дорого может и не остаться? Иль вы какие-то мужики раз решили выйти на дракона. Не верю! Если этот дракон хочет избавиться от этого, значит тот настоящее чудовище",84658,null],[90626,"2026-07-03T19:00:14",9,"Иму — Мы победим его и заберём сокровища!",90624,null],[90627,"2026-07-03T19:00:40",32,"(телепатией)- Майло я же просил иди помоги раненым",84658,null],[90629,"2026-07-03T19:00:59",32,"//(как будем решать кого послушают?)",84658,null],[90630,"2026-07-03T19:01:35",42,"/r 1d20 -1 убеждение. Следуем плану драконорождëнного",84658,null],[90632,"2026-07-03T19:01:48",42,"// ладно, такое себе)",84658,null],[90634,"2026-07-03T19:02:56",42,"// ладно может преимущество есть за такую мощную речь?",84658,null],[90636,"2026-07-03T19:03:18",9,"*Все встали кто мог и выглядит так словно щас будут пиздить тифлинга, им кажется похуй что ранены. Оскорбление рыцарства Темноградского? Те вседа приходили, не бывало такого что нет.*\n\nПервый — Табе сейчас пязды дать, али потом.\n\nВторой — И сейчас и потом можно Пауло, зашем выбярать.",90625,null],[90638,"2026-07-03T19:04:04",9,"//Тут ток крит успех поможет и то временно, они искрене верят)",84658,null],[90639,"2026-07-03T19:04:53",32,"(драконорожденный стоит с фейспамом)\n-Ну Майло! Просто дай мне свой набор травника.\n(Протягиваю руку)",84658,null],[90640,"2026-07-03T19:05:31",9,"//Сорян, вы наверное привыкли к ссыкунам обывателям, тут темноградцы, они ебанутые чуть чуть",84658,null],[90641,"2026-07-03T19:05:55",32,"//я заметил что ебанутые. Не заметил что чуть чуть",90640,null],[90642,"2026-07-03T19:07:03",42,"°отдал набор травника и подошëл к нему°\n(Шепотом) — если честно я хочу сам их уже прикончить, кажется уже будут мешать нам больше чем принесут пользы",84658,null],[90644,"2026-07-03T19:08:22",32,"Арминар взял набор (наложил на себя псевдожинь (на всякий случай)) и не слушая подошёл к ближайшему раненому начал лечить.",84658,null],[90647,"2026-07-03T19:09:31",32,"/roll d4+4 \n(Псевдожинь)",84658,null],[90655,"2026-07-03T19:18:45",9,"*Уже хотели чёт сделать, года все мужики затихли. Вслед за вами по склону показалось три деда. Мощных, бородатых.*\n\nСтароста — Ебать вас в три ноги. Какуго хуя вы полезть на гру в пасть драка. — *Это были первые слова деда что пришёл сюда. Это было настолько мощно что даде Иму притих.* — Пошли назад, усе. Где Коваль? Ежели у него хоть волас с голавы упал будете карячется в печи куя мечи пока ваши сраки от угля не сгорят.\n\n*Все щамолчали, притихли. Будто став мелче перед дедом. Тот посмотрел и не найдя нужного человека... посмотрел на один из обгоревших трупов...*\n\nСтароста — Пошли все нахуй, всем ноги переламаю чтобы не ходили дальше собсвянного двора. Всем в дяревню.",84658,null],[90657,"2026-07-03T19:19:25",9,"*Похоже до старосты тоже дошла новость что мужики пошли дракона бить.*",84658,null],[90658,"2026-07-03T19:20:31",9,"*Староста повздыхал, стёр скупую слезу и посмотрел на трио героев пока мужики собирались идти,, словно чудесным образом открыли аторое дыхание.*",84658,null],[90659,"2026-07-03T19:21:19",9,"Староста — Вы смертняки туды полезете? Помяреть не боитесь?",84658,null],[90661,"2026-07-03T19:22:59",9,"*Тот человек которому ты решил помочь, он дал тебе склянку с кислотой.*\n\nРаненый — Спасиба. Тама у драка неть гласа одного, я старалси, не попал. Табе пригадица.",90644,null],[90662,"2026-07-03T19:23:01",32,"/Эм а мне медицину  кидать?",84658,null],[90663,"2026-07-03T19:23:10",9,"//Да не надо",90662,null],[90664,"2026-07-03T19:23:24",32,"-Спасибо тебе",90661,null],[90665,"2026-07-03T19:23:56",32,"-Хе ,нет у меня страха смерти. Есть страх проиграть бой",90659,null],[90666,"2026-07-03T19:24:18",32,"-Но так как напарники у меня огонь. Думаю вытянем",84658,null],[90667,"2026-07-03T19:24:20",9,"*Просто кивает, на вид молодой алхимик, он подумал.*\n\nРаненый — Прасти, многа с сабой не браль.",90664,null],[90668,"2026-07-03T19:26:41",9,"*Смотрит скептически.*\n\nСтароста — Вы люди не наши — ваше право. Но держитя моё наставления. — *Он вытянул руки и произнёс слова.* — Благослави о солнце над Темноградом этих людей порвать сраку драку.\n\n//На вас час действует эффект заклинания благословение",90666,null],[90669,"2026-07-03T19:27:48",32,"-Ох э!\n//(Напомни какой там бонус я в жреческой не бум бум)",90668,null],[90670,"2026-07-03T19:27:54",9,"Староста — Пращайте. Может увижу вас ящо. — *Идёт своих гнать домой по хатам.*",84658,null],[90671,"2026-07-03T19:28:59",9,"//В начале каждого хода у тебя обновляется 1д4 который можно докинуть к любому д20, будь то спас или атака/проверка, но только раз до слелующего хода",90669,null],[90672,"2026-07-03T19:31:05",9,"//Дед не зря староста, что-то немного могёт и разумеет",84658,null],[90711,"2026-07-03T20:08:49",42,"— еба.. Ты мозг и язык",84658,null],[90712,"2026-07-03T20:09:15",9,"//Эт кому ты",90711,null],[90713,"2026-07-03T20:09:35",42,"//Арми",84658,null],[90714,"2026-07-03T20:10:07",9,"//Ну да, выходит. Коасноречие 1000%",90669,null],[90730,"2026-07-03T21:19:36",42,"// так @Xaosick Hard вы тут можете продолжить?",84658,null],[90731,"2026-07-03T21:20:01",9,"//Минут через 30 полноценно, а так + - да",84658,null],[90732,"2026-07-03T21:20:02",42,"// я отошëл со стрельбищ домой ехал",84658,null],[90733,"2026-07-03T21:50:55",32,"//я тут",84658,null],[90735,"2026-07-03T21:56:24",9,"//Тоже тут + -",84658,null],[90736,"2026-07-03T22:03:16",42,"// тута",84658,null],[90737,"2026-07-03T22:04:07",9,"//Ну, ваши действия)",84658,null],[90738,"2026-07-03T22:07:12",42,"— Чтож.. Я всë же последую твоему плану, драконорождëнный. Давай диктуй",84658,null],[90739,"2026-07-03T22:09:11",9,"Иму — Драконорожденный? Дракон или не дракон? — *Кобольд услышал и запутался, дракон ли арминар или нет.*",90738,null],[90740,"2026-07-03T22:17:03",32,"-План прост. (Дал напарнику десять штырей) Мы сейчас в этом проходе разбиваем породу я с помощью магии делаю замаскированную волчью яму мы пройдём и не провалится а лапа дракона с приличной частью перенесенного веса уйдет в штыри.\nТак что готовься порода известняковая сейчас прийдется поработать ручками. Но как закопаем колья желательно в два ряда. Тут и за следующим поворотом. \nИ у тебя есть дальнобойное оружие? Лук например? Я могу вам натянуть по быстрому из того что найдётся. Потому что приближение к дракону равно оказаться в желудке возможно даже одним куском.",90738,null],[90741,"2026-07-03T22:21:43",9,"//Кинь проницатильность, сложность 6",90740,null],[90742,"2026-07-03T22:22:45",32,"//зачем?",90741,null],[90743,"2026-07-03T22:23:02",9,"//Напомню, выходов дюжина)",84658,null],[90744,"2026-07-03T22:23:26",9,"//И это только тех что видны невооружённым, сведевыкопанные",84658,null],[90745,"2026-07-03T22:23:41",32,"// и чё? Я то знаю как заставить ходить дракона там где надо",90743,null],[90746,"2026-07-03T22:23:48",32,"/roll d20+3",84658,null],[90748,"2026-07-03T22:24:11",32,"Проницательность",90747,null],[90749,"2026-07-03T22:24:37",9,"//Тогда и проницательность не надо, заставляй",84658,null],[90750,"2026-07-03T22:24:53",9,"//Я думал просто ты упустил из виду что выходов много",84658,null],[90751,"2026-07-03T22:25:15",32,"Нет я именно на этом и строил план",90750,null],[90752,"2026-07-03T22:26:06",9,"Иму — Думаешь я его съем за раз? — *Задумчиво прозвучало. Иму стал меньше быть уверенным что Арминар \"мудрец\".*",90740,null],[90753,"2026-07-03T22:26:43",32,"-Смотри мы сейчас измельчаем до гравия породу и я лепкой земли вы...",84658,null],[90754,"2026-07-03T22:28:09",32,"-Иму я не про тебя говорил а про обитателя этого места ты то точно не съешь никого!!(У Арминара подгорело. Капитально и даже волна грома уже пульсировала на пальцах с желанием просто убить это чудище чтобы оно под кобольдов не позорило)",90752,null],[90755,"2026-07-03T22:30:41",42,"— успокойся, он ребëнок. Все мы были такими.. Вот только я в его возрасте бухал",84658,null],[90756,"2026-07-03T22:30:46",32,"Хух (перевел дыхание драконорожденный и продолжил)\nЗаказываем в землю штыри оставляя внутренние полости.\nИ через десять метров ещё одну такую ловушку. Потом две насыпи бруствера и закапываемся буквально в чужом логове. В три стрелка с нами будет очень страшно сражаться а шипы один раз как минимум остановят атаку",90753,null],[90757,"2026-07-03T22:31:20",9,"Иму — Ммммм. — *Всё же подозрение в том что Арминар не дракон, да ещё не мудрец сохранилось.*\n\n*Наверное не очень приятно осознавать когда тупой кобольд считает тупым тебя и это читается прямо в его глазах.*",84658,null],[90758,"2026-07-03T22:31:56",32,"-Сочувствую твоей родне.\nУ меня не было времени на поведение \"ребёнок\" я видете-ли наследник клана! (У Арминара снова горит. Задели за живое)",90755,null],[90759,"2026-07-03T22:32:44",32,"(наверное прямо капитально неприятно особенно когда ты заслужено самый умный в комнате)",90757,null],[90760,"2026-07-03T22:33:05",9,"//Ладно, колья я понял, что такое бруствер",84658,null],[90761,"2026-07-03T22:33:10",42,"— у меня нету родни. Я сирота что отдали в монастырь котором пытали ежедневно\n°с ехидной улыбкой ответил Майло°",90758,null],[90762,"2026-07-03T22:34:24",9,"Иму — Я сидел в железном гнезде, у папы. — *Он прикинул и уточнил.* — Очень долго и много.",84658,null],[90763,"2026-07-03T22:34:48",32,"Арминар полез обниматься \n-Брат, дратан, братишка. Я... Я так долго тебя искал!",90761,null],[90764,"2026-07-03T22:35:14",32,"/roll d20+4\nвыступление",84658,null],[90766,"2026-07-03T22:35:44",42,"/r 1d20 +5 проницательность",84658,null],[90768,"2026-07-03T22:36:53",32,"/Арминар абсолютно искренен в своем душевном порыве",90766,null],[90769,"2026-07-03T22:37:14",32,"Так как его обучение он тоже считал пытками",84658,null],[90770,"2026-07-03T22:37:20",42,"— Сомневаюсь в этом, Арминар. Очень, тут ежу понятно что ты чешуйчатый, а я нет",90763,null],[90771,"2026-07-03T22:38:43",32,"-Брат по духу! Мы как красный и аметистовый драконорожденны внешне сильно отличаемся но в душе!\n(Продолжил развлекатся и за одно отвлекать товарища от воспоминаний)",84658,null],[90772,"2026-07-03T22:38:45",9,"*Иму ничего не понимает. Его то в клетке держали почти всю жизнь.*",84658,null],[90773,"2026-07-03T22:40:27",32,"//Накинь баф от вдохновляющий лидер +4 временных хита",84658,null],[90774,"2026-07-03T22:40:28",9,"*Смотрит и пытается понять, не напал ли Арминар на друга.*",84658,null],[90775,"2026-07-03T22:41:46",42,"— ну чтож.. Тебя тоже били по яйцам импровизированным тараном? Скручивали и вырихивали конечности? А после сам начинаешь это применять на других без сожалений? \n°продолжает с улыбкой отвечать майло°",90771,null],[90776,"2026-07-03T22:42:47",32,"// насыпь обычно креплённая брёвнами внутри но у нас скорее камнем",90760,null],[90778,"2026-07-03T22:47:10",32,"-Ну допустим у меня в детстве рога немного разной длины росли один раньше проклюнулся и немного с разной скоростью. Ты знаешь но когда тебе пилкой спиливают лишнее это очень больно. А мутноватый чешуйки полировали. Молодые очень тонкие вообще. Ощущение как будто тебе шкуру сдирают и я не шучу. \nТак что у меня то же есть что припомнить. А уж идеальную осанку и обучение её держать (вот тут Арминар вздрогнул)\nТак что единственное меня разве что по яйцам не били специально. Нужны ещё клану, видете-ли.\n(И мило улыбнулся оскалился)",90775,null],[90779,"2026-07-03T22:49:21",42,"— ну ладно, заслужил братец\n°приобнял крепко одной рукой за плечо и начал чуханить макушку кулаком забыла расчитывать свои силы°",84658,null],[90780,"2026-07-03T22:50:01",42,"/r +d20 +6 атлетика и приимущество потому что в захвате под названием братское объятие",84658,null],[90782,"2026-07-03T22:50:12",42,"// всë по правилам",84658,null],[90783,"2026-07-03T22:50:33",32,"//У меня псевдожинь висит. И от благословения +К4 к спасброску",84658,null],[90784,"2026-07-03T22:50:52",9,"//Он тоже может к4 докинуть)",84658,null],[90785,"2026-07-03T22:51:04",42,"// это просто считай пат пат по голове, но кулачком",84658,null],[90786,"2026-07-03T22:51:21",32,"/roll d20-1+d4",84658,null],[90788,"2026-07-03T22:51:43",32,"/Хе кажется ты сделал дракону весомо больно",90787,null],[90794,"2026-07-03T22:53:24",42,"// спас от Братского трепания кулачком по макушке? Да вы лютые)",84658,null],[90795,"2026-07-03T22:53:42",32,"//Ну я просто по приколу",90794,null],[90797,"2026-07-03T22:54:22",32,"//да и вообще хрупкий волшебник я меня нужно холить и лелеять",90794,null],[90798,"2026-07-03T22:54:48",32,"/А где конкретно по лбу или у основания рогов?",90785,null],[90799,"2026-07-03T22:55:47",42,"// лоб",90798,null],[90801,"2026-07-03T22:56:25",32,"/Меж глаз неудобно",84658,null],[90802,"2026-07-03T22:56:32",32,"Но больше негде",84658,null],[90803,"2026-07-03T22:56:56",42,"// нечего, выровним голову",84658,null],[90804,"2026-07-03T22:57:11",42,"// слышал о лоботомии?",84658,null],[90805,"2026-07-03T22:58:01",42,"— Так, ладно. Давай за уничтожения монстра браться, быстрее начнëм быстрее кончится",84658,null],[90812,"2026-07-03T22:59:56",32,"-Да идём",84658,null],[90814,"2026-07-03T23:00:36",32,"(коротко сказал драконорожденный и двинулся в пещеру. Прикидывая где будет удобнее разместить ловушку",84658,null],[90815,"2026-07-03T23:02:55",9,"*Пещера? Рытвина, будто кто то вгрызался в породу. Местами легко пройти хоть всем вместе, другим ток по одному ибо тесно, места, завалы, ожоги огня на стенах вплавленных камней. Это чертов лабиринт.*",84658,null],[90816,"2026-07-03T23:04:12",42,"— думаю сойдëт.. Было бы прекрасно и гигантскую сеть установить чтобы споймать эту тварь",84658,null],[90818,"2026-07-03T23:08:31",32,"-Только если из проволки толщиной с палец. Меньшую просто порвёт",90816,null],[90819,"2026-07-03T23:09:13",9,"Иму — Уронить большой камень. — *Показал руками насколько большой.*",90818,null],[90820,"2026-07-03T23:09:14",32,"Ну мы и не уходили далеко. Мы у входа почти занялись делом",90815,null],[90821,"2026-07-03T23:11:19",9,"//Если честно я пытаюсь понять вы там сидите или будете идти или ещё чёт и так далее",84658,null],[90822,"2026-07-03T23:11:37",42,"— а что, не плохая идея\n°выглядываю и ищу гигантские валуны которые можно будет скинуть на дракона°",90819,null],[90823,"2026-07-03T23:12:05",42,"/r 1d20 +5 внимательность если прокатит",84658,null],[90825,"2026-07-03T23:12:21",42,"// надеюсь иму поможет)",90824,null],[90826,"2026-07-03T23:12:56",9,"*Есть несколько, как миниму по голове дракона ударят больно. Правда над входом их затащить — пипец как сложно будет, ощущение что силёнок у тебя может не хватить.*",90824,null],[90827,"2026-07-03T23:14:05",42,"°вспоминаю о медальëне что мне подарил бывший плут и достаю его и прикидываю.. Иму + я + медальëн, наверное хватит сил°",84658,null],[90828,"2026-07-03T23:15:23",9,"//Ну, я не знаю что ты делаешь, это мысли?",90827,null],[90829,"2026-07-03T23:16:07",42,"// это мысли о заготовке на будущую ловушку",90828,null],[90830,"2026-07-03T23:18:29",32,"//Я могу сделать лифт. Спомощью лепки земли можно наращивать грунт под предметом преподнисая его. Так что меня нужно только позвать на помощь",84658,null],[90831,"2026-07-03T23:19:42",9,"/roll 1d20 млучайное решение, чем меньше число тем вероятнее",84658,null],[90833,"2026-07-03T23:20:20",9,"*Иму просто идёт к одному из валунов что ему приглянулись, раз уж заговорили о камнях.*",84658,null],[90834,"2026-07-03T23:21:20",9,"/roll +d20+4 у него две черты которые увеличивают переносимый вес вдвое, так что думаю шансы есть",84658,null],[90836,"2026-07-03T23:21:53",32,"В общем копаюсь у входа разбивая пол и вкапываю свои штыри",84658,null],[90837,"2026-07-03T23:22:24",9,"*Камень немного покатился. Слишком большой и тяжёлый, ещё и в гору катить. Иму бросил эту мысль.*",84658,null],[90838,"2026-07-03T23:22:52",42,"°помогаю Иму таская вместе °",84658,null],[90839,"2026-07-03T23:22:59",42,"// приимущество?",84658,null],[90840,"2026-07-03T23:23:30",9,"//Да давай, сложность 15, в гору 22",84658,null],[90841,"2026-07-03T23:23:30",42,"/r 1d20 +6",84658,null],[90844,"2026-07-03T23:24:10",42,"// на держи. У меня чертяга вот как выглядит когда снимет одежду",84658,null],[90847,"2026-07-03T23:25:33",42,"// нету нормальных гифок",84658,null],[90848,"2026-07-03T23:25:34",9,"*С очень сильным НАСТОЯЩИМ ДРАКОНОМ под боком, хоть и с трудом вы катите в гору камень... почти скалу. Правда когда это оказалось над выходом встала проблемма, как это зафиксировать. Перестать держать — скатится.*",84658,null],[90849,"2026-07-03T23:26:23",42,"°кричу нашему магу°\n— нужна опора! Помоги пожалуйста!!",84658,null],[90850,"2026-07-03T23:27:24",42,"// что видит камень когда идëт Майло",84658,null],[90852,"2026-07-03T23:28:43",32,"Лепкой земли нагоняю грунт на высоту. Пол минуты неспешной магии и валун зафиксирован а два долбодятла лежат и пытаются прийти в себя после перекатывания на гору примерно 4 тонн известняка",90849,null],[90854,"2026-07-03T23:28:52",9,"*Арминар видит как его товариши прикатили скалу весом так фунтов 1000-1500 на глаз по склону, это пиздец.*",84658,null],[90856,"2026-07-03T23:29:50",32,"Не если ты говоришь диаметр больше метра то это за 4 с лишним тонны",90854,null],[90858,"2026-07-03T23:30:37",9,"//Наверное больше, в принципе, не суть то, главное если упадёт...",84658,null],[90860,"2026-07-03T23:30:44",42,"// это дуо",90859,null],[90861,"2026-07-03T23:31:04",9,"//Без мага хер бы чо вышло",90860,null],[90862,"2026-07-03T23:31:46",42,"// правда, но и без тупой грубой силы и у него не вышло бы такой лютой ловушки. Хотя спасибо ему большое",84658,null],[90863,"2026-07-03T23:32:51",9,"//Думаюподготовка заняла 20-30 минут, хз",84658,null],[90864,"2026-07-03T23:33:20",42,"(Кричит) — Арми, думаю дракон от такого ахуеет с подарка с небес. Ты же главное успей убрать уступ когда поведнеется его голова",84658,null],[90865,"2026-07-03T23:33:27",32,"/Кстати удар валуна будет с какой высоты?",84658,null],[90866,"2026-07-03T23:33:47",9,"//Думаю футов 50 с разгоном",84658,null],[90867,"2026-07-03T23:33:54",42,"// а урон?)",84658,null],[90868,"2026-07-03T23:34:11",32,"-Два дебила это сила три дебила это мощь!",90864,null],[90869,"2026-07-03T23:34:23",9,"//Мы больше не вытащим, и так упущение нихуя себе",84658,null],[90871,"2026-07-03T23:34:30",42,"— два физмата и гуманитарий",90868,null],[90872,"2026-07-03T23:35:34",32,"-Ну давление четыре с лишним тонн силы на площадь соприкосновения шароида. Там дохуя получается\nИ это статично а если с ускорением то до 400-600 килоджоулей кинетики прилетит",90866,null],[90873,"2026-07-03T23:36:03",42,"— Так, у нас готово. Я соглашусь побыть приманкой. Главное меня не раздави",84658,null],[90874,"2026-07-03T23:36:17",42,"// и прорицанием помоги если чё :)",84658,null],[90875,"2026-07-03T23:36:48",9,"Иму — Грррр, а зачем это.",84658,null],[90876,"2026-07-03T23:36:50",32,"//У меня пусто по знамениям вроде",90874,null],[90877,"2026-07-03T23:37:12",42,"// уже? У нас же был долгий отдых, когда успел?",90876,null],[90878,"2026-07-03T23:37:32",32,"Не оба заряжены",85945,null],[90879,"2026-07-03T23:37:55",32,"//раз в сутки а не отдых. Кидаются кости на рассвете",90877,null],[90880,"2026-07-03T23:38:21",42,"// так мы спали и сутки прошли со вчерашней битвы с Иму",90879,null],[90881,"2026-07-03T23:38:39",9,"//Это новые",84658,null],[90882,"2026-07-03T23:39:08",9,"//Не юзал он их пока",84658,null],[90883,"2026-07-03T23:39:32",42,"— Ну а кто лучше разозлит дракона как демон что оскверняет его сокровища и честь, у нас давняя рассовая  битва)",90875,null],[90884,"2026-07-03T23:40:22",42,"— ибо я немного рассист и не люблю всех как и себя, хотя вы исключения ребят",84658,null],[90885,"2026-07-03T23:40:25",32,"Бери (протягиваю склянку кислоты и пращу) используй оба по назначению в дракона. Цель в нос",90883,null],[90886,"2026-07-03T23:41:04",32,"-Лучше разозлить дракона ты не сможешь а так же как и временно ослепить",84658,null],[90887,"2026-07-03T23:41:13",42,"— запомнил\n°захожу в логово дракона пытаясь скрыться°",90885,null],[90888,"2026-07-03T23:41:29",42,"/r -d20 -1 скрытность",84658,null],[90890,"2026-07-03T23:41:59",42,"//да пох, я шумлю и громахаю крича и ворча",84658,null],[90891,"2026-07-03T23:42:36",32,"/А почему с помехой?",84658,null],[90892,"2026-07-03T23:42:45",42,"// кольчуга",84658,null],[90893,"2026-07-03T23:42:58",42,"// 16 кд то от куда)",84658,null],[90895,"2026-07-03T23:43:19",9,"*Тунелей и разветвлений — куча, и поворачивают не только в бока а и в низ и вверх. Звук плохо распостраняется, слишком уж закрученны тоннели.*",90887,null],[90896,"2026-07-03T23:43:35",42,"// пох, главное его разгневать и вывести с тунеля на ловушки",84658,null],[90897,"2026-07-03T23:44:42",9,"//Выбери три числа от 1 до 20. Кроме этого кинь на выживание если идёшь вглубь чтобы не заблудится, сложность 15",84658,null],[90898,"2026-07-03T23:45:23",32,"(сижу у входа осматриваю все видимые выходы и готов обрушить валун или нырнуть в туннель если зайдут снаружи)",84658,null],[90899,"2026-07-03T23:45:44",42,"/r 1d20 выбираю число\n/r 1d20 +5 выживание",84658,null],[90901,"2026-07-03T23:46:09",42,"// о как",84658,null],[90902,"2026-07-03T23:46:53",42,"/r 1d20\n/r 1d20 числа",90897,null],[90904,"2026-07-03T23:46:57",9,"//Ну, выживание даже с благословением 1д4 не поможет. А мне надо 3 числа разных из д20, я кину как выберишь, если угадаешь",84658,null],[90906,"2026-07-03T23:47:51",42,"// типо вот числа 17, 20, 2",84658,null],[90907,"2026-07-03T23:47:58",9,"/roll 1d20",84658,null],[90909,"2026-07-03T23:48:37",9,"*Майло кажется заблудился и ещё не нашёл никакого дракона.*",84658,null],[90910,"2026-07-03T23:49:58",42,"// мде.. Ждите меня не скоро, вернусь через два года из пещеры с гаремом дракониц",84658,null],[90911,"2026-07-03T23:50:22",9,"*Просто порытые тоннели, пару испуганных летучих мышей и пути ведущие вникуда. Спустя минут так десять, ты видишь свет. Это выход, но совсем в другом месте.*",84658,null],[90912,"2026-07-03T23:50:28",32,"//ждём. Без драконий не возвращайся",90910,null],[90913,"2026-07-03T23:50:55",32,"//я его вижу?",90911,null],[90914,"2026-07-03T23:51:07",9,"Иму — Дракон не съел его?",84658,null],[90915,"2026-07-03T23:51:37",9,"//Не, вблизи ты видишь только ходы что рядом",90913,null],[90916,"2026-07-03T23:51:46",32,"-Если бы съел, мы бы это услышали",90914,null],[90917,"2026-07-03T23:51:52",42,"°делаю обвал этого выхода если есть какие-то уязвимости в кладке°",90911,null],[90918,"2026-07-03T23:51:57",32,"//я потому и спрашивал",90915,null],[90919,"2026-07-03T23:52:10",9,"*Иму нерничает.*",90916,null],[90920,"2026-07-03T23:52:53",9,"*Выходы все сделанны так чтобы их легко завалить.*\n\n//Опиши как,",90917,null],[90921,"2026-07-03T23:53:07",42,"// не каких нахуй запасных выходов, покажу ему что не я с ним заперт, а он со мной",90917,null],[90922,"2026-07-03T23:53:44",42,"°ударяю кулаком создавая тряску и громкие звуки обвала°",90920,null],[90923,"2026-07-03T23:54:17",42,"// как ни как эти кулаки несли 4 с лишней тоны",90922,null],[90924,"2026-07-03T23:54:18",9,"*Арминар слышит странный звук, где-то что-то осыпалось.*",84658,null],[90925,"2026-07-03T23:54:35",9,"Иму — А это... не дракон?",84658,null],[90926,"2026-07-03T23:55:05",32,"-Не это не дракон. Это похоже на обвал",84658,null],[90927,"2026-07-03T23:55:29",9,"//Хех, ты пр ложил лишь треть услий от нужных, черты мускулистого и безмерной мощи у иму)",90923,null],[90928,"2026-07-03T23:55:58",32,"(Арминар был полностью спокоен руки за спиной в замке спина прямая а глаза следили за округой)",84658,null],[90929,"2026-07-03T23:57:04",42,"// ну а я выбил нужные 25 и я считай на равных или более таскал, мускулистый делает его силу размера как у меня, так что нечего такого",90927,null],[90930,"2026-07-03T23:57:41",9,"//У него размер щитается большим, а у тебя средним, у него две черты ×2",90929,null],[90931,"2026-07-03T23:57:58",42,"°прикладываю уши к земле и вслушиваюсь в окружение и вибрации земли°",84658,null],[90932,"2026-07-03T23:58:14",9,"//Ты внутри или снаружи?",90931,null],[90933,"2026-07-03T23:58:57",42,"/r 1d20 +5 выживание, на понятие понять где есть колебания и от куда свестит ветер",84658,null],[90935,"2026-07-03T23:59:03",42,"// да",90932,null],[90936,"2026-07-04T00:00:11",42,"// а у меня борец и мне пофиг кого ломать)",90930,null],[90937,"2026-07-04T00:01:57",32,"//Мне это уже не нравится.",84658,null],[90938,"2026-07-04T00:02:17",32,"Арминар волнуется что напарника долго нет",84658,null],[90939,"2026-07-04T00:03:21",9,"//Ты пока мож д4 докидывать",90934,null],[90941,"2026-07-04T00:03:51",42,"// потерялся, у Майло орентировачный критинизм",90940,null],[90942,"2026-07-04T00:03:55",9,"/roll 2d20 удача так как пошумел шансы больше",84658,null],[90944,"2026-07-04T00:04:38",32,"//да тут просто проблема в том что Майло не знает куда бежать после дракона",90941,null],[90945,"2026-07-04T00:05:01",9,"*Майло снова бродит по пещерам пока не натыкается на ещё один выход. Это снова не тот что нужон.*",84658,null],[90946,"2026-07-04T00:05:28",42,"°и его валю°",84658,null],[90947,"2026-07-04T00:05:41",9,"Иму — Гррррррр. — *Злится.*",84658,null],[90948,"2026-07-04T00:06:31",9,"//Не моя проблема чтовы без подготовки полезли в лабиринт, самы же ~",84658,null],[90949,"2026-07-04T00:06:53",42,"// пофиг, так интереснее",84658,null],[90950,"2026-07-04T00:07:26",9,"//Описывай что делаешь\n\n\n*Ещё звук обвала, Арминар слышит какой-то шум изнутри.*",90946,null],[90951,"2026-07-04T00:08:47",42,"°так же избил стену кулаками и создал тряску°",90950,null],[90952,"2026-07-04T00:09:04",42,"°снова пошëл на поиски°",84658,null],[90953,"2026-07-04T00:09:05",9,"//Я жду действий после",90951,null],[90954,"2026-07-04T00:09:23",9,"/roll 2d20 чёртова удача",84658,null],[90956,"2026-07-04T00:09:37",42,"/r 1d20 +5 +1d4 выживание",84658,null],[90958,"2026-07-04T00:09:44",32,"Так меня достало. (Я говорю иму) Твой друг потериался его надо спасать. Дай мне руку я примяжу тебя нитью(восток щелкой нити очень длинный а их у меня если что не один потому лапу туго и на удавку привязать и отправить ему внутрь)",90950,null],[90959,"2026-07-04T00:09:50",9,"*Майло выходит к своим.*",84658,null],[90960,"2026-07-04T00:10:18",32,"Как раз вязал узел как Майло появился",90958,null],[90961,"2026-07-04T00:10:28",42,"— Да это катакомбы целые. Вы драконы или черви вирмы?",84658,null],[90962,"2026-07-04T00:11:06",9,"*Дракона он так и не встретил пока. Но даже так, изнутри иногда доносится звук словно перемалывают землю? Или трясётся гора, слегка.*",84658,null],[90963,"2026-07-04T00:11:51",9,"*Иму подбежал к Майло, осмотрел и успокоился.*",84658,null],[90964,"2026-07-04T00:12:27",32,"-Предлагаю исследовать и картографировать.\n(Достал пустой свиток)",84658,null],[90965,"2026-07-04T00:12:28",9,"/roll 2d20 пока вы тут)",84658,null],[90967,"2026-07-04T00:12:47",42,"// чтобы громко крикнуть прям как бросок, кидать тело? Типо преодолевание физических возможностей",84658,null],[90968,"2026-07-04T00:13:26",9,"*Позади Майло из тьмы прохода сверкнули глаза и исчезли, всё странно затихло.*",84658,null],[90969,"2026-07-04T00:13:54",9,"*Арминар видел это...*",84658,null],[90970,"2026-07-04T00:15:57",42,"/r 1d20 +5 тело на громкий крик чтобы поломать эго дракона\n— Чудовище что боятся целые города так боялся меня что позволил мне лично проходы твои завалить? Боишься крошку тифлинга! Апхахах!!",84658,null],[90972,"2026-07-04T00:16:05",32,"-Ей там в темноте! Мы поговорить пришли.\n(Это кстати не ложь Арминар действительно говорить пришёл)",84658,null],[90973,"2026-07-04T00:16:27",9,"//А ты его не видел, глаза видел только Арминар",90970,null],[90974,"2026-07-04T00:16:44",42,"// я до глаз хотел крикнуть в пищеру",90973,null],[90975,"2026-07-04T00:16:55",42,".",90967,null],[90976,"2026-07-04T00:17:26",9,"//А что сподвигло на такое решение?",90967,null],[90977,"2026-07-04T00:17:34",9,"//Я понять не могу",84658,null],[90978,"2026-07-04T00:17:54",42,"// просто крикнуть с надеждой что услышит и оскорбится",90977,null],[90979,"2026-07-04T00:18:27",42,"// всем известно что у драконов проблемы с эго)",84658,null],[90980,"2026-07-04T00:20:05",32,"//эх этот крик мне прямо обломал планы. Я то реально поговорить по душам хотел а теперь его сначала нужно победить.\n(Как говорит народная мудрость \"чтобы заработала Наруто-терапия нужно сначала дать пиздюлей\")",84658,null],[90981,"2026-07-04T00:20:47",42,"// смотри чтобы камушек не ваншотнул его",90980,null],[90982,"2026-07-04T00:22:10",32,"//неа не ваншотнет точно там максимум 10-15 к8 дробящего. Что в самом лучшем случае меньше чем хитов у молодого дракона",90981,null],[90983,"2026-07-04T00:22:31",9,"*На провокацию реаеции небыло. А вот на слова Арминара.*\n\n??? — Гостей приглашают. Говорить достойны лишь на равных. Всего то драконорожденный, тифлинг и... кобольд (с презрением) — *Голос звучит так словно из носоглотки, утробное урчание от которого мурашки по коже.*",84658,null],[90984,"2026-07-04T00:24:31",9,"Иму — И дракон! — *Сказал мелкий чем заслужил очень внимательный взгляд изнутри, а потом звук похожий на смех гремящий и одновременно таков словно кто-то захлебнулся.*",84658,null],[90985,"2026-07-04T00:24:37",32,"-Идём нас зовут в гости.\n(Проигнорировал призрение двинул вперёд)\nЯ по статусу наследник и почти глава клана. И это почти только потому что я не хочу на себя это валить. Так что статус у меня есть",84658,null],[90986,"2026-07-04T00:25:22",9,"//Видно твой цвет?",90985,null],[90987,"2026-07-04T00:25:53",42,"— ну допустим\n°пожал плечами тифлинг как будто для него это типичная пятница°",84658,null],[90988,"2026-07-04T00:27:19",32,"//Глаза только выдадут.",90986,null],[90989,"2026-07-04T00:27:32",32,"А так маскировка булыжник",84658,null],[90990,"2026-07-04T00:27:54",32,"Но мне макушку тёрли!",84658,null],[90991,"2026-07-04T00:28:04",32,"Там стёрто а я не заметил",84658,null],[90992,"2026-07-04T00:28:14",32,"Так что видно что аметистовый",84658,null],[90993,"2026-07-04T00:31:19",9,"*Пронзительный взгляд из тьмы метнулся к каждому из вас из тьмы. После движение и словно втотой глаз исчез, в вас из пещеры прилетел драгоценный камень с кулак, и остался во тьме гореть лишь второй глаз. Говорили же что у твари нет второго глаза.*\n\n??? — Забирайте, охотники за сокровищами. Уходите. Коли ваша жадность будет чрезмерна — я не буду столь... (пробует слово на вкус растягивая как насмешку или не совсем правду) добр.\n\n*Голос очень, очень неестественен.*",84658,null],[90994,"2026-07-04T00:32:23",32,"(телепатия)-майло иму \"проклято нельзя\"",90993,null],[90995,"2026-07-04T00:33:15",32,"-Я здесь не ради сокровищ. Я действительно хотел поговорить и посмотреть. Помочь и дать пару дельных советов. Можно нам зайти? Мы не будем нападать",90993,null],[90996,"2026-07-04T00:33:18",9,"*Глаз из тьмы моргнул внимательно наблюдая.*",84658,null],[90999,"2026-07-04T00:35:04",32,"/перк превилигированость от благородного ещё никто так не использовал",84658,null],[91000,"2026-07-04T00:36:29",9,"??? — Переговоры... я могу выйти сам коли желаешь лицезреть меня, драконид...",90995,null],[91001,"2026-07-04T00:37:33",32,"-Лучше не стоит. Тут ловушки.",84658,null],[91002,"2026-07-04T00:38:52",9,"??? — Те же приёмы, всегда. — *Звук захлёбывающегося смеха.*",84658,null],[91003,"2026-07-04T00:39:00",32,"(да Арминар цинично сдал их приготовления но получил пару очков репутации)",84658,null],[91004,"2026-07-04T00:39:50",32,"-Так мы войдём? (Не дожидаясь разрешения первый начинаю проходить в туннель)",91002,null],[91005,"2026-07-04T00:40:44",9,"??? — Храбрец... как раз подумывал обвалить тоннель.",84658,null],[91006,"2026-07-04T00:41:32",9,"*Дракон похоже передумал и его глаз исчез из тьмы, словно приглашение.*",84658,null],[91007,"2026-07-04T00:41:49",32,"-Я тебе обвалю! (Наигранно грозно помахал кулаком) И вообще, где болит давай раны обработаю у меня зелье лечения и набор травника есть",84658,null],[91008,"2026-07-04T00:42:42",32,"//да хаотично Добрый персонаж это страшно",84658,null],[91009,"2026-07-04T00:43:24",9,"*На предложение \"лечения\" лишь раздался ещё более жуткий гогот исчезающий во тьме становясь приглушённым. У дракона явно деффект речи, невероятно жуткий и странный.*",91007,null],[91010,"2026-07-04T00:44:16",9,"Иму — Это точно настоящий дракон! Как я. — *Сказал он о своих наблюдениях, явно воодушевлённый поведением существа изнутри.*",84658,null],[91011,"2026-07-04T00:44:25",32,"//Ну это понятно. У меня есть несколько предположений почему",84658,null],[91012,"2026-07-04T00:45:22",32,"Идём внутрь. По пути прямо за драконом.",84658,null],[91013,"2026-07-04T00:46:19",9,"//Майло?",84658,null],[91014,"2026-07-04T00:47:09",32,"//видимо пропал",91013,null],[91015,"2026-07-04T00:47:38",32,"//ещё с вот этого сообщения",90993,null],[91016,"2026-07-04T00:49:05",32,"//Опиши сцену входа в логово дракона пж",84658,null],[91017,"2026-07-04T00:49:23",32,"//Майло все равно деваться некуда",84658,null],[91018,"2026-07-04T00:49:24",9,"//Входа?",84658,null],[91019,"2026-07-04T00:49:43",32,"Ну куда дракон пошёл центральный зал или ещё что",91018,null],[91020,"2026-07-04T00:53:49",32,"//не заметил опечатки",91018,null],[91022,"2026-07-04T00:55:15",9,"*Норы, много нор, сырость. Это был красный дракон насколько ты разглядел в небе издалека тогда, но, это не стиль красных драконов.  Землю тряхнуло и среди всех проходов появился выход в чуть более просторное место, но не слишком.*\n\n*Вспышка, приложив лицо провой стороной к брёвнам дракон разжёг костёр. Дерево начало, тлеть немного освещая видимость, стало понятно почему дракон говорил таком странным образом. Половина черепа, разбита, куча дыр в шее, с тактм точно не живут.*\n\n??? — Любуешься — *Раздался утробный голос из дыр на шее, он говорил не открывая пасти. В свете огня было видно очень мощные передние лапы, словно полукротовьи, чтобы разрывать почву.*",84658,null],[91023,"2026-07-04T00:56:52",9,"*Сотни шрамов, отсутствующая во многих местал чешуя, дыхание словно скрип, тяжёлое, вымученое. Лишь левый глаз всё ещё ярко сверкал, не тронутый.*",84658,null],[91024,"2026-07-04T00:56:57",32,"-Ебаный рот... (Совершенно невоспитано протянул драконорожденный) \nТы жив? Или нежить?",84658,null],[91025,"2026-07-04T00:57:40",32,"- мы тебе обязательно поможем. Пусть это и будет очень тяжело.",84658,null],[91026,"2026-07-04T00:58:23",9,"??? — Ни одного проклятия, ни одного заклинания, ничего. Раны, бесчисленные сражения. — *Залился утробным смехом.*",84658,null],[91027,"2026-07-04T00:58:24",32,"-Кхм.(Вспомнил о манерах Арминар) Я Арминар из клана Керрилон.",84658,null],[91028,"2026-07-04T00:59:23",32,"-Ну тут моих лекарских препаратов не хватит.\nНужно добыть ещё лечения",91026,null],[91029,"2026-07-04T00:59:47",9,"*После первого впечатления Арминар понял что этот дракон едва ли большой, вирм что лишь недавно начал становится взрослым, подросток.*",84658,null],[91030,"2026-07-04T01:00:22",32,"(совершенно без страха подходит и начинает осматривать все раны. А за одно применил обнаружение магии)",84658,null],[91031,"2026-07-04T01:00:37",32,"Вдруг в ранах есть некротика",84658,null],[91032,"2026-07-04T01:01:12",32,"Да буквально заглядывать под все и под брюхо и под крылья и вообще обнаглел осматривая дракона",91030,null],[91033,"2026-07-04T01:01:23",9,"*Магии никакой.*\n\n??? — Вернись на место... — *Звучит как угроза и предупреждение чтобы не лез, иначе — атака.*",91030,null],[91034,"2026-07-04T01:02:44",32,"-Я хочу осмотреть раны а не стоять столбом. Мне нужно прикинуть объем работ по лечению.\nА ещё к тебе тут буквально завтра рыцари должны заглянуть",91033,null],[91035,"2026-07-04T01:02:59",9,"Квархадрон — Имя. Пусть будет Квархадрон. — *Хрипение, словно насмешка самого над собой.* — Неизвестный дракон, хрррррр.",84658,null],[91036,"2026-07-04T01:04:09",9,"Квархадрон — То что не может залечится само — не вылечить. Прошли годы.",91034,null],[91037,"2026-07-04T01:04:13",32,"-Приятно познакомиться. (Сделал небольшой поклон Арминар)",91035,null],[91038,"2026-07-04T01:05:15",9,"Квархадрон — Рацари... — *Почесал отсутсвующий глаз, точнее глазницу.*",84658,null],[91039,"2026-07-04T01:05:40",32,"Хмм (Арминар задумался) возможно все нужно только придумать как. Например когда-то существовало заклинание \"регенерация\" оно бы за пару минут тебя в идеальное состояние привело. Но седьмой круг",91036,null],[91040,"2026-07-04T01:05:51",9,"*Кварх реально выглядит так словно жив на грани драконьей живучести от ран.*",84658,null],[91041,"2026-07-04T01:06:42",32,"-Есть варианты более доступны но потребуется изрядно извернутся чтобы добыть достачно и применить как надо.",84658,null],[91042,"2026-07-04T01:07:15",32,"Банально раздеребить старые раны и зашить чтобы срослись правильно",84658,null],[91043,"2026-07-04T01:07:35",32,"-Больно зато цел",84658,null],[91044,"2026-07-04T01:08:05",32,"//Мне сначала показалось что за гранью",91040,null],[91045,"2026-07-04T01:08:36",9,"Квархадрон — Ты пришёл говорить обо мне? Буду жить, но снова сбегать... — *Посьеднее прозвучало с раздражением, но скорее всего он чуял когда реально надо уходить от угрозы, возможно поэтому жив.*",84658,null],[91046,"2026-07-04T01:09:02",9,"//Может чутка и за гранью, много ли драконьих ветеринаров?)",91044,null],[91047,"2026-07-04T01:10:06",32,"-Давай вместе двиним на восток ,там можно подрядился на работу и поискать жрецов или алхимиков. Да и я что-нибудь придумаю. Потихоньку приведём тебя в порядок",91045,null],[91048,"2026-07-04T01:10:25",32,"//один похоже скоро появится",91046,null],[91049,"2026-07-04T01:10:31",9,"Квархадрон — Раны остаются. Опыт не утратить, не способный нести ношу — изгой. — *Явно отрицает идею исцеления.*",91043,null],[91050,"2026-07-04T01:11:08",32,"-Да ты ещё пару таких \"опытов\" получишь и ласты склеишь!",91049,null],[91051,"2026-07-04T01:11:28",32,"(у Арминара сдало терпение и убеждения знамения 17+4",84658,null],[91052,"2026-07-04T01:12:07",9,"//К сожелению убеждение работает если есть шанс убедить",84658,null],[91053,"2026-07-04T01:12:32",32,"//а тут вообще без шансов?",91052,null],[91054,"2026-07-04T01:12:36",9,"*Лишь смеётся жутким утробным смехом, а потом слышится нечто похожее на кашель.*",84658,null],[91055,"2026-07-04T01:12:51",9,"Квархадрон — Нет.",84658,null],[91056,"2026-07-04T01:13:19",9,"//Можешь кинуть анализ, сложность 13",91053,null],[91057,"2026-07-04T01:13:41",32,"Я подхожу и протягиваю эму пузырек с зельем лечения. Поможет от кашля",91054,null],[91058,"2026-07-04T01:14:36",32,"//и так понятно что это красный дракон и характер у них не сахар",91056,null],[91059,"2026-07-04T01:14:52",9,"*Дракон лишь краем взгляда взглянул.*\n\nКвархадрон — лишь пересохло горло.",84658,null],[91060,"2026-07-04T01:15:29",32,"-Да по тебе видно что от крови пересохло",91059,null],[91061,"2026-07-04T01:15:37",32,"Пей давай",84658,null],[91062,"2026-07-04T01:18:00",9,"Квархадрон — Крестьяне? Те царапины уже зажили. — *Он наглядно. Словно насмехаясь раздирает себе чешую и кожу, легко, мощными коглями что способны дробить камни. Явно хвастается или красуется, кровотечение исчезло почти сразу и начало заживать? Кажется да, но медленно очень.*",84658,null],[91063,"2026-07-04T01:18:56",9,"*Снова утробный смех, потом кашель. Кварх встал и взял бочку у стены, с водой. Наклонил голову вливая воду прямо в дыры на лице и шее, большая половина пролилась на пол.*",84658,null],[91064,"2026-07-04T01:19:29",32,"(Арминар просто положил на пол комплект травника и сидит на это смотрит)",84658,null],[91065,"2026-07-04T01:19:40",9,"Квархадрон — Так... лучше.",84658,null],[91066,"2026-07-04T01:19:46",32,"С видом взрослого перед капризным ребенком",84658,null],[91067,"2026-07-04T01:20:20",9,"*Смотрит в ответ с видом мол \"ты не понимаешь\".*",91066,null],[91068,"2026-07-04T01:20:25",32,"(Арминар прислушивается интересно какое у него дыхание)",84658,null],[91069,"2026-07-04T01:20:43",32,"-Раскажи почему эти увечья для тебя так важны?",91067,null],[91070,"2026-07-04T01:20:49",9,"*Сейчас стало менее сухим и хрипящим, но немного булькает.*",91068,null],[91071,"2026-07-04T01:21:05",32,"(кровь в лёгких)",91070,null],[91072,"2026-07-04T01:23:28",9,"Квархадрон — История, самый сильный из молодых.",91069,null],[91073,"2026-07-04T01:24:22",32,"-Ты из-за ран сейчас самый слабый из своих потому что ещё немного и ты просто упадешь замертво",84658,null],[91074,"2026-07-04T01:24:37",9,"*Нос не задирал, сел снова у тлеющих углей. Кажется он выбрал сырую пещеру и подземелье, чтобы не дышать горячим воздухом что раздражает лёгкие.*",84658,null],[91075,"2026-07-04T01:24:39",32,"(спокойно говорит констатирует Арминар)",84658,null],[91076,"2026-07-04T01:24:53",9,"Квархадрон — Нет.",91073,null],[91077,"2026-07-04T01:25:30",9,"*Звук похожий на фырканье, полную уверенность в свою правоту.*",84658,null],[91078,"2026-07-04T01:25:41",32,"(драконорожденный сидит в позе мыслителя)",84658,null],[91079,"2026-07-04T01:25:51",9,"*Если посмотреть на рану что он себе нанёс, та затянулась на треть.*",84658,null],[91080,"2026-07-04T01:26:12",32,"/кстати действительно странно",91079,null],[91081,"2026-07-04T01:26:36",32,"У него что аналог \"дар стойкости\" есть",91080,null],[91082,"2026-07-04T01:29:19",32,"-Хмм толи я дурак, толи лыжи не едут.\n(Бурчит Арминар) Ладно есть идея. Давай устроим пари. Наперегонки пробежимся вдоль гор? Кто первый свалится тот и проиграл",91076,null],[91085,"2026-07-04T01:32:29",9,"Квархадрон — Три дня без перерыва — ты умрешь.",91082,null],[91086,"2026-07-04T01:33:20",9,"*Звучит так словно он проверял.*",84658,null],[91087,"2026-07-04T01:33:38",32,"-Хе-хе. Не попробуем не узнаем. \n(Спокойной сказал хилый маг) С утра на рассвете встанем на старт.",91085,null],[91088,"2026-07-04T01:34:57",9,"Квархадрон — Надо рыть тонелли. Рыцари скоро будут здесь. Они никогда не ждут сильного молодого дракона. — *Явно имеет приоритеты.*",84658,null],[91089,"2026-07-04T01:35:15",32,"/естественно проверял но байтить на поединок с рыцарями и уж тем более с кем-то из его братвы я не хочу. А так я его и из логова выманю из-за чего с рыцарями разменемся и...",91086,null],[91090,"2026-07-04T01:36:11",32,"-Ладно, тебе помочь? Я могу двигать рыхлый грунт сотнями килограмм и укреплять своды.",91088,null],[91091,"2026-07-04T01:36:43",32,"//да даже дописать не успел)",91089,null],[91092,"2026-07-04T01:36:59",9,"Квархадрон — Не льсти себе, я говорю с тобой только потому что мне скучно.",84658,null],[91093,"2026-07-04T01:38:04",32,"-Ага ага. А ещё потому что заботу почувствовал.\n(Сказал Арминар встал и двинулся на выход. Явно угрожая дракону что он потеряет такого интересного собеседника)",91092,null],[91094,"2026-07-04T01:38:20",9,"Квархадрон — Знаешь кто самый страшный дракон? — *Он словно хотел чтобы маг накинул вариантов.*",84658,null],[91095,"2026-07-04T01:38:35",32,"- умный",84658,null],[91096,"2026-07-04T01:38:55",32,"(спокойно бросил я явно льстя дракону)",84658,null],[91097,"2026-07-04T01:38:55",9,"Квархадрон — Правильно... Гриммилосерд...",84658,null],[91098,"2026-07-04T01:39:40",9,"*Он воспринял этот ответ по другому.*",91096,null],[91099,"2026-07-04T01:39:49",32,"-Учту. Гриммилосерд",91097,null],[91100,"2026-07-04T01:39:57",32,"/как?",91098,null],[91101,"2026-07-04T01:40:26",9,"//Решил что ты намекнул на тогл самого дракона о котором тот спросил",91100,null],[91102,"2026-07-04T01:41:00",32,"-Но мне казалось ты лучше всех видных мною",91099,null],[91103,"2026-07-04T01:41:20",32,"(ага потому что единственный)",91102,null],[91104,"2026-07-04T01:43:37",9,"Квархадрон — нет. Страшнее дракон без гордости, тот который не имеет логова, всегда на ногах, никогда не отдыхает, способен быть везде, всегда и никто его не заметит. Тень способная убить, играть с любым смертным от короля до крестьянина. — *Явно преувеличивал, но серьёзно говорил.* — Чёрный дракон с огненным дыханием...",84658,null],[91105,"2026-07-04T01:44:44",32,"(Встал у входа в зал. Понял что моя угроза уйти не имеет смысла. Пошёл обратно.)\n-А вообще смотри. Да характер чёрного и красного.\nСтрашнее только Тиамат из приданий. Но на то она и злая богиня",84658,null],[91106,"2026-07-04T01:44:46",9,"Квархадрон — Никогда не буду таким, не буду изгоем.",84658,null],[91107,"2026-07-04T01:46:18",32,"-Хмм (вот тут Арминар капитально загрузился) \nА что мешает и иметь логово и путешествовать? У меня например есть мой клан и в нем мой особняк. У меня есть логово но я путешествую",91106,null],[91108,"2026-07-04T01:46:40",32,"-Что мешает тебе поступить так же?",84658,null],[91109,"2026-07-04T01:46:53",32,"Ну смотри. Подожди дай договорю",84658,null],[91110,"2026-07-04T01:47:04",9,"Квархадрон — У меня... нет логова.",84658,null],[91111,"2026-07-04T01:48:36",32,"Вот есть королевство. Вот есть крестьяне. Прилетел и вручил старосте пару тысяч монет золотом и сказал что ты теперь барон этой земли а староста пусть подаст все нужные бумаги и будет твоей левой лапой в делах с людьми. И просто строй на своей земле себе логово",84658,null],[91112,"2026-07-04T01:49:16",32,"Нет не на этих землях, тут народ уж больно боевой",84658,null],[91113,"2026-07-04T01:49:29",32,"Но где-то в соседних запросто такое можно провернуть",84658,null],[91114,"2026-07-04T01:50:13",32,"//ну что там с драконом?",84658,null],[91115,"2026-07-04T01:53:28",9,"*Он пронзительно на тебя посмотрел, будто думая о чём то. Но похоже, этот дракон говорит как есть и что реально думает.*\n\nКвархадрон — Нет логова, нет золота, нет урожающей внешности. Каждый крестьянин видя мои раны думает что этого дракона легко прикончить. — *После серьёзных заявлений, на последнем сделал главный акцент, утробный смех, но на этот раз скорее насмешка.* — Каждый раз, ошибаются, недооценивают.",84658,null],[91116,"2026-07-04T01:54:23",9,"*Создаётся ощущение что ему нравится сражаться.*",84658,null],[91117,"2026-07-04T01:58:09",9,"//Я вижу ты оч любишь драконью тему)",84658,null],[91118,"2026-07-04T01:58:10",32,"-Ммм. Ну допустим раны нужны не обязательно. Их можно и подделать гримом без вреда силам.\nНо я серьёзно, предлагаю тебе стать сильнее восстановив тело. Мы можем просто найти и изучить заклинание например \"маскировка\" которая и даст \"раны\" и слабость.\nЛогово я тебе уже предложил решение тем более что логово которое куплено будут защищать от авантюристов и прочей нечисти сами люди хехе. Золото и заработать можно и это удивительно но факт привлечёт сильных противников желающих его отобрать.",84658,null],[91119,"2026-07-04T01:58:25",32,"//да и я его дожму. Благо он достаточно расслаблен чтобы я мог его прощупать и надавить куда надо",91117,null],[91120,"2026-07-04T01:59:21",32,"//я в ролках в которых это можно только за драконов и ролю",91117,null],[91121,"2026-07-04T02:00:34",9,"Квархадрон — это, история, награда моих сражений, силы... не сравнивай с никчёмными иллюзиями то что добыто и настоящее. — *Немного раздаражённо указывает на свои раны, явно не понравилось сравнение с иллюзией.*",91118,null],[91122,"2026-07-04T02:01:45",9,"*Кто-то гордится кучей сокровищь, кто-то властью, а Квархадрон своими ранами, словно те его неотьемлимая часть.*",84658,null],[91123,"2026-07-04T02:02:45",32,"-Хеее. Ладно можно только один вопрос? Последний так сказать.\nЧто ты будешь делать когда ран станет ещё больше и ты будешь умирать?",84658,null],[91124,"2026-07-04T02:03:48",32,"-Мне кажется собирать факты победы например черепа своих противников куда интереснее. Как минимум это не так больно",91122,null],[91125,"2026-07-04T02:04:24",9,"Квархадрон — Я не умру.",84658,null],[91126,"2026-07-04T02:04:54",9,"*Ни мгновения раздумий на ответ.*",84658,null],[91127,"2026-07-04T02:06:16",32,"-??? (Вид Арминара был полон непонимания. Нет неверия не было. Было именно непонимание как) Ладно закрою тему ран. Это всё-таки твое дело.\nА что насчёт рыцарей и логова?",91125,null],[91128,"2026-07-04T02:07:29",9,"Квархадрон — Земля, моя стихия. Те кто войдёт — не выйдет, если сам не захочу.",91127,null],[91129,"2026-07-04T02:08:26",9,"Квархадрон — Обрушить гору на врагов. — *Смеётся утробным смехом, хвастается.*",84658,null],[91130,"2026-07-04T02:08:49",32,"Киваю.\n- можно я с тобой побуду понаблюдаю что будет происходить. А может и поучаствую в бою.",84658,null],[91131,"2026-07-04T02:10:49",9,"*Смотрит оценивающе, думает.*\n\nКвархадрон — Ты умрёшь. Я обрушу вершину разом.",84658,null],[91132,"2026-07-04T02:11:25",32,"-А ты куда денешься?",91131,null],[91133,"2026-07-04T02:12:37",9,"Квархадрон — Прикончу тех кто не умрёт сразу и вырыю новый тоннель.",84658,null],[91134,"2026-07-04T02:13:39",9,"//Я давал тучу подсказок на счёт этого, с окружением)",84658,null],[91135,"2026-07-04T02:14:08",32,"-Есть несколько идей.\n(Спокойно выдал маг)\nКак пережить даже падение горы",84658,null],[91136,"2026-07-04T02:14:33",32,"//и я то все это вижу но у мага мудрость несколько ниже моей)",91134,null],[91137,"2026-07-04T02:14:33",9,"Квархадрон — Хочешь узнать ответ?",84658,null],[91138,"2026-07-04T02:15:22",32,"-Да я знаю ответ. Просто выйти заранее",91137,null],[91139,"2026-07-04T02:15:37",32,"Или быть рядом с тобой",91137,null],[91140,"2026-07-04T02:16:15",9,"Квархадрон — Нет и да. — *Он прищурил глаз.* — Иди за мной.",84658,null],[91141,"2026-07-04T02:16:56",32,"(иду за драконом.)\n/Первая попытка была намереным проебом кстати",84658,null],[91142,"2026-07-04T02:20:33",9,"*Он привёл тебя в часть коридора, цилиндр и заветвление, словно выплавленное и вылепленное в единый слой.*\n\nКвархадрон — Места, которые не обвалить... — *Он берёт камень и прожигает его огнём из дыр на шее и половины недостающей щеки пока не расплавит в течении полуминуты, а после повторяет с местом и размазывает как пластилин.*\n\nКвархадрон — Не каждый камень, не любая гора, но это та самая гора. — *Смотрит на реакцию.*",84658,null],[91143,"2026-07-04T02:21:45",9,"*Снова сухой кашель.*",84658,null],[91144,"2026-07-04T02:21:56",32,"-Известняк. Да я сам думал о необходимости сделать бункер но ты уже его сделал.",91142,null],[91145,"2026-07-04T02:22:49",32,"(Арминар был приятно удивлен смекалкой дракона. И весело улыбался)",91143,null],[91146,"2026-07-04T02:23:02",9,"Квархадрон — Да, но думаю. Если придавит гора — выживу.",91144,null],[91147,"2026-07-04T02:23:37",32,"//что-то вроде бетона изобрел дракон",91146,null],[91148,"2026-07-04T02:25:06",32,"В следующий раз можно ещё более твертые но ломкие части вкладывать например металлические конструкции. Тогда станет сильно долговечнее и жёстче.",91146,null],[91149,"2026-07-04T02:25:36",9,"Квархадрон — Большее и не нужно.",91148,null],[91151,"2026-07-04T02:26:47",32,"-Я учёный а не инженер. Я стремлюсь к максимуму и совершенству а не необходимому минимуму",84658,null],[91152,"2026-07-04T02:27:06",9,"//Действие логова дракона — логово падает вам на голову",84658,null],[91153,"2026-07-04T02:27:54",32,"//это понятно. Оно в убежище не упадет. И это главное.",91152,null],[91154,"2026-07-04T02:28:07",32,"(не упадёт же?",84658,null],[91155,"2026-07-04T02:28:41",9,"//Но никто не выкопается, под тонами то земли, кроме крота, тоесть дракона)",91153,null],[91156,"2026-07-04T02:30:05",32,"(Да но я с лепкой земли имею все шансы. А ещё я так докажу что чего-то стою. Совместная битва сближает)",91155,null],[91157,"2026-07-04T02:30:34",32,"//А умрёт перс ну и хрен с ним. Но я до последнего не дам этому произойти",84658,null],[91158,"2026-07-04T02:31:00",32,"А ещё с самим собственно кротом",91155,null],[91159,"2026-07-04T02:32:36",32,"//Кстати в темноте рассмотреть Арминара подновившего инвиз будет просто нереально",84658,null],[91160,"2026-07-04T02:33:16",9,"Квархадрон — У меня нет ни злата, ни логова. Каждый раз встречая достойного противника я своими же руками разрушал то что построил. — *Прижмуривает глаз, не расстроен, просто меланхолия.*",84658,null],[91161,"2026-07-04T02:34:56",32,"(подошёл и погладил лапу не боясь атаки ибо не проявлял ни капли враждебности) \n- все рано или поздно изменится. Либо к лучшему либо мы умрём. А так как ты точно не умрёшь то у тебя точно будет все к лучшему.\n\n/Выступление на вдохновение?",91160,null],[91162,"2026-07-04T02:35:46",9,"//Скорее выступление, чтобы он не атаковал хотя бы, он просил не трогать его",84658,null],[91163,"2026-07-04T02:36:07",32,"/roll d4",84658,null],[91165,"2026-07-04T02:36:14",32,"17+4+2",84658,null],[91166,"2026-07-04T02:36:23",32,"Выступление",84658,null],[91167,"2026-07-04T02:37:10",9,"//Ты 17 вродь использовал? Но там даже второй хватит, даже с 12 +бонусы.",84658,null],[91168,"2026-07-04T02:37:27",32,"/не использовал ты завернул заявку",84658,null],[91169,"2026-07-04T02:39:42",9,"*Просто отошёл явно раздражённый.*\n\nКвархадрон — В следующий раз пощитаю что ты напал почуяв шаги так близко без предупреждения. — *Не слишком контактный парень.*",84658,null],[91170,"2026-07-04T02:40:40",32,"-Я то точно не нападу. Но ладно. Не буду подходить.",84658,null],[91171,"2026-07-04T02:41:35",32,"-Дело твоё. (Начал разворачивать лагерь)",84658,null],[91172,"2026-07-04T02:41:51",9,"*Лишь фыркнул так что воздух слегка засвистел.*",84658,null],[91173,"2026-07-04T02:42:08",9,"//Прямо там?",91171,null],[91174,"2026-07-04T02:42:19",32,"Прямо в бункере да",91173,null],[91175,"2026-07-04T02:42:52",32,"В сторонке сажусь на перекус и так по мелочи",84658,null],[91176,"2026-07-04T02:43:28",9,"*Один недовольный дракон наблюдает за небывалой наглостью.*",84658,null],[91177,"2026-07-04T02:43:30",32,"Поджёг и поставил в вылепленую из земли подставку факел и начал перекус.",84658,null],[91178,"2026-07-04T02:43:46",9,"/roll +d20 испытываешь удачу",84658,null],[91180,"2026-07-04T02:44:22",32,"Будешь (протягиваю шесть пайков мяса.) Все что есть но немного перекусить",84658,null],[91181,"2026-07-04T02:44:24",9,"*Он просто ушёл куда-то вглубь.*",84658,null],[91182,"2026-07-04T02:44:46",32,"/не успел пригласить к столу",84658,null],[91183,"2026-07-04T02:45:15",9,"//Да да, дело только в этом)",84658,null],[91184,"2026-07-04T02:45:59",32,"//да понятно что логово дракона неприкосновенно и если бы я его реально не задел ты бы даже удачу не кидал.",91183,null],[91185,"2026-07-04T02:46:32",32,"Здесь я реально сокрушаясь что не успел пригласить на перекус не мной",91182,null],[91186,"2026-07-04T02:46:46",9,"//Тебе повезло что он не так сильно привязан к логову, потому что оно не первое далеко)",84658,null],[91187,"2026-07-04T02:47:13",32,"И это я тоже учитывал",91186,null],[91188,"2026-07-04T02:47:36",32,"/Долгий отдых до утра",84658,null],[91189,"2026-07-04T02:47:47",32,"Кину новые знамения?",84658,null],[91190,"2026-07-04T02:48:16",9,"//В целом, я чёрт знает. Жака и Иму что, будто не входили выходит",84658,null],[91191,"2026-07-04T02:48:45",9,"//Когда пригодятся в след раз тогда и кинь новые, спешить некуда.",91189,null],[91192,"2026-07-04T02:48:53",32,"(ну да похоже я один пошёл... И не вернулся",84658,null],[91193,"2026-07-04T02:49:49",32,"Но ладно тянуть товарищей в суицидальную миссию страшновато",84658,null],[91194,"2026-07-04T02:59:15",9,"//Опыт вам выдам немного заранее @Xaosick и @Jak_Zak \n\nМайло: 100 опыта за социалку и бой с Иму + 100 опыта за остальнуб социалку. Всего — 200\n\nАрминар: 100 опыта за социалку и бой с Иму + 100 опыта за остальнуб социалку + 100 опыта за разговор по душам с Квархадроном. Всего — 300",84658,null],[91235,"2026-07-04T09:19:09",32,"/roll 2d20",84658,null],[91237,"2026-07-04T09:19:30",32,"/Знамения. Мне надо знать от чего отталкиваться",84658,null],[91238,"2026-07-04T09:39:03",32,"Удачные кубики кстати",91236,null],[91241,"2026-07-04T10:06:52",42,"// капец скоро будет 3 лвл",84658,null],[91242,"2026-07-04T10:10:34",9,"//После этого квеста — точно",91241,null],[91256,"2026-07-04T10:46:38",32,"//у меня сотки опыта не хватило",84658,null],[91257,"2026-07-04T10:52:54",9,"//Некоторым и 10 не хватало. Было)",84658,null],[91258,"2026-07-04T10:55:29",32,"//Ладно грохну пару рыцарей и наберу.",84658,null],[91259,"2026-07-04T10:57:39",32,"(Арминар встал ,потянулся. Стальные нервы и не только позвякивают при утреней разминке под светом факела.)\n-На удивление хорошо поспал.\n(Сказал Арминар и двинулся искать дракона)",84658,null],[91288,"2026-07-04T12:42:59",42,"//180",91256,null],[91289,"2026-07-04T12:43:56",42,"// так, я так и остался за пещерой с иму?",84658,null],[91302,"2026-07-04T12:56:17",32,"/ну в диалоге участвовал только Арминар. Так что это как-то надо отыграть",91289,null],[91307,"2026-07-04T13:04:33",42,"°проснулся у входа с пищеры и начал упражняться бья кулаками по пещере°",84658,null],[91313,"2026-07-04T13:31:36",32,"-Не шуми дракона разбудишь.\n(Выглянул из пещеры позевывая.\nДа путь с моим интеллектом запомнить было не сложно. Отмечал повороты в ассоциативной памяти на пальцах. Загибал нужный в зависимости от поворота. А потом восстановил в памяти путь обратно)",91307,null],[91314,"2026-07-04T13:34:38",32,"(с фразой \"не шуми дракона разбудишь\" я конечно шутил.  Так как дракон уже явно не спал где лег вчера)",84658,null],[91331,"2026-07-04T15:39:16",9,"*Это было чертовски сьожно, появилась дюжина новых поворотов и не всегда поймёшь в какую сторону. Ты едва угадал путь, Квархадрон рыл, много рыл своими мощными лапами раздвигая землю, камни, гравий, с силой уплотняя их.*",91313,null],[91332,"2026-07-04T15:39:32",9,"//Ищешь/ищете дракона?)",84658,null],[91333,"2026-07-04T15:52:22",32,"//неа осматриваюсь на предмет рыцарей",91332,null],[91334,"2026-07-04T15:53:17",32,"//я сейчас вряд-ли смогу играть. 3% на телефоне и ещё не скоро зарядка",84658,null],[91335,"2026-07-04T15:53:43",9,"*Пока не видать ничего и никого. Но идти сюда им несколько часов.*",91333,null],[91336,"2026-07-04T15:54:21",9,"//С слюзниками бы пешил сначала. Не уверен что жака читал что было",91334,null],[91357,"2026-07-04T16:27:10",42,"// прочëл",84658,null],[91358,"2026-07-04T16:27:38",42,"// хочу убить и того и тех как игрок, мор xp",84658,null],[91639,"2026-07-04T20:00:34",32,"//Я тут",84658,null],[91644,"2026-07-04T20:17:46",42,"// тута",84658,null],[91649,"2026-07-04T20:43:34",9,"//Я жду ваших взаемодействий, вы вчера раздедились, решать чёт надо за персонажей и почему Майло не пошёл бы тоже решить. Вы сейчас вольны выбрать сторону, своё решение и все такое, думайте @Jak_Zak @Xaosick",84658,null],[91650,"2026-07-04T20:45:15",42,"— ладно. Тогда так\n°разминается делая отжимания на одной руке°",84658,null],[91652,"2026-07-04T20:45:30",42,"/r 1d20 +6 на сколько круто отжимается",84658,null],[91654,"2026-07-04T20:50:36",9,"*Иму не понимает но повторяет. Правда для кобольда который может нести вес в дюжину раз больше себя это не стоит никаких усилий.*\n\n//Без бросков делает не хуже)",91650,null],[91657,"2026-07-04T20:52:12",32,"(Арминар присвистывает) \n-Ребята не поверите я с драконом подружился... Пусть и пока в одностороннем порядке. Но я работаю над тем чтобы процесс двинулся дальше.",84658,null],[91658,"2026-07-04T20:53:11",42,"— вот и чудно, что тогда рыцарей мочить с не мирным людом? \n°продолжает отжиматься, уже на одном пальце°",84658,null],[91659,"2026-07-04T20:53:22",42,"// думаю этот бросок позволяет)",91653,null],[91660,"2026-07-04T20:53:54",32,"-Я как всегда самый слабый (подумал драконорожденный и с помощью лепки земли сделал трон из грязи и уселся поддерживая твёрдость и узоры резьбы)",84658,null],[91664,"2026-07-04T20:55:32",42,"— так у вас магов сила от ума, а не от мышц. Хооотя я слышал историю с волшебником что ходит с вырванным деревом с корнем вместо посоха.. Страшная фигня",84658,null],[91667,"2026-07-04T20:56:50",32,"//вот этот?",91664,null],[91669,"2026-07-04T20:58:13",42,"// не, я видел инди мульт где волшебник ходит с деревом и использует как посох, но враги быстрее раздавлялись чем он произносил заклинание",91667,null],[91670,"2026-07-04T20:58:48",32,"//ну я что-то похожее то же видел. Просто мем первый в голову пришёл",91669,null],[91671,"2026-07-04T20:59:34",42,"// вот что делают ваши характеристики через кубы",91666,null],[91673,"2026-07-04T21:00:44",32,"//Не знаю у меня всегда хорошо падало",91671,null],[91674,"2026-07-04T21:01:41",32,"//помню было\n18 17 15 15 14 7",84658,null],[91675,"2026-07-04T21:02:20",9,"// 18 17 16 16 12 10 было у меня вродь однажды",84658,null],[91677,"2026-07-04T21:02:37",9,"//Но так и не играл там",84658,null],[91678,"2026-07-04T21:06:50",9,"*Со стороны Дракеризады, меж разрушенных крепостей идёт процессия... странно. Издалека видно что приехали не просто рыцари. Герои у предгорий, так что могли бы наблюдать. Отряд с телегой на которой лежит что-то чёрное, не разглядеть так далеко, но кони в броне, воины в латах.*",84658,null],[91679,"2026-07-04T21:08:26",32,"(интуиция Арминара которая граничит с экстрасенсорикой даже среди магов прорицателей подсказывала что это похоже пиздец)",84658,null],[91680,"2026-07-04T21:08:27",42,"— тааак, я не особо умëн.. Но предлагаю заманить тебе\n°показал пальцем на Арми\n\n— их в пещеру и после раздавим их большую часть",84658,null],[91681,"2026-07-04T21:10:04",32,"(да телега Арминару вот прямо сходу не понравилась)",91678,null],[91682,"2026-07-04T21:10:47",32,"//так ребята я похоже не могу сегодня играть меня мой первый мастер на игру позвал и он мне должен уже две недели пропусков",84658,null],[91683,"2026-07-04T21:16:13",9,"*Перед вами на небольшом расстоянии появилась иллюзия глаз на мгновение, те посмотрели на вас, на пещеры и ищезли.*",84658,null],[91693,"2026-07-04T22:06:53",9,"//Короче, я щас боюсь за вас. И поэтому скажу так — \"Сейчас решение лежит на вас и любое оно будет иметь последствия, это не бой с крысами в канализации\". Не хочу тпк, вы даже не 3-4 уровней 🫠🫠🫠",84658,null],[91694,"2026-07-04T22:08:06",9,"//Но вы вольны поступать кск захотите. По сути квест был в том чтобы найти дракона, дальше историю пишите вы\n🔥😎🔥\n   👉👉",84658,null],[91695,"2026-07-04T22:08:27",42,"// консервные банки нам не помеха",84658,null],[91696,"2026-07-04T22:10:13",32,"//Спасибо но я и так понял что заруба будет не из лёгких",91694,null],[91700,"2026-07-04T22:13:39",42,"// вообще есть идея, ты сбеги к дракону, а я с иму перекроем путь гигантским камнем и сбежим поверх горы, я атлет и мне не почëм скорость лазанья",84658,null],[91727,"2026-07-04T22:30:34",32,"//перепиши это как обращение к Арминару. Можно просто на ушко шепнуть.",91700,null],[91835,"2026-07-05T00:23:23",9,"//Да, а что с тем драгоценным камнем что Квархадрон вам выкинул, он не вернулся по него",91727,null],[91861,"2026-07-05T06:28:17",32,"//если его ещё не подобрал Майло то подберу в сумку я. Отдам когда будет возможность",91835,null],[91874,"2026-07-05T07:53:37",42,"— Арминар, тут есть такое предложение. Прячься ты в пещеру, и примани рыцарей. А после как они подойдут я с иму сбросим камень на них и закроем проход. Нас то не догонят. Я лазаю отмено, могу иму на спине протащить чтобы точно сбежать по верху горы",84658,null],[91876,"2026-07-05T08:10:23",32,"- идея не очень. Здесь постоим встретим рыцарей за собой обрушим туннель и и будем вместе сражаться \n(Проявил изрядную паранойю волшебник и толком ничего не сказал и при этом оставил друга близко)",84658,null],[91877,"2026-07-05T08:17:11",42,"— тогда скинем булыжник так сильно чтобы он покатился на самих рыцарей и раздавил их всех",84658,null],[91878,"2026-07-05T08:18:25",9,"//Кинь историю",91876,null],[91879,"2026-07-05T08:18:59",9,"//Арминар же мог знать основополагающие стран?",91878,null],[91884,"2026-07-05T08:28:26",32,"//да отличное образование",91879,null],[91885,"2026-07-05T08:28:37",32,"/roll d20+3",91878,null],[91887,"2026-07-05T08:33:15",9,"*Ходят байки о правителе Кравлости Темнограда что чёрные доспехи, его могущества — Тёмного лорда возят на телеге за ним. Ну и что тот драконов по несколько штук валит по четвергам. Насколько это всё правда неизвестно, но в сражении один на один со взрослым драконом, из того что известно клану — больше шансов у Тёмного лорда.*",84658,null],[91888,"2026-07-05T08:34:53",9,"*Страна маленькая, страна личности и рыцарства. Сам правитель темнограда всегда на ногах и помогает отбивать набеги монстров и решает проблеммы силой.*",84658,null],[91889,"2026-07-05T08:36:04",32,"😁",91679,null],[91890,"2026-07-05T08:38:07",9,"//Умный игрок — кайф. Ещё бы прислушивался к своей интуиции)))",84658,null],[91891,"2026-07-05T08:39:12",32,"-Кажется это тёмный король и кажется нем не туда.\n(Сказал маг и двинулся в пещеру потому что заклинание школы прорицания четвёртого круга. Те самые глаза появившиеся в воздухе, мага тоже капитально напрягли)",91888,null],[91892,"2026-07-05T08:40:54",32,"//пока что я буду держать не использованной минимум одну ячейку для того чтобы устроить пафосный побег",84658,null],[91895,"2026-07-05T08:45:33",9,"*Большой отряд рыцарей медленно движется к предгорью по ложбине, а после и в гору к логову дракона крутить тому хвост.*",91894,null],[91896,"2026-07-05T08:46:26",42,"°готовлюсь с иму сбросить камень в нужный момент как рыцари начнут заходить в пещеру°",84658,null],[91897,"2026-07-05T08:46:36",42,"// хоть с каким-то, но опытом уйду",84658,null],[91898,"2026-07-05T08:47:09",32,"/Мне кажется черному больше такая тема подойдёт",84658,null],[91900,"2026-07-05T08:49:13",9,"//Кто что и куда, Майло с Иму делают хню, а Арминар?",84658,null],[91902,"2026-07-05T08:53:48",32,"А Арминар просто сидит на троне из грязи и встречает гостей",91900,null],[91906,"2026-07-05T09:00:58",9,"//Вы решили ничего не делать?",84658,null],[91907,"2026-07-05T09:01:43",42,"// а что сразу хуйня, нормас идея. Опыт пофармлю до 3",91900,null],[91908,"2026-07-05T09:02:19",42,"// а так да, нормас идея. Убьëм конкурентов иму что будут досаждать будущему дракону",84658,null],[91909,"2026-07-05T09:02:51",32,"//я просто жду. Я хочу с темным монстром поговорить",84658,null],[91910,"2026-07-05T09:05:27",9,"*Процессия медленно движется всё ближе. О вас уже знают и два всадника прискакали перёд всех, посланцы..*\n\nПосол — Его могущество прибудет сразить дракона! Всем освободить путь и уйти отсюда.",84658,null],[91911,"2026-07-05T09:05:33",42,"// у меня эта песня ассоциациируется с охотой на гномов",91894,null],[91912,"2026-07-05T09:05:49",42,"// думаю эта не будет хуже",91899,null],[91913,"2026-07-05T09:07:03",42,"// ну я прячусь за валуном с Иму, тут вот Арми переговорщик",91910,null],[91914,"2026-07-05T09:24:54",32,"- я всё-таки хочу встретится с вашим лордом. \n(Спокойной сказал комок грязи в форме драконорожденного сидящий на троне из земли и грязи.) Да и мне есть что рассказать. \nДа и спросить многое хочу",91910,null],[91915,"2026-07-05T09:26:08",9,"Посол — Уходите, именем его могущества Тёмного лорда.",91914,null],[91916,"2026-07-05T09:26:36",9,"*Топчутся на конях рядом.*",84658,null],[91917,"2026-07-05T09:28:09",32,"-Ладно сам виноват.\n(Сказал Арминар встал и ушел в пещеру. Растворяясь в тьме)",91915,null],[91918,"2026-07-05T09:28:40",32,"/roll 2d20+2\nСкрытность",84658,null],[91920,"2026-07-05T09:28:56",32,"/roll 2d20+2\nСкрытность",84658,null],[91922,"2026-07-05T09:29:15",9,"*Послы переглянулись и ускакали обратно, с отчётом.*",84658,null],[91923,"2026-07-05T09:29:19",32,"(у меня из-за грязи приимущество.)",84658,null],[91924,"2026-07-05T09:29:42",9,"//Пох, я бы броска не попросил даже)",91923,null],[91925,"2026-07-05T09:30:16",32,"(есть идея где там дракон?)",91924,null],[91926,"2026-07-05T09:30:54",32,"//огонь тема",91912,null],[91927,"2026-07-05T09:30:57",42,"°спустился к Арми°\n— тааак? Ну что убивать?) \n°чушет руки и лыбится°",84658,null],[91928,"2026-07-05T09:32:07",32,"-Уходим в глубь. Мы это чудовище не потянем даже в троем. \nДля него если мы нападем в троем это не мы его окружили а наступать можно в любом направлении",91927,null],[91929,"2026-07-05T09:32:37",42,"°Выражение лица майло°",84658,null],[91930,"2026-07-05T09:32:46",32,"-Потому я с темным лордом воевать не буду",84658,null],[91933,"2026-07-05T09:34:03",42,"— а что так?? Обычный человек наверное. Тоже давится камнем",84658,null],[91934,"2026-07-05T09:35:37",32,"-Обычный человек камень такого размера (вспоминает защищеный булыжник) и с места сдвинуть не сможет.\nА там даже не ты, а лучшая версия тебя.",91933,null],[91935,"2026-07-05T09:37:30",32,"(И вообще. Арминар повел товарища уже знакомым маршрутом в бункер показал куда идти когда станет жарко)",84658,null],[91936,"2026-07-05T09:37:57",42,"— лучше меня некого нет дружок, ну раз так.. То ладно, доверюсь\n°потопал за драконорождëнным°",84658,null],[91937,"2026-07-05T09:38:12",9,"*Пришлось немного поплутать, Арминар услышал знакомое, тяжёлые сопение за спиной. Дракон поняв кто вы перестал прятаться в своде своих нор.*\n\nКвархадрон — На этот раз ты с друзьями. — *Он посмотрел на вас единственным глазом, проворчал утробным голосом не размыкая челюсти, и поплёлся дальше, будто ему плевать.*\n\n*Майло видит во тьме что половина черепа дракона счезанна до кости, шея раздзербанена, очень много ран старых, шея вся в ранах, нет местами чешуи, передние лапы очень мощны. Дракон выглядит так словно должен был помереть но каким-то чудом все ещё жив.*",84658,null],[91938,"2026-07-05T09:39:08",9,"*Размер дракона внушал трепет (большой).*",84658,null],[91939,"2026-07-05T09:39:37",9,"Иму — Дракон... — *Ему очень интересно.*",84658,null],[91942,"2026-07-05T09:41:42",32,"-Привет Квархадрон. У меня тебе новости, не знаю хорошие или плохие но там Тёмный лорд по твою душу прибыл иии это чудовище говорят уже не одного дракона под нож пустило, рас на рас и что важнее он может в магию, минимум 4 круг. Будь очень внимателен не попадай под гипноз, извержение земли проклятия слепоты/глухоты и кучу другой мерзости которую я могу назвать сходу по типу банального скользкого пола под лапой",91937,null],[91943,"2026-07-05T09:41:55",42,"— ухх страшила\n°рсматривает дракона°",84658,null],[91944,"2026-07-05T09:42:01",32,"(спокойно рассказал Арминар что узнал)",84658,null],[91945,"2026-07-05T09:45:56",32,"-в общем противник достойный и от обвала потолка может и не помереть.\n(Развел руками Арминар)",91942,null],[91946,"2026-07-05T09:46:08",9,"*Дракон сразу заинтересовался, он наклонился и сверлил Арминара единственным глазом, пытаясь понять не врёт ли он. Новость его впечатлила настолько что он проигнорировал оскорбление.*\n\nКвархадрон — ...раз так... — *Он залился жутким утробным смехом, его хвост в предвкушении качнулся.* — Ему хватило одного удара чтобы изуродовать меня навсегда, в этот — не дам шанса.\n\n*Дракон до сих пор не допускает даже мысли что умрёт.*",91942,null],[91947,"2026-07-05T09:47:55",42,"— мда... Мозги не моя сила, как нужны будут мускулы я тут\n°плюхнулся на землю и делает грязевого ангела°",84658,null],[91948,"2026-07-05T09:48:24",9,"Иму — Кажется дракон будет бить кого-то.",91947,null],[91949,"2026-07-05T09:48:25",32,"(сначала просто выслушал вздохнул от уверенности в собственном бессмертии а потом спохватился) -Вы уже встречались?",91946,null],[91950,"2026-07-05T09:49:29",32,"-Наша задача проста. Отвлечь массовку пока большые дяди развлекаются",91947,null],[91951,"2026-07-05T09:49:45",9,"*Дракон посмотрел в пустоту, а потом наклонил голову и провел рукой по отсутствующей части шеи, лица, цеки, рогов и чуть ниже самой ключицы.*\n\nКвархадрон — Даааа...",91949,null],[91953,"2026-07-05T09:51:13",9,"Квархадрон — Вы умрёте. — *Не угроза, не насмешка, будто цитировал сухой факт.*",91950,null],[91954,"2026-07-05T09:53:11",32,"- не-а (сказал драконорожденный и начал что-то мастерить высушивать и перетирать магией почву в мелкую пыль собирая в склянки сверх сухую известняковую пыль)",91953,null],[91955,"2026-07-05T09:54:14",32,"(голос этого \"не-а\" был настолько безбашено весел хе)",91954,null],[91956,"2026-07-05T09:54:31",42,"— ну не так уж и плохо. Люблю консервы мять по утрам",91950,null],[91957,"2026-07-05T09:55:09",9,"*Дракон не стал ждать, просто обернулся и поплёлся вглубь решив что разговор на этом окончился.*",84658,null],[91958,"2026-07-05T09:55:35",9,"Иму — Консервы? Что это.",91956,null],[91959,"2026-07-05T09:56:32",9,"*Любопытство и бесстрашие кобольда не знало границ.*",91958,null],[91960,"2026-07-05T09:57:15",32,"//так у меня тут шквал накатывает я временно не смогу играть под дождем",84658,null],[91972,"2026-07-05T10:49:54",42,"— банки железные которые тебе в гнездо подавали\n// думаю он пойдëт потому что в свалке жил",91958,null],[92747,"2026-07-05T14:26:10",32,"-Так мне нужен факел и тифлинг с моей пращей.\nГорящий факел куда-то к рыцарям и банку с пылью в след. Главное не оглохнуть и не задохнутся в последствии",91954,null],[92765,"2026-07-05T14:30:41",9,"*Иму походе не понял, он видел только стеклянные и основном бутылки, всегда разбитые.*\n\n//Средневековая свалка, чё. Металл на вес золота часто",91972,null],[92787,"2026-07-05T14:32:45",32,"//Да я как игрок уже начинаю ненавидеть мистический заряд. Ибо слишком привык к огненной стреле и в умелых руках эффект поджигания похоже полезнее",92747,null],[92955,"2026-07-05T15:05:01",42,"// я поспал после смены и тоже тут",84658,null],[92960,"2026-07-05T15:06:08",42,"// ладно, Иму с Майло заживëт. Майло ещë тот любитель поесть. Протеиничик с белком любит",92765,null],[92966,"2026-07-05T15:08:18",42,"°встал весь извазюкан грязью и отдал факел Ами°\n— Постараюсь не оглохунуть",92747,null],[93099,"2026-07-05T15:23:19",32,"Передаю исчадию флакончик с пылью и говорю.\n-Так смотри узкий коридор враги, кидаешь чтобы разбилось в стену или потолок. После я добавлю факел. И драпаем",84658,null],[93138,"2026-07-05T15:27:17",42,"— ага... А зачем?",84658,null],[93158,"2026-07-05T15:29:52",32,"-Не поверишь но горит все. Нужно только задать условия.",84658,null],[93191,"2026-07-05T15:33:01",32,"/интересный факт. Дракон перепутал несколько разных веществ из-за чего пытается использовать негорючий порошок",84658,null],[93217,"2026-07-05T15:35:49",9,"//Интересный факт, пыль тоже может ебануть. Я видел ^^",84658,null],[93251,"2026-07-05T15:39:36",32,"//да но тут надо дракон надо известняк в негашеную известь перестроить и уже этот порошок будет круче чём черный порох",93217,null],[93259,"2026-07-05T15:40:09",32,"//конкретно известняк не горюч вообще. Но у драконида алхимия в голове путается",93217,null],[93270,"2026-07-05T15:41:25",9,"//Вы чего-то ждёте, или?",84658,null],[93274,"2026-07-05T15:41:49",42,"—Хорошо\n\n°взял флакон с пьлью потопал ближе к выходу где есть узкий проход°",84658,null],[93306,"2026-07-05T15:47:16",32,"(но даже так пыль наглухо ослепит всех в нее попавших ибо трение глаз от песка не просто опасно для зрения а наверняка лишит роговицы)",93274,null],[93314,"2026-07-05T15:48:05",32,"Как вооружились двигаем в туннель по души рыцарей",93274,null],[93318,"2026-07-05T15:48:18",42,"// всë типо мы уже у входа где узких коридор и ждëм рыцарей",84658,null],[93357,"2026-07-05T15:54:12",9,"*Снаружи нарастает шум. Гости прибыло и вздруг — звук удара молнии. Пещеры щатряслись на мгневение и тот камень что был установлен как ловушка похоже потерял опору и скатился.*\n\n*Снаружи кто-то ударом молнии обвалил вашу незатейливую конструкцию.*",84658,null],[93421,"2026-07-05T15:58:57",42,"— ооооооу.. А мы так старались с иму.. СДОХНИТЕ ВЫБЛЯДКИ! \n°Готовлюсь в нужный момент бросить банку с пылью на потолок чтобы расыпалась пыль над ними°",84658,null],[93435,"2026-07-05T15:59:42",32,"//это действие капитально траванет и полностью ослепит",93421,null],[93446,"2026-07-05T16:00:32",32,"Спокойно прислонился к стенке как простой булыжник.\n-Ну этого требовало ожидать. Будем ждать дальше",93421,null],[93536,"2026-07-05T16:07:08",9,"*Слышится лай. Похоже первыми пойдут собаки.*",84658,null],[93540,"2026-07-05T16:07:31",9,"//Сори, я на игре другой ща, в этом де чате, а там тпк почти моему персу",84658,null],[93582,"2026-07-05T16:11:32",32,"(телепатией) -Заряжай кислоту( у тебя банка есть) побереги подарок для латников. \n(Я выхожу немного вперёд и припадаю к земле становясь камнем. У меня запах куска камня и визуально. Интелекта бобиков не хватит распознать засаду) Готовлю громовую волну как бобики добегут если добегут",93536,null],[93669,"2026-07-05T16:21:07",42,"°отхожу от радиуса Громовой волны°",84658,null],[93720,"2026-07-05T16:24:46",32,"//я потому вперёд и Вышел чтобы ты в радиусе не был",93669,null],[94197,"2026-07-05T17:24:06",9,"Такс",84658,null],[94198,"2026-07-05T17:24:06",9,"Я щас чаю заебеню и вести настоящего дракона",84658,null],[94202,"2026-07-05T17:26:32",32,"//?",84658,null],[94305,"2026-07-05T17:45:32",9,"*Собаки входят первыми, словно на охоте, мастифы и ??? (Я зыбыл вторую породу что по норам ебенит) они видят Майло и Иму и начинают на них лаять.*",84658,null],[94307,"2026-07-05T17:45:58",9,"Иму — Грррррр. — *Рычит на них став на четвереньки.*",84658,null],[94312,"2026-07-05T17:47:10",9,"*Собаки совсем не боятся и немного рассредоточившись по проходу медленно идут вперёд. Как бы арминар не приготовился — всех волной не задеть.*",84658,null],[94327,"2026-07-05T17:50:04",42,"°готовится встать сразу перед Арми после Громовой волны чтобы принять удар псов на себя°",84658,null],[94329,"2026-07-05T17:50:25",32,"//В том и прикол что я и не рассчитываю на это. У меня есть прикол который их удивит.",94312,null],[94332,"2026-07-05T17:50:46",32,"-майло кислота!(Телепатия)",94327,null],[94335,"2026-07-05T17:51:04",9,"Пёс — Ахпхаф!",84658,null],[94338,"2026-07-05T17:51:20",32,"//Арминар ожидает",94337,null],[94341,"2026-07-05T17:51:43",42,"°бросаю кислоту°",94332,null],[94346,"2026-07-05T17:52:03",32,"/собакам очень больно и обидно 😁",94341,null],[94350,"2026-07-05T17:52:43",42,"// да плевать. Это опыт)",94346,null],[94355,"2026-07-05T17:53:10",32,"//это паника среди хвостатых из-за чего у них стайные инстинкты сломаются и все налетят на громовую",94350,null],[94360,"2026-07-05T17:54:29",9,"//Опишите пж, я не ипу что вы хатите",84658,null],[94365,"2026-07-05T17:55:50",32,"Я нахожусь перед Майло как валун",84658,null],[94368,"2026-07-05T17:56:07",42,"//А я Бросаю кислоту в кучу шавок",84658,null],[94369,"2026-07-05T17:56:19",32,"Он кидает кислоту и провоцирует свору на атаку. Мы в ткнеле из-за чего они сходятся на нас и конкретно передо мной чтобы атаковать Майло",84658,null],[94371,"2026-07-05T17:56:31",32,"Я эбашу громовой как подготовленное действие и из засады",84658,null],[94375,"2026-07-05T17:57:56",42,"//А после громовой я его прекрываю собою",84658,null],[94378,"2026-07-05T17:58:18",32,"//Если будет от кого. Потери своры явно будут огромные это даже самых дрессированных с учётом громкого звука напугает",94375,null],[94387,"2026-07-05T18:00:14",42,"// кто знает. В этом месте тут всë бестрашно и нагло",84658,null],[94393,"2026-07-05T18:01:52",9,"//А попади ка ты кислотой)",84658,null],[94395,"2026-07-05T18:02:34",42,"/r 1d20 +6",84658,null],[94399,"2026-07-05T18:03:11",42,"// бросок от силы т.к. металка и есть владение даже импровизированным оружием",84658,null],[94401,"2026-07-05T18:03:49",9,"//Ясно... что же, значит кидай урон от импровизированного)",84658,null],[94403,"2026-07-05T18:04:13",42,"// а кислотой?",84658,null],[94404,"2026-07-05T18:04:31",42,"/r 1d4 импровизированное",84658,null],[94407,"2026-07-05T18:04:38",9,"//Ьак ты кислоту кидаешь или просто как камнем ебенишь?)",84658,null],[94408,"2026-07-05T18:04:54",9,"//+4 сила, да?",94405,null],[94409,"2026-07-05T18:04:56",42,"// оба",94407,null],[94411,"2026-07-05T18:05:14",42,"// в любом случае склянка разобьëтся",84658,null],[94413,"2026-07-05T18:05:25",9,"//Ну, так не работает по механу, поэтому",84658,null],[94414,"2026-07-05T18:05:37",42,"// ну тогда как кислота",84658,null],[94415,"2026-07-05T18:05:44",32,"//И окатит на 2д6 на соседние клетки",94411,null],[94416,"2026-07-05T18:05:45",42,"// я тут уже хз",84658,null],[94421,"2026-07-05T18:06:28",32,"//но ведь это логично? Или как оно по механу",94413,null],[94422,"2026-07-05T18:06:30",9,"*Склянка кислоты просто гулко разбивает череп псу и застряёт в нём, тот даже пискнуть не успел.*",84658,null],[94423,"2026-07-05T18:06:50",9,"//Он ебанул просто как камнем)))",84658,null],[94425,"2026-07-05T18:06:59",32,"//Вася ты дурак!",94422,null],[94426,"2026-07-05T18:07:03",42,"// ;-;",84658,null],[94428,"2026-07-05T18:07:19",42,"// я кастую огненный шар",84658,null],[94429,"2026-07-05T18:07:26",32,"//Ну ладно пусть останется",94426,null],[94436,"2026-07-05T18:08:18",32,"Ну так он и метнул",94433,null],[94437,"2026-07-05T18:08:51",9,"//А он её метнул как импровизированное! Вы видели мензурки средневековья??? Там можно как ксмнем заебенить 😎",84658,null],[94440,"2026-07-05T18:09:14",42,"// склянки, камень всë что не орудие считается импровизированным",94437,null],[94441,"2026-07-05T18:09:16",32,"//Просто пращей которая и создана для дальнего поражения. \nТут сказано что метаешь с руки",84658,null],[94442,"2026-07-05T18:09:21",9,"//Щато кислота осталась",84658,null],[94443,"2026-07-05T18:09:35",32,"//ладно пох",94442,null],[94445,"2026-07-05T18:09:41",42,"// от туда и бонус владения",94440,null],[94446,"2026-07-05T18:09:45",32,"//пригодится ещё",84658,null],[94447,"2026-07-05T18:10:12",9,"*Собаки залаяли сильнее, шарчали и ближайшие бросились к майло. Атаковать.*",84658,null],[94449,"2026-07-05T18:11:03",32,"//Жду до последнего когда шавки уже ко мне первые подбегут. Чтобы захватить максимум целей",94447,null],[94453,"2026-07-05T18:11:14",42,"°встал в стойку \"готов пинать ногами\"°",84658,null],[94456,"2026-07-05T18:11:35",9,"//Да ебашьте уде, я понял",94449,null],[94461,"2026-07-05T18:11:59",32,"//Сколько их в зоне поражения? И сколько вообще",94456,null],[94463,"2026-07-05T18:12:08",9,"//Всех не заденешь, но большую часть да, кста скок там радиус закла? Пещера широка достаточно",84658,null],[94465,"2026-07-05T18:12:19",9,"//Две дюжины",94461,null],[94469,"2026-07-05T18:12:54",32,"/roll 2d8.\n(Бонусов от атаки из засады не будет? Например спас с помехой?)",84658,null],[94474,"2026-07-05T18:13:24",9,"/roll 20d20 шоле",84658,null],[94479,"2026-07-05T18:13:43",32,"//Куб пятнадцать на пятнадцать.\nКлетка я посередине и две соседние на три в длину",94463,null],[94481,"2026-07-05T18:14:15",32,"(сила закл 13)",94475,null],[94484,"2026-07-05T18:14:42",32,"/11 штук отбросило",84658,null],[94485,"2026-07-05T18:14:53",9,"*Многих собак звук лишь оглушил, только половину откинуло, но они кажется живы и встают на ноги.*",84658,null],[94487,"2026-07-05T18:15:06",32,"//Ладно иня?",84658,null],[94491,"2026-07-05T18:15:20",9,"Иму — Гррррр",84658,null],[94492,"2026-07-05T18:15:29",9,"//Ходите вы потом собаки",84658,null],[94495,"2026-07-05T18:15:54",32,"//Ещё одна громовая волна. Лучше закла все равно нет",84658,null],[94496,"2026-07-05T18:15:59",9,"/roll 1d20+4 иму щас раздзербанит блежайшего",84658,null],[94500,"2026-07-05T18:16:32",9,"*Просто разодрал хаски.*",94497,null],[94502,"2026-07-05T18:16:38",32,"/roll 2d8",84658,null],[94506,"2026-07-05T18:17:06",32,"//Вот это с учётом прошлого урона уже солиднее",84658,null],[94508,"2026-07-05T18:17:11",9,"*Половина полегла к чертям, большая.*",94503,null],[94509,"2026-07-05T18:17:11",42,"/r 1d20 +6 избиваю кулаком близжайшую псину\n/r 1d20 +6 ударил ногой другую пытаясь раздавить ей череп",84658,null],[94511,"2026-07-05T18:17:28",9,"//Опишите)",84658,null],[94514,"2026-07-05T18:18:05",9,"*Вы слышите шум снаружи, явно всёслышали и щас будут заходить.*",84658,null],[94520,"2026-07-05T18:19:10",42,"— прачемся\n°пытается спрятаться и думаю есть приимущество потому что он извазюкан полностью в грязи°",84658,null],[94521,"2026-07-05T18:19:23",42,".",91947,null],[94523,"2026-07-05T18:19:33",32,"(Я подготовил магию и на нас бежали собаки я сидел глаза закрыты я не дышал я камень.\nНо когда псы подбежали слишком близко я быстро немного дергано произнес формулу но сила была малой. И я в панике повторил ещё раз но сильнее.\nБольшая часть собак лежит с взорваны и ушами и истекает кровью из Носов пастей и ушей настолько сильна магия грома)",84658,null],[94525,"2026-07-05T18:19:52",42,"/r +d20 -1",84658,null],[94527,"2026-07-05T18:20:00",32,"(телепатия. Отступаем тут будут искать)",94520,null],[94528,"2026-07-05T18:20:23",42,"— лады.. \n°уходит°",94527,null],[94530,"2026-07-05T18:20:27",32,"/roll d20+2 \nСкрытность",84658,null],[94532,"2026-07-05T18:20:36",32,"/roll d20+2 \nСкрытность",84658,null],[94535,"2026-07-05T18:21:17",32,"(я правильно сделал что решил отступить ибо не получалось сконцентрироваться руки дрожат от боя и адреналина нихрена не камень)",84658,null],[94539,"2026-07-05T18:23:51",9,"/roll 1d20+2 какая-то вшивая псина слишком живучая и надоедливая",84658,null],[94541,"2026-07-05T18:24:22",9,"*Кусает стену, похоже всё ещё дезориэнтированная.*",94540,null],[94542,"2026-07-05T18:24:49",32,"//(кажется слой грязи на Арминара сработал как броня)\nПогребальный звон в неё",84658,null],[94543,"2026-07-05T18:24:51",9,"//Так, вы убегаете или?",84658,null],[94544,"2026-07-05T18:25:09",9,"*Сгорела шавка.*",94542,null],[94545,"2026-07-05T18:25:19",32,"//забыл что стрелы нет",94544,null],[94546,"2026-07-05T18:25:56",42,"°сбегает с слезами на глазах, что не будет нормальной битвы°",84658,null],[94548,"2026-07-05T18:26:05",32,"Похоронил и драпаеул. По пути за поворотом накладываю на себя псевдожинь",94544,null],[94549,"2026-07-05T18:26:22",32,"/roll d4+4",84658,null],[94551,"2026-07-05T18:26:57",32,"-не ссы ещё все будет. Ещё своих люлей отхватим",94546,null],[94552,"2026-07-05T18:27:45",9,"*Самыми первыми пошли собаки, а потом рыцари? Не похоже. Вы слышите треск молнии, покалывание в воздухе, некто медленно движется по проходу и выжигает электричеством оплавляя стены. Гудение как от трансформатора (сравнение).*",84658,null],[94553,"2026-07-05T18:28:08",9,"*Тяжёлые шаги.*",84658,null],[94554,"2026-07-05T18:28:48",32,"-Отлично что известняк не горит а только становится негашеной известью и загорается сначала впитывая жар а потом отдавая",94552,null],[94556,"2026-07-05T18:29:17",42,"— ДААА БЛЯЯЯ Я ХОООЧУУ С НИМ СРАЗИТЬСЯ!! \n°Ловит ломку из-за того что нету в последнее время достойного противника°",84658,null],[94557,"2026-07-05T18:29:50",32,"-Майло прошу потерпи. \n(Мы похоже проебали кислоту)",94556,null],[94558,"2026-07-05T18:29:59",9,"*В сторону вашего прохода на звук ебенит молния, оглушает почти полностью.*",94556,null],[94559,"2026-07-05T18:30:44",9,"*Благо вы были ща поворотом поэтому вилели только мощную, толстуб вспышку.*",84658,null],[94560,"2026-07-05T18:30:45",32,"//ну я понятно использую только телепатию мне говорить не удобно грязь в пасть попадает",84658,null],[94561,"2026-07-05T18:30:59",9,"//Майло кричал вродь",84658,null],[94564,"2026-07-05T18:31:33",42,"//Да ему грязь в рот как второй завтрак",94561,null],[94566,"2026-07-05T18:31:57",32,"(как всегда телепатией) -майло на этот раз разбей склянку или метни рукой открыв. Но окати пылью",94559,null],[94569,"2026-07-05T18:32:06",9,"*От такого можного удара и разряда часть пешеры в которой вы сидите чуть не осыпалась.*",94559,null],[94579,"2026-07-05T18:33:21",32,"//Ну оно и понятно. Я бы чувство магии применил но ячеек на это нет одна осталась. Да и понятно что если молниями так хуярит то либо свитков прорва либо ячейки и пятого есть и может даже шестого",94569,null],[94580,"2026-07-05T18:33:21",42,"// так я бросаю. Но как кислоту, но бонусы владения имеются",84658,null],[94581,"2026-07-05T18:33:28",9,"//Мне надо пособие для чайников с названием \"Как обьяснить игрокам что им пизда не говоря об этом прямо\"",84658,null],[94587,"2026-07-05T18:33:59",42,"// да да да, с жуком ты меня предупреждал что пизда",94581,null],[94589,"2026-07-05T18:34:14",42,"// ещë с помехой кидать спасы от смерти)",84658,null],[94593,"2026-07-05T18:34:40",9,"//Оно тебя жрало, но в ответку кое кто не давал умереть",94589,null],[94598,"2026-07-05T18:35:16",9,"//И после каждого провала выше 3х было + истощение ^^",84658,null],[94599,"2026-07-05T18:35:23",42,"// или артефаки",94579,null],[94602,"2026-07-05T18:35:56",42,"// ладно, я дальше убегаю за Ами, а куды он я не знаю",84658,null],[94607,"2026-07-05T18:36:32",9,"//Арминар тоже бежит?",84658,null],[94617,"2026-07-05T18:38:49",32,"//хе-хе я это понял ещё когда ты увидели повозку",94581,null],[94619,"2026-07-05T18:39:03",32,"//я пока не могу форс-мажор на работе",84658,null],[94788,"2026-07-05T19:31:53",32,"/я хочу кинуть выступление",84658,null],[94794,"2026-07-05T19:32:20",9,"//Я не понимаю зачем, опиши",84658,null],[94795,"2026-07-05T19:32:30",32,"-Майло можешь иллюзией создать какой-нибудь мотивчик лютни",84658,null],[94798,"2026-07-05T19:33:03",32,"//я сейчас описываю но коротко хочу просто постебатся выбить из равновесия мага",94794,null],[94800,"2026-07-05T19:33:26",32,"-Я напою текст балладу\nДа  во мне проснулся дух барда",94795,null],[94801,"2026-07-05T19:34:01",32,"//ну и самого себя и Майло вдохновить",94798,null],[94802,"2026-07-05T19:35:38",32,"(если Майло подыграет то Я вставлю текст)",84658,null],[94803,"2026-07-05T19:36:19",9,"*Маг или кто там не спешит, похоже он понял что проходы легко обвалить и медленно планомерно вплавляет стены чтобы идти по ним безопасно. Тактика дракона пошла нахуй.*",84658,null],[94805,"2026-07-05T19:36:49",9,"*Звуки электрической дуги, треск и озон.*",84658,null],[94806,"2026-07-05T19:36:49",42,"°подыгрываю °",94795,null],[94808,"2026-07-05T19:37:26",32,"//неа. Это не так но ты поймёшь позже",94803,null],[94809,"2026-07-05T19:37:42",42,"// я хочу отпиздить колдуна",94788,null],[94811,"2026-07-05T19:38:41",32,"(Арминар имитируя голос дракона выразительно читает стих)\nПред собою видишь ты дракона\nНа морде виден интерес \nВстань смертный на колени \nУ на с тобою будет секс\nОхренел тот смертный часом\nИ внятно отказать не смог\nА потому теперь он в позе раком\nМеж драконих ног\nПод брюхом у дракона\nУютно и тепло\nА скоро станет жарко\nИ может хорошо \nНо учесть нам с вами стоит \nДракон то был большой \nА человек обычный\nПарень молодой \nИ не известно сколько б это длилось \nНо паренька спасло одно\nДракониха явилась\nИ дракона увело",94806,null],[94814,"2026-07-05T19:39:24",32,"/есть смысл кидать выступление? Или достаточно обидно?",84658,null],[94817,"2026-07-05T19:40:43",42,"°услышал это Майло упал на землю и начал угарать хватаясь за живот°\n— ААААААА АКХАХАХАХАХАКААА",94811,null],[94818,"2026-07-05T19:40:50",9,"Квархадрон — Забавно... — *Послышался кашляюще похрипывающий голос из за спины.* — Идите отсюда.\n\n*Дракон пришёл на шум.*",94811,null],[94819,"2026-07-05T19:41:24",9,"//Кинь с помехой. Там кое кто кому плевать на оскорбления",94814,null],[94828,"2026-07-05T19:42:58",42,"// может просто бросок за то что над ним угарает какой-то чертила?",94819,null],[94830,"2026-07-05T19:42:59",9,"Квархадрон — Ведёт прямо на другую сторону горы. — *Укащывает один из непримечательных проходов.*",84658,null],[94831,"2026-07-05T19:43:12",32,"/roll 2d20R",84658,null],[94834,"2026-07-05T19:43:25",32,"/roll 2d20",84658,null],[94838,"2026-07-05T19:43:48",9,"*Шаги стали чуть увереннее в вашу сторону, не более.*",94835,null],[94840,"2026-07-05T19:44:02",32,"9 на оскорбление!\n(идём за драконом.)",94830,null],[94843,"2026-07-05T19:44:33",9,"*Дракон не идёт, от посылает вас, похоже сейчас начнётся бой.*",94840,null],[94844,"2026-07-05T19:44:34",32,"//а вдохновение союзникам?",84658,null],[94845,"2026-07-05T19:44:51",9,"//Квархадрона позабавило",94844,null],[94847,"2026-07-05T19:44:59",42,"°Идëт за драконорождëнным°\n— а когда пиздилооо???",84658,null],[94848,"2026-07-05T19:45:00",9,"//.",94818,null],[94850,"2026-07-05T19:45:14",32,"//дай эму +4 временных хита за вдохновляющий лидер",94845,null],[94856,"2026-07-05T19:46:15",32,"-Мы отступаем. Сейчас начнётся пиздилово и мы ударим либо в спину либо будем ждать удачного момента поднасрать по маленьку",94847,null],[94858,"2026-07-05T19:46:38",32,"-Либо умрем мешаясь под лапами и молниями",94856,null],[94860,"2026-07-05T19:47:11",9,"*Арминар как маг прорицатель чувствует что Квархадрону конец однозначно. Но, есть момент, ты держишь будщее в своих руках в своих руках.*\n\n//Напомни пожалуста какие у тебя знамения, ты можешь отдать одно дракону и модет судьба будет милостива)",94850,null],[94861,"2026-07-05T19:47:39",32,"8 и 18.\n8 магу и 18 дракону",84658,null],[94864,"2026-07-05T19:48:13",9,"*На пол пути вы начинаете слышать звуки, всё рушится!*",84658,null],[94867,"2026-07-05T19:48:41",9,"*Тоннель сбоку обвалился, совсем немного времени и вас просто раздавит.*",84658,null],[94869,"2026-07-05T19:49:48",9,"*Иму хоть и не боится ничего но встал на четвереньки и бежит держа мешок со своими сокровищами в зубах.*",84658,null],[94870,"2026-07-05T19:49:53",32,"-у меня есть план! (Крикнул Арминар.) И метнул в дракона зельем лечения. Начав отступать",84658,null],[94871,"2026-07-05T19:50:15",32,"-Лови!",94870,null],[94873,"2026-07-05T19:50:25",42,"°максимально быстро бежит от сюда°",84658,null],[94875,"2026-07-05T19:51:00",9,"*Он поймал зелье, обычно он бы откащался и вряд-ли это помодет, но противник был достаточно силён чтобы поступится принципами и он тут же открыл пробку и выпил уйдя в перёд, драться.*",94870,null],[94886,"2026-07-05T19:52:37",9,"*Вы выбежали с другой стороны. За вами обвалился проход обдав пылью и воздухом. Пгтом ещё где-то, потом ещё. Вершина обсыпалась обдавая вас небольшой лавиной, дождем камней на голову.*",84658,null],[94888,"2026-07-05T19:52:53",9,"/roll 3d4 дробящего",84658,null],[94890,"2026-07-05T19:53:06",9,"//Спас ловкости 12 и тогда половина урона",84658,null],[94891,"2026-07-05T19:53:10",32,"Ладно я отступаю Майло пращу и склянку с известняком унес потому не могу помочь \n-Что-то мне подсказывает что пора бежать но сначала я тебя коснусь (предупреждаю и\nПодбегаю к дракону накладывая скороход и бегом с пещеры)",94875,null],[94892,"2026-07-05T19:53:38",32,"/roll d20+2",94890,null],[94896,"2026-07-05T19:53:50",9,"//Пробафал дракона максимально)",94891,null],[94897,"2026-07-05T19:53:58",32,"У меня как раз 7 временных хитов",94889,null],[94900,"2026-07-05T19:54:06",32,"//как мог",94896,null],[94905,"2026-07-05T19:55:30",9,"*Битва блилась по ощущениям всего-то не больше минуты, потом тишина. Вы с другой стороны горы, и похоже сражение было один на один, ща такое короткое время вряд-ли бы кто-то прибежал на помощь тому кто первый шёл по коридору.*",84658,null],[94906,"2026-07-05T19:55:31",42,"/r 1d20 +1",94890,null],[94908,"2026-07-05T19:55:45",9,"/roll 1d20 иму",84658,null],[94913,"2026-07-05T19:56:29",9,"*Мелкий сидит и трёт ушибленную голову, его задело неплохо. Камнем по голове.*\n\nИму — Грррр, злая гора...",94910,null],[94916,"2026-07-05T19:57:11",9,"*Всё затихло очень быстро. Отсюда не понятно чем закончилось противостояние.*",84658,null],[94919,"2026-07-05T19:57:28",32,"//Ладно есть кто-то ещё из каравана с первым",84658,null],[94921,"2026-07-05T19:57:48",9,"//Вы с другой стороны горы, отсюда не видно",84658,null],[94925,"2026-07-05T19:58:44",42,"— итак.. Что делать? Теперь и с простыми рыцарями не попиздиться\n°ударил кулаком по стене°",94913,null],[94927,"2026-07-05T19:59:05",42,"/r 1d20 +6 на сколько сильно ударил с эмоций по стене",84658,null],[94929,"2026-07-05T19:59:21",32,"-Кажется пора внутрь. Беру в руки набор лекаря (честно не вернутый Майло)\n- идём внутрь. С простыми рыцарями мы и не попиздимся. Потому что попиздят нас",94921,null],[94937,"2026-07-05T20:01:31",42,"// это набор травника если чë. Лекаря нету у меня",94929,null],[94940,"2026-07-05T20:02:00",9,"*Входы засыпало, не пройти не пролезть.*",84658,null],[94942,"2026-07-05T20:02:21",32,"//Ну у меня есть иглы и нити попробую их для завывания использовать",94937,null],[94944,"2026-07-05T20:02:36",32,"(Иду вдоль горы искать вход)",94940,null],[94945,"2026-07-05T20:02:43",9,"*Вы слышите возласы эхом в горах, похоже... рыцари победили, а точнее кажется тот кто зашёл в гору — вернулся с победой.*",84658,null],[94946,"2026-07-05T20:03:04",32,"//но сначала дай опыт за произошедшее",84658,null],[94947,"2026-07-05T20:03:13",9,"//?",84658,null],[94950,"2026-07-05T20:03:47",32,"//нам с Майло до третьих уровней не хватало совсем копейки с песелей набили",94947,null],[94951,"2026-07-05T20:03:59",42,"// это правда",94950,null],[94959,"2026-07-05T20:06:01",9,"//Ну, пусть по 50, просто по некоторым причинам опыт делится ÷3, у вас с собой помощник)",84658,null],[94961,"2026-07-05T20:06:35",32,"//а сколько за одну собаку? Просто что-то вроде 25 а мы их дюжину положили",94959,null],[94963,"2026-07-05T20:07:00",42,"// фи, смысла нету",94959,null],[94965,"2026-07-05T20:07:16",32,"//да так и смысла нет",94963,null],[94977,"2026-07-05T20:09:50",42,"// дайте я убью кого-то, у меня лоооомкааа",84658,null],[94980,"2026-07-05T20:10:35",9,"//Сто делают впши персы, дракон явно проиграл.",84658,null],[94987,"2026-07-05T20:12:06",42,"— да надо их было вместе с тем трупом ходячим их мочить. Теперь нас и в городе не жалуют, не дракон твой покойный\n°ударил по булыжнику с кулака°",84658,null],[94988,"2026-07-05T20:12:23",42,"/r 1d20 +6 на сколько сильно ударил булыжник",84658,null],[94989,"2026-07-05T20:12:24",32,"//да но возможно ещё не сдох",94980,null],[94991,"2026-07-05T20:12:39",9,"//И мне не нравится что наш прорицатель сильно зациклен на классовых абилках)",84658,null],[94992,"2026-07-05T20:13:12",32,"-Ну так нас никто и не видел. Тебя может по голосу узнают а я точно не светился",94987,null],[94995,"2026-07-05T20:13:44",9,"//Ты маг видящий будущее, придумай что-то, у тебя камень в рюкзаке принадлежащий дракону)",84658,null],[94996,"2026-07-05T20:13:51",42,"— не забывай кто с гонцами общался, тебя тоже по голосу узнают",94992,null],[95003,"2026-07-05T20:15:53",32,"//хмм ну раз ты хочешь отвгрыша все механики то ок.",94995,null],[95006,"2026-07-05T20:16:06",42,"// а что я зациклен на грубой силе и драками так же не нравится?",94991,null],[95018,"2026-07-05T20:17:17",32,"//просто ну камень и что это мать его не филактерия и не сосуд души чтобы как-то влиять.\nВ любом случае мне надо добраться до тела дракона и я знаю как туда дойти.",94995,null],[95020,"2026-07-05T20:17:22",9,"//Ну все норм, перс так и залымывался. А у него явно некто кто может что-то мистическое, а он даже не пытается мыслить за пределами классовых навыков и заклинаний",95006,null],[95023,"2026-07-05T20:18:00",32,"//до этого свободомыслие ты немного карал \"а у нас по правилам механически так\"",95020,null],[95029,"2026-07-05T20:18:53",42,"°обходит гору и идëт в сторону рыцарей°\n// бля я устал, хочу пиздело",95018,null],[95030,"2026-07-05T20:18:55",9,"//Ну, смотря что. Что прописанно — так и есть. А что не прописанно но имелось ввиду)",84658,null],[95031,"2026-07-05T20:19:13",9,"*Иму идёт за Майло.*",95029,null],[95032,"2026-07-05T20:19:19",42,"// наш волшебник просто пуси",84658,null],[95037,"2026-07-05T20:19:32",42,"//КУУУЛАААКИИИИ",84658,null],[95039,"2026-07-05T20:19:55",32,"//Ладно. Я иду в пещеру в ближайший ход искать тело дракона у меня есть кое что что может помочь",95030,null],[95046,"2026-07-05T20:21:10",9,"*Майло обходит гору и на растоянии видит как с какого-то парня снимают черные доспехи. Процессия собирается выступать обратно. Ну и его заметили.*",84658,null],[95050,"2026-07-05T20:21:47",32,"/а ведь угадал с возрастом в балладе",95046,null],[95055,"2026-07-05T20:22:13",9,"//Описывай как перс\n\n*Проход завален, и второй, и третий. Похоже все не укреплённые ходы обвалились.*",95039,null],[95057,"2026-07-05T20:23:09",32,"(а Арминар и не идёт к заваленным. Он знает потому что видит будущее какой путь привет его к телу дракона)",95055,null],[95058,"2026-07-05T20:23:25",9,"//Какой путь?",84658,null],[95062,"2026-07-05T20:23:46",9,"//Что ты делаешь)",95057,null],[95063,"2026-07-05T20:23:54",42,"— ЭГЕГЕГЕЙ!! Я не понял?!? Кто будет платить за ремонт моего дома?? \n°Бежит к ним и делает вид словно пьян, для правда подобия он навернул немного алкогольного для запаха°",95046,null],[95064,"2026-07-05T20:23:57",32,"/банально иду за Майло.",95058,null],[95066,"2026-07-05T20:24:15",32,"Потому что маг вышел а значит там можно зайти",95064,null],[95069,"2026-07-05T20:24:49",42,"// я к рыцарям иду, думаю за драконью компанию меня прикончат даже слыха не хотя)",95064,null],[95072,"2026-07-05T20:25:40",32,"(Так я не дракон. А всем известно что драконы и драконорожденные находится в состоянии близком к холодной войне. Как минимум маг точно знает)",95069,null],[95074,"2026-07-05T20:27:04",42,"// да мужскому Рыцарскому  DEUS VULT рассизму поебать должно)",95072,null],[95076,"2026-07-05T20:27:22",42,"// особенно ты уже знаком какие люди здесь живут)",84658,null],[95078,"2026-07-05T20:28:25",32,"//в любом случае это для меня единственный путь ведь иначе мастер требует \"отыграй мага который видит будущее\" а как только ты говоришь \" я знаю какой путь в будущем приведет меня к дракону\" сразу морозится в стиле \"и что ты делаешь. Я не понимаю\"",84658,null],[95080,"2026-07-05T20:28:43",32,"/Так что поебать я тоже хочу крови",84658,null],[95083,"2026-07-05T20:30:13",42,"// сколько хп у Арми?",84658,null],[95085,"2026-07-05T20:30:35",32,"12+4 временных.",95083,null],[95088,"2026-07-05T20:31:20",42,"// норм, я за ход справлюсь. Не обидешься если вырублю случайно?",95085,null],[95090,"2026-07-05T20:31:40",9,"//Мастер... эх, ладно.",84658,null],[95091,"2026-07-05T20:31:52",42,"// моя жажда крови пропитана стратегией и алкоголью",84658,null],[95094,"2026-07-05T20:32:32",32,"//Если не вырубишь ,пиняй на себя. Ведь я тебя и убить ответом могу. Но хорошо что предупредил не обижусь но надеюсь у тебя есть план",95088,null],[95095,"2026-07-05T20:32:49",9,"*Перед Майло встаёт пара крупных мужиков в полулатах, крепкие. У одного их них отсутствует нагрудник и он просто светит идеальным мощным пресом.*",84658,null],[95097,"2026-07-05T20:34:32",9,"*Основной проход не завален, вроде ьы. Но ещё тебя привлекает маг, он в составе выделяется слишком что-то делает с двуручником на котором кровь, драконья кровь.*",95094,null],[95099,"2026-07-05T20:35:06",42,"°движется пьянной походкой°\n— Мужики.. Да вы хороши\n°осматривает шатающей головой пресс воина и ставит большой палец вверх°\n— Почему вы уничтожили мой дом? Мой храм? Что был на вершине горы",95095,null],[95103,"2026-07-05T20:36:39",32,"(Я подхожу к магу и представляюсь.)\nАрминар из крана Керрилон. Принц клана и не глава только потому что не хочу пока.\nПрошу прощения за мой неподобающий вид",95097,null],[95105,"2026-07-05T20:37:20",9,"*Они переглядываются.*\n\nРыцарь — Это гнездище дракона и он сам егообрушил,поди отсюда окаянный.\n\nРыцарь с голым пресом — Да чё прогонять то сразу, может чё интересного скажет. Твой храм говоришь?",84658,null],[95107,"2026-07-05T20:38:09",9,"*К магу не пускают тебя ближе чем на 50 футов. Волшебник явно сейчас занят и не реагирует.*",95103,null],[95108,"2026-07-05T20:38:20",32,"(даже для вида что коллега из внутреннего кармана вытянул книгу заклинаний)",95103,null],[95109,"2026-07-05T20:38:58",42,"— Ик! Да.. Храм.. Мы варили отменное вино и учили нас как голоми руками убивать драконов. Хотите поспорим? 1 на 1 со мной?? Ставлю 10 золотых",95105,null],[95110,"2026-07-05T20:39:09",42,"// если что я притворяюсь пьянным",84658,null],[95111,"2026-07-05T20:39:37",32,"(Хорошо (я достаю камушек. Ты описывал самоцвет как весьма внушительного размера камушек)) и просто сажусь в сторонке ждать",95107,null],[95112,"2026-07-05T20:39:41",9,"*Молодой человек которого распаковали из брони взглянул на Арминара.*\n\nМолодой человек — Не слышал о таком клане. На прошлой неделе с северной границы нападали дракониды. — *Задумчивость в голосе.*",84658,null],[95115,"2026-07-05T20:40:29",32,"-Я аметистовый. С юга. Наш клан в основном лекари и учителя",95112,null],[95117,"2026-07-05T20:41:05",9,"Молодой человек — Хм, ладно. — *Потерял интерес.*",95115,null],[95119,"2026-07-05T20:41:33",32,"-Да несколько магов.\n(Убирает лепкой земли с морды грязь. Снимая маскировку)",84658,null],[95123,"2026-07-05T20:42:51",9,"Волшебник — Я вижу... змей тяжело ранен. — *Волшебник наконец что-то увидел и переда меч лорду, тому молодому парню.* — Он умрёт через день или два, там под завалами, так говорит его судьба.",84658,null],[95127,"2026-07-05T20:45:04",9,"*Рыцари рассмеялись.*\n\nДаниель — Могу попробовать, как раз хотел отдохнуть. Но я пока при исполнении, не положенно. Звать Даниель, коли хочешь приходи в корму местную, отдохну неделько а горах. — *Тот самый чел в броне но с голым торсом.*",95109,null],[95130,"2026-07-05T20:45:48",32,"-Я хотел бы искупаться в крови дракона для получения его сил. Потому займусь раскопками\n(Ни капли лжи)",95123,null],[95134,"2026-07-05T20:47:09",42,"°резко сделал трезвый вид°\n— Даниель, увы. Храм был разрушен из-за землетрясения. Дракон который был с низу не мог так поступить. Я лично ему делаю больно чтоб боялся на наш храм даже смотреть",95127,null],[95135,"2026-07-05T20:47:43",42,"— вот только остался мой вот ручной дракон\n°показывает на Иму°",84658,null],[95137,"2026-07-05T20:48:42",9,"Молодой человек — Пусть драконид делает что хочет, нет времени.",84658,null],[95138,"2026-07-05T20:48:56",32,"-Да отличный был храм... Я оттуда как трезвенник еле сбежал",95134,null],[95139,"2026-07-05T20:49:03",9,"*Лорд перебил возмушение своего мага, ему плевать.*",84658,null],[95141,"2026-07-05T20:50:56",32,"-Майло. Отстань от людей идите сюда. Дракон это целое состояние в золоте. Надо его выкопать",95138,null],[95142,"2026-07-05T20:51:11",9,"*Покрутили бы у головы если могли, смотрят как на дурачка. Ток Даниель рассмеялся.*\n\nДаниель — Ручной говоришь? — *Присел, пытается погладить Иму но тот просто укусил его за перчатку оставив следы.* — Забавный.",95134,null],[95146,"2026-07-05T20:52:49",9,"*Процессия почти собралась выступать обратно.*",84658,null],[95147,"2026-07-05T20:53:04",32,"- уважаемый маг а у вас есть магия на продажу? Переписать из книги в книгу?",95139,null],[95148,"2026-07-05T20:53:31",42,"— Настырный и дерзкий. Уважаю таких. У вас есть здесь какие-то желающие поспаринговаться? Хочешь нет, но со своего храма я слышал о славе силе рыцарей. Поэтому условие мужское и простое, на кулаках",84658,null],[95149,"2026-07-05T20:53:34",32,"Или свитки с заклинаниями",95147,null],[95151,"2026-07-05T20:54:02",32,"//тебе их не жалко?",95148,null],[95152,"2026-07-05T20:54:23",9,"*Волшебник ничего не сказал, просто посмотрел и отвёл взгляд. Похоже он не был в расположении делиться наработками. Такие они, придворные маги.*",95147,null],[95153,"2026-07-05T20:55:04",42,"// нет.. Я должен каждый день драться по нормальному, а то ломку ловит не Майло, а я",95151,null],[95154,"2026-07-05T20:56:07",32,"(ну и хрен с ним. (Убрал камушек на очень большую сумму в сумку)(Кстати какая оценочная на первый взгляд стоимость драгоценного камня? Арминар немного в ювелирке разбирается)",95152,null],[95155,"2026-07-05T20:56:34",9,"*Желание высказал только тот самый Даниэль, и то только какс работой закончит в корчме местной отдыхать будет.*",95148,null],[95156,"2026-07-05T20:56:50",9,"//Минимум 250 золотых",95154,null],[95157,"2026-07-05T20:57:39",9,"*Камень выглядит необработанным но напоминает глаз дракона из красного рубина.*",95154,null],[95158,"2026-07-05T20:58:10",42,"— Эх.. Ладно, опять камни и руды разбивать кулаками.. \n°Жалобно сказал Майло и уходит в сторону свалки°",95155,null],[95164,"2026-07-05T21:02:38",9,"*Даниель положил руку в латной рукавице на плечо.*\n\nДаниель — Виду ты парень боевой. Не хочешь к нам? Сначала оруженосцем а там и рыцарем не далеко. Не дерёмся мы разве что в пути)",95158,null],[95166,"2026-07-05T21:05:24",9,"//Ладно, чем вы занимаетесь",84658,null],[95167,"2026-07-05T21:06:51",42,"— звучит очень сладко. Словно мëд. Вот жаль что я не пчела. Монастыря нет больше из-за моей слабости. Я подумаю, в корчме увидимся. На трезвую голову думается тяжко\n°приподнял руку для рукопожатия°\n— и только посмей слабо пожать руку, видно что ты тоже не капли не уступаешь моей боевитости)",95164,null],[95168,"2026-07-05T21:07:26",9,"/roll 1d20+9 атлетика на стльное рукопожатие",95167,null],[95171,"2026-07-05T21:08:40",9,"Даниэль — Обязательно поспарингуемся. — *Этот рыцарь явно любит посражаться и покрасоваться, судя по тому что он ещё и с голым торсом ходит при этом остальное в броне.*",95167,null],[95172,"2026-07-05T21:09:16",42,"/r 1d20 +6",95168,null],[95174,"2026-07-05T21:09:29",9,"*Рыцари уже собираются, садятся по коням.*",84658,null],[95176,"2026-07-05T21:10:19",9,"*Никто никому не уступает.*",95173,null],[95178,"2026-07-05T21:11:51",9,"Даниель — Хорош рогатый, точно помахаемся. — *Довольный потом он садится на коня и взмахнув в след уезжает за процессией.*",84658,null],[95179,"2026-07-05T21:11:55",42,"— Прощай. Жди в карчме",84658,null],[95182,"2026-07-05T21:12:33",9,"*Видно как медленно процессия движется всё дальше.*",84658,null],[95184,"2026-07-05T21:13:32",42,"// я там пропаду. 3%",84658,null],[95187,"2026-07-05T21:15:02",32,"(Арминар идёт в туннель на этот раз просто по единственному пути из оплавленных молнией стен) и начинает раскапывать лепкой земли туннель где возможно. А дальше только кобольда и тифлинга припрягать если сам не смогу)",84658,null],[95188,"2026-07-05T21:15:30",32,"(провёл короткий отдых для восстановления ячейки магии)",84658,null],[95189,"2026-07-05T21:17:14",32,"//в общем опиши что видно по пути",84658,null],[95190,"2026-07-05T21:17:29",9,"*Тоннель опалённый — цел, остальное обваленно, не понятно куда и в какую сторону копать, где Квархадрон или его остатки.*",84658,null],[95191,"2026-07-05T21:18:30",32,"/я могу использовать ритуал чувство магии и поискать некротику? от полу мертвого дракона смертью должно пованивать изрядно.\nЕсли не позволишь конечно опереться на интуицию",95190,null],[95192,"2026-07-05T21:20:12",9,"*Такой красивый камень в сумке, похожий на глаз дракона и принадлежал ему, хм.*",84658,null],[95193,"2026-07-05T21:22:06",32,"(я понял что это похоже глаз выбитый или что-то похожее) мм в любом случае я использую чувство магии и если камень необычный а например спиритический фокус для прорицателя я пойму хотя бы по заряду.)",95192,null],[95194,"2026-07-05T21:27:32",9,"*Камень как камень, дракоценность. Кажется в нём есть крохотный след магии воплощения, даже понятна стихия — огонь. Поэтому он и сверкал как настоящий глаз в темноте тогда.*",84658,null],[95195,"2026-07-05T21:29:07",9,"*Ты нашёл немного крови, но след исчезает под завалами. Похоже это место битвы, видно на стенах следы магии и огня, на ней ветви словно облизала молния.*",84658,null],[95196,"2026-07-05T21:31:19",32,"-Тут и будем копать. \n(Сказал себе Арминар четко понимая что у него (или их если вместе с тифлингом и кобольдом) только сутки на работу. )\nЛепка земли землю перемещать и на ней камни чтобы их выплавлять в опоры. Разгрести самый верх и утрамбовать. А потом поставить импровизированные опоры. И по новой",95195,null],[95198,"2026-07-05T21:32:02",32,"???",95197,null],[95199,"2026-07-05T21:33:14",32,"//хард можно я проницательность кину? На озарение?",95192,null],[95200,"2026-07-05T21:34:15",9,"*Следы крови ищезли через некоторое время сколько не копайся вглубь, похоже раны просто перестали кровоточить.*",95196,null],[95201,"2026-07-05T21:34:54",32,"Я обваляю камень в драконей крови. Просто по приколу",95200,null],[95202,"2026-07-05T21:35:19",9,"*Теперь камень немного в земле и крови.*",95201,null],[95203,"2026-07-05T21:35:36",32,"Ну и ок. Теперь он лучше",95202,null],[95204,"2026-07-05T21:35:38",9,"//Лки, илистория или магия или просто инта",95199,null],[95205,"2026-07-05T21:35:59",32,"/roll d20+5 \nАркана",95204,null],[95207,"2026-07-05T21:38:04",9,"*Если предмет имеет связь с владельцем то в теории можно смастерить маятник который укажет направление к владельцу. Правда интерпретация вращений чаще неточна но... повторение и еще раз повторение, магия прорицания не славится своей точностью, кроме разве что знамений.*",84658,null],[95208,"2026-07-05T21:39:17",9,"//Вы недооцениваете сам концепт мага прорицателя, по крайней мере я так вижу. И у меня на играх так можно",84658,null],[95209,"2026-07-05T21:40:18",32,"//конкретно маятника я не знал. А мог кинуть кости. Я просто не знал как это отыгрывать. Спасибо за совет",95208,null],[95210,"2026-07-05T21:41:03",9,"//Да там 1000 способов, ебашь тот что тебе прикольнее)",84658,null],[95211,"2026-07-05T21:42:01",32,"//Ну значит я не зря в крови его извалял. Надёжность повыситься.\nСвязать(обвязать глаз на узел \"корзинка\" из шелковых нитей и начал гадать.)",95207,null],[95212,"2026-07-05T21:43:06",32,"У меня и карты есть и кости. И можно на дымку гадать. В общем я понял спасибо за совет",95210,null],[95213,"2026-07-05T21:44:07",9,"*Камень едва заметно подрагивает, пришлось сосредоточенно концентрироваться несколько минут прежде чем он повернулся в предположительно нужное направление стороной которая напоминала зрачок.*",95211,null],[95214,"2026-07-05T21:45:15",32,"Разложил карты в гадании по типу таро. И кинул кости, помолился Тиамат (просто по приколу ибо то же должно как вера работать) и начал копать",84658,null],[95215,"2026-07-05T21:45:35",9,"//Ну, я думаю способы разные для разных нужд",95212,null],[95216,"2026-07-05T21:45:47",9,"//Опиши что спросил у карт",95214,null],[95217,"2026-07-05T21:45:51",32,"//да перегибаю",95215,null],[95218,"2026-07-05T21:49:09",32,"Тасуя карты я задаю вопрос. \nПусть карты поведают мне. \nВыживу я после того как дракон переродиться как феникс",95216,null],[95219,"2026-07-05T21:50:08",32,"Да ничего лучше чем (если я зашью раны дракона он меня не убьет. В голову не пришло)",95218,null],[95220,"2026-07-05T21:52:25",9,"*Три карты, смерть (похоже не твоя), потом Суд (возвращение) и после десятка мечей (гибель, возможно о тебе).*",84658,null],[95221,"2026-07-05T21:53:54",32,"-Ну гадание имеет свойство ошибаться.\n(С весёлым суицидальным настроением в голос рассудил Арминар) -Не попробуем не узнаем",95220,null],[95222,"2026-07-05T21:54:18",32,"//сейчас ещё молитву зачитаю",84658,null],[95227,"2026-07-05T22:05:13",32,"- ех не знаю, поможет ли но.\n(Падает на колени сгибая спину в позе максимальной покорности сжимая в пасти кошель с остатками своего золота.) В мыслях обращаясь скорее к самому Квархадрону но используя ритуалы для обращения к Тиамат.\n- владыка небес и пламени! могущество драконов не знает себе равных,\nгордость и дух непоколебим.\nЛишь вечные не знают поражения от смерти.\n(Тут немного запнулся и просто полоснул по ладони когтями)\nПрими в дар мою силу.\n(Стараюсь входить в посыл и магию)",84658,null],[95228,"2026-07-05T22:05:28",32,"//надеюсь из этого что-нибудь получится",84658,null],[95229,"2026-07-05T22:06:19",9,"*После ритуала ты чувствуешь себя увереннее, стало чутка спокойнее на душе.*\n\n//Надеюсь",95227,null],[95230,"2026-07-05T22:06:45",32,"//хе-хе. Ну будем надеяться что помогло",95229,null],[95231,"2026-07-05T22:07:17",32,"Копаем в направлении куда показал глаз",95229,null],[95232,"2026-07-05T22:08:02",32,"Так как я ячейку восстановленную в это дело вложил а куда там магия пошла одному Акселетору известно",95230,null],[95233,"2026-07-05T22:09:48",32,"//хотя десятину не приняло золото осталось но и ладно",95229,null],[95234,"2026-07-05T22:10:26",42,"// чтож я тут",84658,null],[95235,"2026-07-05T22:10:29",42,"// но с 2%",84658,null],[95236,"2026-07-05T22:10:55",42,"// благополучно проебал зарядку",84658,null],[95238,"2026-07-05T22:11:10",32,"//держись!",95236,null],[95242,"2026-07-05T22:14:25",9,"*Толща земли и камня очень плохо поддавалась, приходилось рыть под углом чтобы не осыпалось, а другие места лепка земли не могла взять. Работы заняли целый день, вы устали и надо отдохнуть, но ощущение что осталось совсем немного.*",84658,null],[95244,"2026-07-05T22:16:08",32,"(Арминар из набора травника готовит нам бодрящий отвар и мы продолжаем)",95242,null],[95251,"2026-07-05T22:21:12",9,"*В один момент вы наткнулись на стенку, чем то напоминает те места где дракон делал необваливаемые тоннели.*",84658,null],[95253,"2026-07-05T22:22:39",32,"/roll d20+3 \nЧистый интелект. Арминар вспоминает объёмную карту путей по поворотам которую проходил",95251,null],[95255,"2026-07-05T22:23:40",32,"(прикидываю куда копать)",84658,null],[95256,"2026-07-05T22:23:42",9,"*Кажется можно обкопать вдоль по твёрдой поверхности и потом попасть в тоннель.*",84658,null],[95257,"2026-07-05T22:25:26",32,"(А если просто проломать? Какой шанс на обрушения. \n-Если тут сломать шанс на то что все рухнет?\n(Кидает 3 д6)",95256,null],[95258,"2026-07-05T22:26:03",9,"*Шанс что всё рухнет всегда есть, безопаснее обкопать.*",84658,null],[95259,"2026-07-05T22:28:20",32,"(Тяжелый вздох и продолжение изнурительной работы.)\n(Арминар капитально заебался. Руки уже дрожат от многих часов работы. Но останавливаться на отдых не позволяет честь.)",95258,null],[95261,"2026-07-05T22:29:35",9,"*Это щаняло ещё около часа, снаружи точно глубокая ночь, а может скоро утро? Очередной слой а за ним пустота. Там темно, очень.*",84658,null],[95265,"2026-07-05T22:30:45",32,"Ну у нас горят факела ибо и в том туннеле было не менее темно",95261,null],[95274,"2026-07-05T22:33:28",9,"*Посреди пещеры лежит Квархадрон, слышен едва заметный звук дыхания. Его плоть опалённая чёрными ветвистыми рисунками молний, прожжённая, запёкшийся. Лежит на левой стороне, тело прикрыто крылом, сейчас не сказать что с туловищем, шеей или головой. Второе крыло напоминает порванную тряпку на сломанных костях и перепонках. Никак не среагировал на шум или ваше появление, кажется он спит или в отключке.*",84658,null],[95279,"2026-07-05T22:34:09",9,"*Но даже так выглядит пиздец хреново, его просто односторонне отпиздили.*",84658,null],[95295,"2026-07-05T22:36:05",32,"Иду к дракону. \n-Ей здоровяк ты жив? (Использую телепатию чтобы позвать если спит ответит если в отключке то сразу осматривать буду)",95274,null],[95299,"2026-07-05T22:37:09",9,"*Ты видишь его волю, сон или меланхолию, слишкомс настолько что выидишь сцену.*",95295,null],[95303,"2026-07-05T22:38:26",9,"??? — Квархадрон... ты всё ещё помнишь стук молота... на другой стороне времени, миров. — *Слышен тяжёлый голос.*",84658,null],[95307,"2026-07-05T22:40:16",9,"*Сцена рещко обрывается. И из под крыла вытыкается его лицо. Выжженное ещё сильнее, он уже слабо видит и вторым глазом, тот опалён сильно, но вроде шевелится. Чувствует направление чужого присутствия как-то по другому, но не отвечает.*",84658,null],[95308,"2026-07-05T22:40:33",9,"//Он может отвечать в ответ если ты с ним телепатией?",84658,null],[95310,"2026-07-05T22:41:05",32,"-я подойду. Я хочу помочь.\n(Передаю искренне желание помочь и ощущение эмоции от объятия)",95307,null],[95311,"2026-07-05T22:41:23",9,"Квархадрон — Кто ты... пришёл сразится со мной? — *Он не понимает кто перед ним.*",84658,null],[95312,"2026-07-05T22:42:50",32,"-я Арминар. (Передаю свою внешность в зеркале как картинкау. Образ объемный композитный Обмазаный грязью драконид который говорит с самим драконом)",95311,null],[95314,"2026-07-05T22:45:35",9,"Квархадрон все ещё в ответ на телепатию — Это ты... уходи... раны скоро заживут... — *Он выглядит очень упёртым, но даже так видно что помрёт он без помощи, но воля и вера в собственное бессмертие настолько сильна что скорей всего он не совсем умрёт...*",95312,null],[95315,"2026-07-05T22:47:01",32,"- я не могу уйти. Если я уйду ты больше не сможешь летать! (Да приплетаю сюда эмоции и образ волитвы, и эмоции о \"владыке небес\")",95314,null],[95316,"2026-07-05T22:48:08",32,"-Я хочу подойти. Можно?\n(С робкой надеждой вопрошаю)",95314,null],[95319,"2026-07-05T22:48:26",9,"*Только упёртое намеренье в ответ... он... не... примет... помощь... правда способен ли он сопротивляться в этом состоянии — другой вопрос.*",84658,null],[95321,"2026-07-05T22:50:41",32,"-Я не собираюсь тебе помогать. (Подхожу к дракону он Арминара достал)\nНе хочешь жить, не хочешь летать? Не хочешь ходить!? Ну пожалуйста. Хочешь подохнуть от голода в этой пещере!!? Да раны то может и заживут но ты после этого от истощения уже не встанешь.",84658,null],[95322,"2026-07-05T22:51:35",9,"//Телипатия?",95321,null],[95325,"2026-07-05T22:52:05",32,"Скорее и крик души и в голос и телепатия с всеми оттенками того что помочь то собирается и будет и просто даёт возможность зацепится за то что не будет дракону",95322,null],[95336,"2026-07-05T22:54:22",9,"Квархадрон — нет... я не умру... никогда... — *Он уверен, уверен настолько что проэцирует эмоции, он должен был умереть десятки раз, но всегда выживал, сам... ему плевать будет ли он летать или нет, останутся ли конечности на месте, будет ли биться его сердце или нет, он... не... умрёт...*",84658,null],[95338,"2026-07-05T22:55:30",32,"-Если ты встанешь как нежить ты именно что умрёшь. Как минимум технически.\n(Академичным тоном вставил Арминар)",95336,null],[95344,"2026-07-05T22:58:27",9,"*Этот факт он не то чтобы его смутил, ноль реакции.*",95338,null],[95345,"2026-07-05T22:58:49",32,"(я подхожу к целой глазнице) \nИ пробую ещё раз.\n-Может хотя бы задумаешься о жизни?\nСуть в том что если бы не моя магия ты бы УЖЕ был мёртв (вбиваю в разум дракона понимание прорицания и что такое знамения и что без них он бы уже даже как нежить не встал)",84658,null],[95346,"2026-07-05T22:59:47",32,"(да буквально все скопом ощущение от магии и как ощущается предзнаменование что именно я отвел магией его от гарантированной гибели)",84658,null],[95347,"2026-07-05T23:01:06",9,"*Слышно чуть сбывчивое дыхание, кажется он пытался смеяться.*\n\nКвархадрон все ещё мысленно — Я не просил о помощи, ты сам выбрал эту судьбу. Ты ею доволен? Скажи... — *Он будто ведёт беселу в уме, как тогда, игнорируя раны и боль.*",84658,null],[95348,"2026-07-05T23:01:38",32,"-Если бы не скороход, если бы не зелье лечения, если бы не магия судеб ты был бы мёртв. Стопроцентно.",84658,null],[95349,"2026-07-05T23:02:25",32,"- я не доволен результатом по одной простой причине. Я ещё не спас тебя до конца",95347,null],[95351,"2026-07-05T23:04:32",32,"(Арминар действительно был растроен.\nПередаю все те образы когда познакомились понимания что его слова \"говорю со скуки\" явно были не из-за скуки, что он не напал хотя я у него в логове хозяйничал, что уже принял помощь в виде зелья лечения и просто прошу.\n-Доверься мне я не сделаю плохо, я не причиню вреда.",84658,null],[95353,"2026-07-05T23:07:42",32,"-Твоя и моя судьбы уже переплетены. Ещё с момента когда ты пустил меня в логово. Ещё когда мы сражались с тобой плечом к плечу, ещё когда ты нас выгнал зная что мы можем погибнуть... Ты буквально пожертвовал собой чтобы нас спасти.\n(Да Арминар и в своём восприятии крутит факты как может, но эмоции чистые)",95347,null],[95354,"2026-07-05T23:19:58",9,"*Дракон что-то для себя решил, и просто положил голову на землю. Безразличие. Целое крыло убрал это открыло его раны, от мягкой части шеи остались лишь ошмётки, не понятно как он ещё умудряется дышать, но дело в тем что это был один удар, чистый. От шеи до задней ноги, споровший живот, грудь, сломавший кости и рёбра. Через щель от двуручника можно увидеть... даже услышать как бьётся сердце, слабо, но всё ещё упрямо бьётся. И это помимо того что он весь в синяках что раскинулись словно ветви от молний и спёкшийся крови. Его тело пытается регенерировать из последних сил нг не может, просто не изчего и это не оьычные раны от вил или когтей.*\n\n*Этот жест выглядел скорее как \"раз уже вмешался, делай что хочешь\". Похоже Квархадрон снова погрузился в себя, меланхолично прокручивая в голове старые воспоминания.*",84658,null],[95355,"2026-07-05T23:21:45",32,"-Ох бля! Ладно. Будем лечить как можем.\n(Тут мне понадобятся оба моих товарища для \"принеси подай\")",84658,null],[95356,"2026-07-05T23:22:42",9,"//Кинь с преимуществом что нить от инты или мудрости",84658,null],[95357,"2026-07-05T23:23:19",9,"//Хотя нах, узнаешь после попыток помочь просто",84658,null],[95358,"2026-07-05T23:23:26",32,"/roll 2d20H+5\nАркана",95354,null],[95360,"2026-07-05T23:23:52",32,"//хе-хе. Мозги после безсоницы не грузятся",84658,null],[95361,"2026-07-05T23:24:15",9,"*Раны по большей части несут в себе магический урон.*\n\n//Ну, чтобы бросок не в пустоту",95359,null],[95362,"2026-07-05T23:24:21",32,"И так понятно что рана нанесена чем то проклятым",95357,null],[95363,"2026-07-05T23:25:22",32,"Обычная регенерация на раны не работает?",84658,null],[95364,"2026-07-05T23:25:33",32,"Или это именно ослабляет реген",84658,null],[95365,"2026-07-05T23:26:40",32,"Ладно. Начну с того что могу сейчас. Под чешую мазь от ожогов в места попадания молний",84658,null],[95366,"2026-07-05T23:26:48",9,"*Это не вылечить, можно лишь оттягивать неизбежное. Насколько долго? Неизвестно. На проклятие не похоже, это не некромантия, а чистый урон магией и очень мощный. И так ослабленное тело множеством лет жизни с тяжелейшими ранами просто слабо.*",84658,null],[95367,"2026-07-05T23:29:07",9,"// Короче, если ты будешь пытаться его лечить это буквально как быть сиделкой для инвалида присмерти с надеждой на чудо со временем или сильную магию типа регенерации",84658,null],[95368,"2026-07-05T23:29:38",32,"//выходим.",95367,null],[95369,"2026-07-05T23:30:55",32,"Есть несколько идей.\nНачну с банального. Рану надо аккуратно обрезать(зарубцевавшиеся края и зашить. Как и кучу других ран. А потом ищем дичь)",95367,null],[95370,"2026-07-05T23:31:22",32,"(а в процессе можно и кровушки драконей хлебнуть)",84658,null],[95371,"2026-07-05T23:31:52",32,"Сначала начну со старого и по ходу дела к свежим",95369,null],[95372,"2026-07-05T23:32:15",9,"*После комплексного лечения побыстрому кажется его дыхание стало спокойнее, сердце стучит тише и ровнее. Но вы не хирурги чтобы сделать все идеально.*",84658,null],[95373,"2026-07-05T23:32:29",9,"//Ты хочешь попробовать выпить его кровь?",84658,null],[95374,"2026-07-05T23:32:48",32,"//у Арминара обучение в клане включало углублённый курс медицины",95372,null],[95375,"2026-07-05T23:33:07",32,"//да в процессе что выступит то и выпью",95373,null],[95376,"2026-07-05T23:33:32",9,"//Лан, сделаю скидку",84658,null],[95377,"2026-07-05T23:33:39",32,"//я же говорил в клане преимущественно лекари и учителя",95374,null],[95378,"2026-07-05T23:35:34",9,"*Самое трудное было шеей нужно было убрать лишнее, оставить так чтобы не мешало дышать и в то же время остатки глотки не прекрывались ничем. Ниток быс а ещё лучше кожи или чего-то такого чтобы зампнить ею недостающее, а то выглядит невероятно плохо.*",84658,null],[95379,"2026-07-05T23:37:07",32,"Обрезки разобранного крыла",95378,null],[95380,"2026-07-05T23:39:00",9,"*Дракон лежит и никак не реагирует, по крайней мере с вашей стороны та часть его головы что больше напоминает череп с пустой глазницей, в ней он кстати и носил ранее тот драгоценный камень что внешне был немного похож на его второй глаз.*",84658,null],[95381,"2026-07-05T23:42:00",32,"(Ну камень я отдавать не намерен. Я его обработаю и продам жрецу)",84658,null],[95382,"2026-07-05T23:43:00",32,"//ладно что там даст кровь и начисли ещё хотя бы 50 опыта за переговоры чтобы я уровень повысил и я спать. Мне завтра вставать рано",84658,null],[95383,"2026-07-05T23:45:11",9,"//Ладно, 100 опыта тебе. Майло тоже будет отдельная сцена. А кровь? Очень металлическая на вкус и жжётся обжигая изнутри. Кажится надо нечто большее чем выпить кровь или по классике искупаться в ванне из крови дракона от рогов до кончика хвоста.",84658,null],[95384,"2026-07-05T23:46:17",32,"//понятно тогда кровь потом",95383,null],[95385,"2026-07-06T00:02:42",9,"//Я надеюсь норм игра идёт, а так споки",84658,null],[95386,"2026-07-06T00:11:08",32,"//лично мне нравится.\nА Майло? Он вроде не жаловался.",95385,null],[95412,"2026-07-06T07:41:09",42,"// я тута",84658,null],[95413,"2026-07-06T07:41:27",42,"// как там личная арка Арми прошла?",84658,null],[95414,"2026-07-06T07:41:33",32,"//привет!",84658,null],[95415,"2026-07-06T07:42:10",42,"// Майло чутка жалуется на ломку, а так вот. Будет спаринговаться в корчме",95386,null],[95416,"2026-07-06T07:42:30",32,"//я дал понять беспомощному драконучто убить меня проще чем отказаться от моей помощи",84658,null],[95417,"2026-07-06T07:42:51",32,"//то есть и то и то в его состоянии невозможно",95416,null],[95420,"2026-07-06T07:52:11",9,"//Квархадрона мучают до последнего. Хотя он сам упёртая скатина. Пардон — огромная ящерица. Я ещё что спросить хотел. У дракона мыслеобразы прошлого настолько сильны что когда он закатывается в меланхолию то их видно через телепатию хотя она нихуя для этого не прелназначенна, Арминар пробует ещё подсмотреть что-то?)",84658,null],[95421,"2026-07-06T07:54:00",32,"//пока работает с исцелением то постоянно на связи. А под утро заснёт ближе к обеду пойдет на охоту",95420,null],[95422,"2026-07-06T07:54:21",9,"//Лумаб тогда мог уловитт ещё пару сцен",84658,null],[95423,"2026-07-06T08:04:15",9,"*Квархадрон — скорей всего не настоящее имя дракона, это имя какого-то дварфа которым он пользуется, в воспоминаниях промелькнуло несколько упоминаний как он сам называл кого-то этим именем.*\n\n*Ты мог видеть момент из прошлого, тёмный лорд, эти же доспехи сразил его одним ударом в горах, хотя дракон сбежал и выжил — вряд-ли это тот самый молодой парень которого вы видели, он человек а в воспоминаниях — его предшественник.*\n\n*Ты видишь ещё, что дракон не нападал на селение. Он прилетел спиздить бочек пить из них воду чтобы горло не пересохло, ему было плевать на дань, но ретивые люди вместо испуга — напали и он поджог те несколько домов.*\n\n*Сам дракон по какой-то причине имел очень много воспоминаний о кузне под землёй. Обрывками памяти но ясно что проводил там очень много времени. Может поэтому не такой дикий или агрессивный как большая часть драконов.*\n\n...\n\n??? — ... Квархадрон, я всё ещё помню звук молотов. Это было так давно, на другой стороне веков ... — *И чей-то голос, постоянно твердил, повторял будо сцена под заездженную пластинку. Обрывок памяти, сцена неуловимая но будто очень дорогая, настолько что приходится её постоянно вспоминать чтобы не забыть. На фоне звуки молотов и работы, в огромной кузне дварфов, их почти слышно...*",84658,null],[95425,"2026-07-06T08:06:05",32,"//жесть. Значит моя интуиция и тут не подвела",95423,null],[95426,"2026-07-06T08:07:05",42,"// я после 9 утра смогу. На работе буду как раз",84658,null],[95427,"2026-07-06T08:07:08",32,"Ладно \nПосле сна Арминар двинется на охоту подстрелить кого мистическим зарядом",84658,null],[95428,"2026-07-06T08:07:47",32,"//Дракона надо подкормить.",84658,null],[95429,"2026-07-06T08:08:15",32,"//да и у меня рационов не много осталось да и надоело солонину жрать",95428,null],[95430,"2026-07-06T08:08:53",9,"*В горах полно живности. Найти змею или зайца не заняло бы много времени. С дичью побольше будут проблемы, её бы найти и выследить для начала. Местных пока не видно.*",84658,null],[95431,"2026-07-06T08:09:33",32,"/roll d20+3\nПрирода, выслеживание",95430,null],[95433,"2026-07-06T08:10:54",32,"//кстати знамения с утра новые",84658,null],[95434,"2026-07-06T08:11:05",32,"/roll 2d20",84658,null],[95436,"2026-07-06T08:12:39",9,"*На одном из уступов ты заметил горных баранов, целое их стадо, ягнёнки, козы, пару баранов. Было бы опасно, может быть но сейчас они стояли почти под прямым углом, лизали скалу. Похоже камни в том месте солёные.*\n\n— Бааааа, — *Какой то козёл издал соответствубщий звук.*",84658,null],[95438,"2026-07-06T08:14:46",32,"Создаю ледяной кинжал и мечтаю в одного из баранов",95436,null],[95439,"2026-07-06T08:16:32",32,"/кидать на попадание?",84658,null],[95440,"2026-07-06T08:16:55",9,"//Кидай, с преимуществои если не шумел",84658,null],[95441,"2026-07-06T08:17:26",32,"/roll 2d20H+5",84658,null],[95443,"2026-07-06T08:17:37",9,"//Урон",84658,null],[95444,"2026-07-06T08:17:55",32,"/roll d10+2d6",84658,null],[95446,"2026-07-06T08:18:23",32,"/кажется под мороженая баранина",84658,null],[95447,"2026-07-06T08:18:44",9,"//Это что там за урон у кинджала, надо будет закл присмореть и себе",84658,null],[95448,"2026-07-06T08:19:03",32,"/кстати холодом (2д6) могло и соседей задеть это 5 футов аое",84658,null],[95449,"2026-07-06T08:19:46",32,"//десять колющего и 2 д6 холодом аое с Спасом ловкости на 5 футов",95447,null],[95450,"2026-07-06T08:21:00",9,"*Блеяние, и на удивление быстро стадо помчалось со скалы. Баран же цпал камнем вниз застыв как стоял с высунутым языком.*",84658,null],[95451,"2026-07-06T08:21:31",9,"/roll 1d20+2 коза ловкость",84658,null],[95453,"2026-07-06T08:22:24",9,"*Рядом был ещё ягнёнок, он умер сразу, а попытка увернутся у козы кончилась тем что та тоже свалилась.*",84658,null],[95454,"2026-07-06T08:23:10",9,"//Хорошо быть магом, воин без дальнобойного мог бы нае — упасть",84658,null],[95455,"2026-07-06T08:23:46",32,"-Бля я все не унесу!\n(Прохрипел страдальчески Арминар. И пошёл разделывать туши когтями снова обещая купит себе кинжал или лучше нож)",95453,null],[95456,"2026-07-06T08:24:42",32,"/снимет шкуры и из одной из них сделает волокушу чтобы двинулся с вырезкой обратно в логово",84658,null],[95457,"2026-07-06T08:25:50",32,"(да даже потрошить не будет снимет шкуру козы и просто спинку бока и ножки обрежет загрузится и двинет назад)",84658,null],[95458,"2026-07-06T08:27:00",32,"Надо будет ещё дров на растопку взять чтобы отвары/бульены варить. \nИ поискать по пути целебных трав, кореньев кор растений и прочего",84658,null],[95459,"2026-07-06T08:28:30",9,"*Под одной из скал растёт чёт красное, хотя обычно под такими скалами хрен что растёт.*",84658,null],[95460,"2026-07-06T08:28:58",32,"Подходит и пытается рассмотреть и опознать",95459,null],[95461,"2026-07-06T08:29:30",32,"/roll d20+3\nПрирода",84658,null],[95463,"2026-07-06T08:31:09",32,"//ледяной кинжал одно из лучших заклинаний первого круга. На него кстати несмотря на АоЕ урон действует снайпер заклинаний из-за того что это бросок атаки сначала",84658,null],[95464,"2026-07-06T08:31:26",9,"*\"Красный подскалим\" чем-то может обезболить но в то же время вызывает привыкание. Нормальные целители стараются не пользоваться, но в народной медецине часто его добавляют в обезболивающие мази или даже варят отвары.*",84658,null],[95465,"2026-07-06T08:32:38",32,"(Арминар забирает и точно сделает мазь. Но использовать только если дракону не станет хуже не будет.\nНо в работе всегда пригодится)",95464,null],[95466,"2026-07-06T08:36:14",32,"Арминар вернулся в логово у входа варит жидковатый бульон и надеется на помощь Иму или Майло ибо сам он это в драконью топку не зальет",84658,null],[95467,"2026-07-06T08:37:03",32,"Да прийдется несколько (возможно десяток) залов варки делать котелок маленький.",84658,null],[95468,"2026-07-06T08:37:40",32,"Или идти в деревню или кормить сырым хотя организм на последнем дыхании тут вопрос можно ли",84658,null],[95469,"2026-07-06T08:37:45",9,"*Так то не составит труда, огромная дыра в шее сойдёт, правда предупретить дракона заранее, чтобы не захлебнулся.*",84658,null],[95470,"2026-07-06T08:38:04",32,"//я же её зашивал? На это даже кусок разобранного крыла пошёл",95469,null],[95471,"2026-07-06T08:38:44",9,"//Ммм. Тогда ему будет есть нечем, точно зашил всё?",95470,null],[95472,"2026-07-06T08:39:30",9,"//У него пасть не открывается, напомню, он похоже и сам как-то так и ел, или пытался есть до этого",84658,null],[95473,"2026-07-06T08:39:40",32,"/А что у него с пастью? Если был какая-то важная причина то не все",95471,null],[95474,"2026-07-06T08:40:06",9,"//Щас попробую нарисовать, найти бы арт норм",84658,null],[95475,"2026-07-06T08:40:30",32,"//я этого не знал ну да и сколько там этих обрезков с крыла было",95472,null],[95482,"2026-07-06T08:50:09",9,"//Красное крыло — ему писец\nЩелёное — это решето на шее\nЖёлтое — рана через всё тело словно ровно рассекли клинком\nЧёрное — нах всё выжжено до кости от чего наверное и пасть не открывается\n\nА ещё на остальном теле живого места нет, весь в синих полосах как ветви от молний. Куча мелких царапин ран и сдёртой чешуи, больша часть последнего не свежее. + - так, более похожего арта не нашёл",84658,null],[95483,"2026-07-06T08:52:25",9,"*Самым целым выглядит хвост, только немного подёртый когда-то.*",84658,null],[95484,"2026-07-06T08:53:13",32,"Ладно кажется я погорячился что списал только один моток шелковой нити на швы. Тут видимо два надо",95483,null],[95485,"2026-07-06T08:53:49",9,"//Сорри, самое блищкое что смог изобразить",84658,null],[95486,"2026-07-06T08:54:21",32,"/ну ты мои эскизы обороны видел. Так что никаких претензий",95485,null],[95487,"2026-07-06T08:54:29",9,"//Ну и рана от меч скорее с левой стороны, проипался",84658,null],[95505,"2026-07-06T09:14:34",9,"//Короче, описывай, пытайся общаттся может что-то выудишь. Как ты понял дракон не может сейчас отвечать своим утробным голосом потому что у него нет сил, раньше ему приходилось напрягать всё тело чтобы это было возможным.",84658,null],[95515,"2026-07-06T09:55:04",32,"/Идём с Майло в деревню?",84658,null],[95516,"2026-07-06T09:58:08",42,"// Ну майло с Иму в карчму хотел бы, встретится с Даниэлем",84658,null],[95517,"2026-07-06T10:00:19",42,"// возможно Майло станет рыцарем. Если набухается хорошо. Мастер спасы тела будут много)",84658,null],[95518,"2026-07-06T10:00:45",42,"// а пока с Арни заканчивай, тэгнишь",84658,null],[95519,"2026-07-06T10:01:14",32,"/могу отдолжить пару бутылок крепкоча",95517,null],[95520,"2026-07-06T10:02:09",42,"/ давай, малой иллюзией придам ей невероятный вкус и запах",84658,null],[95521,"2026-07-06T10:02:22",42,"// этот заговор просто имба",84658,null],[95522,"2026-07-06T10:02:42",42,"// но Арни думаю с утра увидет эту картину",84658,null],[95524,"2026-07-06T10:02:59",32,"/У меня других нужных хватает.",95521,null],[95525,"2026-07-06T10:03:12",42,"// но в этом случае проебал Иму в покер",95523,null],[95526,"2026-07-06T10:04:35",32,"-Ладно я тоже в деревню иду, потому нам по пути",84658,null],[95527,"2026-07-06T10:04:55",32,"(сказал капитально заебаный драконорожденный)",95526,null],[95528,"2026-07-06T10:05:29",42,"// так ладно я покурить и тут",84658,null],[95529,"2026-07-06T10:05:29",9,"//Кинь тело сложностью 10с давно бы пора но вы на травках были",95527,null],[95530,"2026-07-06T10:05:57",32,"//так я же после этого спал с утра до обеда",95529,null],[95531,"2026-07-06T10:06:10",32,"/roll d20",95529,null],[95533,"2026-07-06T10:06:41",9,"*Драконорожденный просто заёбан и не выспавшийся.*",95532,null],[95536,"2026-07-06T10:08:42",42,"— Лады. Потопали. Пошли Иму, вкусно поешь как раз\n°потопал в корчму°",84658,null],[95537,"2026-07-06T10:09:45",9,"*Вы возвращаетесь в деревню, народ немного на взводе. Сам Тёмный лорд был проездом! Хотя он постоянно разьезжает по Темнограду, именно в Дракеризаде бывает раз в несколько лет дай боже и то по делам.*",84658,null],[95538,"2026-07-06T10:11:38",42,"°плевать, главное хочу увидеть того с кем у меня было крепкое рукопожатие и того он и считает другом°",84658,null],[95539,"2026-07-06T10:11:42",32,"(Арминар идёт за тифлингом)",84658,null],[95540,"2026-07-06T10:11:43",9,"*Остатки крепостей всё так же возвышаются на холмах над озером под которым лежит ваш путь. Руины укреплений, словно уставшие стражи. Спокойствие.*",84684,null],[95541,"2026-07-06T10:13:04",9,"*Даниэль сидел без шлема в таверне, сегодня он провёл начало дня продуктивно. Выпил пива, искупался в озере, потом вернулся в корчму продолжить.*",95538,null],[95542,"2026-07-06T10:13:47",32,"-Я привыкаю к тому чтобы быть грязнулей.",84658,null],[95544,"2026-07-06T10:14:32",42,"— Здравия желаю сильный и красивый товарищ! \n°салитирует ему как славному рыцарю, словно по дружески°",95541,null],[95545,"2026-07-06T10:15:17",9,"+ - броня даниэля",84658,null],[95546,"2026-07-06T10:16:01",9,"Даниэль — Ооо, уже думал выйти прогуляться в горы, подышать свежим воздухом. Иди сюда, кормарь — наливай ещё мне и моему другу.",95544,null],[95547,"2026-07-06T10:16:36",9,"*Просто мужик (качок) в форме.*",95545,null],[95551,"2026-07-06T10:19:31",42,"— Вижу как всегда, ты в прекрасной физической форме. Я пожилестее буду. а и сомневаюсь что и в технике я тебя превосхожу) \n°Сел рядом°",95546,null],[95556,"2026-07-06T10:22:43",9,"Даниэль — Чтобы хорошо ударить, не нужна техника, достаточно опыта и силы. — *Кружки поставили на стол и он взял свою.* — Давай по одной! За встречу. Надеюсь на хороший спаринг.",95551,null],[95563,"2026-07-06T10:25:04",32,"-Ну не знаю я как бы хорошо ударить не смогу вообще.\n(Сказал присаживаясь третьим за столом Арминар и выкладывая самодельный ещё теплый шашлык из баранины. (Когда кормил дракона и себе нажарил)) -Закусь будете? Ещё часа три назад блеяла",95556,null],[95564,"2026-07-06T10:25:06",42,"— Меня недооценивать страшная ошибка друг, одна троица бандитов это уже поняла\n°взял вкужку и подставил еë чтобы ими стукнутся и сразу выпить°",84658,null],[95566,"2026-07-06T10:26:37",42,"— Закусь, дело когда брюхо пустое и в глазах темнеет. Но нас врядли так быстро можно вырубить обычным пивом. Так точно товарищ Даниэль?",95563,null],[95570,"2026-07-06T10:28:53",32,"-Ну как хотите. Мое дело предложить. \n(Сам жуёт кусок шашлыка)\n-Кстати Майло а можешь вернуть мне пращу, ты же вроде против оружия а я не хочу новую покупать, к этой привык",95566,null],[95572,"2026-07-06T10:30:43",9,"Даниэль — Я не пью. Это как вода. А чего покрепче? Не моё. — *Покачал головой и навернул ещё кружку.* — Хмель всегда приятен на вкус.",84658,null],[95573,"2026-07-06T10:31:03",9,"//Полутрезвенник, ничё крепкого не пьёт чтобы не опьянеть",84658,null],[95575,"2026-07-06T10:31:23",32,"//Арминар вообще полный трезвенник",95573,null],[95576,"2026-07-06T10:31:40",42,"// ухх.. Ну чтож я буду самое крепкое, если сломаюсь то.. Это уже не буду спойлерить",95573,null],[95579,"2026-07-06T10:32:22",42,"— порою приятно мне забыться и жить время от времени без проблем\n°заказывает самое крепое что есть здесь°",95572,null],[95581,"2026-07-06T10:32:54",32,"- поддерживаю. Но не пью вообще. Хмель ухудшает четкость ума",95572,null],[95583,"2026-07-06T10:33:28",32,"(я протягиваю эму несколько бутылок дварфийского самогона купленного в трактире)",95579,null],[95585,"2026-07-06T10:34:51",42,"— ооо, Арми. Душа тыж моя. Про своего рогатого товарища не забыл\n°взял и начал хлестать с горла в моменты когда от него нечего не хотят°",95583,null],[95586,"2026-07-06T10:35:11",9,"*Даниэль поел, Даниэль выпил но основном пиво. Даниэль доволен.*\n\nДаниэль — Ты хотел спаринг, помнишь? Могу сейчас, после планирую по горам погулять, отдохнуть на природе.",84658,null],[95593,"2026-07-06T10:36:53",42,"— чтож, с радостью. Можем после спаринга в горы. Скалолаз я отменный. На монашеских турнирах хвалили, а вот за спарринги ругали",84658,null],[95597,"2026-07-06T10:37:52",32,"-Даниэль я Арминар я прошу прощения, что забыл представиться. Ты знаешь где в ближайшее время можно быстро заработать. И где можно купить свитки с заклинаниями?",95586,null],[95601,"2026-07-06T10:39:40",9,"Даниель — Не интересовался таким. Денег всегда достаточно. — *Рассмеялся, похоже он жил просто и не сильно роскошевал и рыцарского оклада хватало вполне.*",95597,null],[95608,"2026-07-06T10:41:28",32,"-Ех. Ладно и на том спасибо.\n(Драконорожденный взгруснул) Мой друг тяжело заболел и при смерти. Нужно много денег чтобы его спасти.\n(Ни капли лжи)",95601,null],[95618,"2026-07-06T10:44:41",9,"Даниэль — Чей это так? Плохо.",95608,null],[95622,"2026-07-06T10:45:59",32,"- да именно и ищу работу. \nЛадно буду думать дальше",95618,null],[95623,"2026-07-06T10:46:19",32,"(Кивает драконорожденный.)",84658,null],[95633,"2026-07-06T10:50:22",9,"Даниэль — Могу немного в долг дать, коли очень нужно. При себе не ношу большие суммы. — *Предложил он.*",95622,null],[95643,"2026-07-06T10:54:06",42,"— чтож друг мой. Не нужно. У нас с Иму золота не мало, да, могучий Дракон? Присаживайся поешь с нами\n°отодвинул стул для Иму°",95633,null],[95645,"2026-07-06T10:55:20",32,"(Арминар качает головой в отрицании) \n-если бы все было так просто я бы позвал товарища из клана или взял в клановой казне.\nВ общем спасибо, но видимо тут надо думать самому",95633,null],[95646,"2026-07-06T10:57:07",9,"*Иму сел рядом с Майло.*\n\nИму — Нужно меняться? — *Помнит тот самый урок с деньгами но переспрашивает тифлинга, вдруг не нужно, есть он хочет а меняться нет, ну впрочим есть чуть чуть сильнее.*",95643,null],[95651,"2026-07-06T10:59:22",42,"— Да Иму, меняться. Щас поедим чтобы набраться сил для завтрашнего дня чтобы наши сокровища могли пополнять\n°делает гордый вид перед Даниэлем что научил драка торговле°",84658,null],[95653,"2026-07-06T11:00:40",42,"— отдаëм парочку монеток сейчас и получаем десятки завтра. Выгодно же, друг?",84658,null],[95655,"2026-07-06T11:01:52",9,"*Нехотя, Иму соглашается. Всё же Майло для него словно мудрец, как его отец.*",84658,null],[95658,"2026-07-06T11:09:57",32,"-Кстати Иму а кто твой отец?\n(Арминар заскучал и его ум сразу нашёл что изучать)\n-Ты говорил что он мудрец",84658,null],[95659,"2026-07-06T11:13:20",9,"Иму — Мудрец! Он делает магию, как ты. Много книг, много друзей с длинными ушами. — *Он показал длинные уши, там где они должны быть.* — Но у него нет длинных ушей, он человек.",95658,null],[95664,"2026-07-06T11:15:57",32,"(у Арми начался нервный тик.)\nХорошо, перефразирую.\nГде он живёт, если что \"он\" это твой отец мудрец.",95659,null],[95665,"2026-07-06T11:16:41",9,"Иму — Большая башня, на горе. Далеко.",84658,null],[95666,"2026-07-06T11:17:55",9,"*Похоже он не сможет назвать где точно.*",84658,null],[95667,"2026-07-06T11:18:52",42,"— Да не докапывайся до Иму, главное что он со мной и что он хороший малый, которого тискать не стоит\n°цикнул губами и глазами показал на перчатку покусанную Даниэля°",84658,null],[95668,"2026-07-06T11:19:56",9,"*Даниэль слегка улыбнулся.*\n\nДаниэль — Но мне тоже интересно, что это за кобольд у которого отец — мудрец.",95667,null],[95669,"2026-07-06T11:20:26",9,"Иму — Я дракон!\n\nДаниэль — Ладно, дракон, дракон.",84658,null],[95670,"2026-07-06T11:20:37",42,"°завернул глаза в веки и косплеит эту гифку°\n— ошибка новичка",95668,null],[95672,"2026-07-06T11:22:46",42,"— я уверен что он дракон, ибо помню как он угостил меня своей кровью.. У меня появилось чувство что моë тело стало крепкче (на 1 хп)",84658,null],[95834,"2026-07-06T13:05:34",42,"// думаю мааалооость было бы не жирно черту подогнать мускулистый 👌",84658,null],[95839,"2026-07-06T13:09:04",42,"// хотя я приятно идивлëн что Даниэль имеет +9 на атлетику. За жопу трудно будет ухватиться)",84658,null],[95866,"2026-07-06T14:32:28",9,"Даниэль — Ну, всякое бывает. — *Заинтепесованым взглядом окинул Иму, но не то чтобы поверил.*",95672,null],[95922,"2026-07-06T15:14:38",42,"— поверишь или нет. Нооо он считай как мой покровитель и друг\n°во время болтовни пошëл и взял у Арми баранинку и угостил Иму°\n— Пока покушай это, щааа.. Отец кормящий, пожалуйста самое мясное и самое вкусное для моего чешуйчатого друга",95866,null],[96055,"2026-07-06T18:15:05",9,"*Иму кушает, довольный.*",95922,null],[96056,"2026-07-06T18:15:56",9,"// @Jak_Zak @Xaosick в принципе, квест окончен. Доделайте что планировали — отыграем и мы заканчиваем, распишу итоги 😏👌",84658,null],[96057,"2026-07-06T18:18:08",42,"// спаринг",84658,null],[96058,"2026-07-06T18:18:16",42,"// требую пиздело",84658,null],[96059,"2026-07-06T18:20:08",42,"— Тааак, Даниэль увы. К сожалению мне придëтся снова идти и скитаться. Исполнишь моë желание на прощание? Дуэль которую так я и жаждал всë приключение здесь",84658,null],[96060,"2026-07-06T18:21:47",9,"Даниэль — Помню, я обещал. — *Он осушил кружку и надел шлем играя мышцами.* — Думаю никто не будет против нашего спаринга у тааерны.",84658,null],[96061,"2026-07-06T18:22:48",42,"— главное чтобы под руку не попались) \n°осушил бутылку и встал разминая плечи и шею°",84658,null],[96062,"2026-07-06T18:25:01",9,"*Даниэль встал чуть сбоку от таверны, занял стойку и в латной перчатке показал \"иди сюда\". Похоже доспех он снимать не собирался, но с другой стороны казалось что доспех скорее украшение, нагрудник то отсутствовал.*",84658,null],[96063,"2026-07-06T18:25:11",42,"// я думаю у него кд 17 или 18",84658,null],[96064,"2026-07-06T18:25:11",9,"//Ты ходишь. Ходит он и так далее",84658,null],[96065,"2026-07-06T18:26:12",9,"//17 и в доспехах и без)",96063,null],[96066,"2026-07-06T18:26:41",42,"°делает распрыжку разминая секунд 5 ноги и делает рывок с толчка ногой и пытается нанести удар, а после в захват°",84658,null],[96067,"2026-07-06T18:26:54",42,"// дурацкая идея с его +9 атлетики)",84658,null],[96068,"2026-07-06T18:27:08",42,"/r 1d20 +6",84658,null],[96070,"2026-07-06T18:27:21",9,"//Удар попал",84658,null],[96071,"2026-07-06T18:27:58",42,"/r 1d8 +4 ударил локтëм по снизу в верх в челюсть",96069,null],[96073,"2026-07-06T18:28:20",42,"/r 1d20 +6 сразу хватает его",84658,null],[96075,"2026-07-06T18:28:24",9,"*Слека больно, тебе. Челюсть то в шлеме.*",84658,null],[96076,"2026-07-06T18:28:36",9,"/roll 1d20+9 атлетика",84658,null],[96078,"2026-07-06T18:28:44",42,"// ну я пытался)",84658,null],[96079,"2026-07-06T18:29:19",42,"// вообще могу хитрожопить по лютому.. Если тебе на кубы будет не везти",84658,null],[96080,"2026-07-06T18:29:34",9,"/roll 1d20+9 просто удар с руки, видно что он пока не старается",84658,null],[96082,"2026-07-06T18:30:31",9,"//Скок кд у тебя?",84658,null],[96084,"2026-07-06T18:30:44",42,"// 16",96082,null],[96085,"2026-07-06T18:31:18",9,"//Щас вспомню есть ли у него мультиатака)",84658,null],[96086,"2026-07-06T18:31:50",9,"//Есть, вижу",84658,null],[96087,"2026-07-06T18:31:58",42,"// нехрена себе 2 лвл против 5 лвл воина)",84658,null],[96088,"2026-07-06T18:32:21",9,"*Даниель пока не бьёт ещё, но видишь что он не старается пока, разминается.*",84658,null],[96089,"2026-07-06T18:32:26",9,"//Воин?)))",96087,null],[96090,"2026-07-06T18:32:40",42,"// лааадно, интересно. Что выйграет. перс перекач или твои встратые кубы",84658,null],[96091,"2026-07-06T18:32:47",42,"// как битва говна и мочи",84658,null],[96092,"2026-07-06T18:33:29",42,"// мой ход?",96088,null],[96093,"2026-07-06T18:33:43",9,"//Ходи пока, он разминается, не в полнуб силу бьёт",84658,null],[96094,"2026-07-06T18:34:57",42,"°Тифлинг сменил стойку, он начал легонечно подпрыгивать и держит свой рост ниже Даниэля° (бокс стойка)",84658,null],[96096,"2026-07-06T18:35:22",9,"*Даниель и так на голову выше.*",84658,null],[96097,"2026-07-06T18:35:26",42,"°делаю действие уклонение и бонусным ударяю его кулаком°",84658,null],[96098,"2026-07-06T18:35:43",42,"/r 1d20 +6",84658,null],[96100,"2026-07-06T18:36:13",42,"°непривычная стойка, ведь он еë только что придумал на ходу°",96099,null],[96101,"2026-07-06T18:36:17",9,"*Он словил твой кулак пресом, даже не уворачивался. Бить его туда бесполезно.*",84658,null],[96102,"2026-07-06T18:37:08",42,"// ход",84658,null],[96103,"2026-07-06T18:38:38",9,"*Видя что ты уворачиваешься, он раззадорился, ударил кулаком о кулак и его движения стали быстрее.*",84658,null],[96104,"2026-07-06T18:39:00",9,"/roll 1d20+9 помеха и преимущество без, атлетика на захват",84658,null],[96106,"2026-07-06T18:39:18",42,"/r 1d20 +6",84658,null],[96108,"2026-07-06T18:39:30",42,"// стоп, а преимущество от куда?",84658,null],[96110,"2026-07-06T18:39:54",9,"*Ты понимаешь что это не воин а варвар, и он атакует безрассудно.*",84658,null],[96111,"2026-07-06T18:40:15",42,"// ну всо. Гудбай Майло",84658,null],[96112,"2026-07-06T18:40:46",42,"// варвар с мультиатакой это пизда страшно",84658,null],[96113,"2026-07-06T18:40:51",9,"*Он берёт Майло прямо за руку и метает его на дьщину метров от себя.*\n\n//Второй атакой он теья бросил",84658,null],[96114,"2026-07-06T18:41:04",9,"/roll 1d6 дробящего от падения",84658,null],[96116,"2026-07-06T18:41:29",9,"//У варвара есть мультиатака от класса, но всего 2 раза",96112,null],[96117,"2026-07-06T18:41:54",42,"// у как, одна есть. Осталось пережить вторую",84658,null],[96118,"2026-07-06T18:42:06",42,"// 21 хп",96115,null],[96119,"2026-07-06T18:42:15",9,"//Так он первой захватил а второй метнул тебя",84658,null],[96120,"2026-07-06T18:42:36",42,"// а 22. Я забыл добавить от благословения  Иму",84658,null],[96121,"2026-07-06T18:42:37",9,"Даниэль — Вставай, вижу ты можешь лучше...",84658,null],[96122,"2026-07-06T18:42:57",9,"//Он бещрассудно бил, по нему щас с преимуществом",84658,null],[96123,"2026-07-06T18:43:41",42,"°Майло хоть выглядит худоват, но он ещë тот атлет и встаëт без проблем и идëт к Даниэлю° (черта атлетичный позволяет дойти до него без потери скорости? )",84658,null],[96124,"2026-07-06T18:44:37",42,"°подходит и бьëт дважды кулаками, увидев брешь в его обороне, походу он увлëкся такой атакой°",84658,null],[96125,"2026-07-06T18:45:49",42,"/r +d20 +6 Бьëт ему двумя пальцами в подмышку\n/r +d20 +6 второй атакой ударом ногой \"Торнадо\"",84658,null],[96127,"2026-07-06T18:46:04",9,"//Обе попали",84658,null],[96128,"2026-07-06T18:46:43",42,"/r 1d8 +4 удар пальцами по подмыхе\n/r 1d8 +4 удар ногой вертушкой",84658,null],[96130,"2026-07-06T18:47:16",42,"// 15 урона щас, 20 в сумме нанëс",84658,null],[96131,"2026-07-06T18:47:39",9,"*Похоже Даниэль особо не уворачивался принимая удары лицом. С другой стороны — казалось он их почти не чувствовал и даже раззадоривался.*",84658,null],[96132,"2026-07-06T18:48:20",9,"/roll +d20+9\n/roll +d20+9 железные кулаки летят в майло, вообще без намеренья защититься",84658,null],[96134,"2026-07-06T18:48:55",42,"// так больше мультов нету, зато все попали",84658,null],[96135,"2026-07-06T18:49:01",9,"/roll 1d8+4\n/roll 1d8+4 у него тот же боевой стиль но взят чертой",84658,null],[96137,"2026-07-06T18:49:14",42,"// 4 хп осталось",84658,null],[96138,"2026-07-06T18:49:20",9,"//Сорян, сила +5, там на 2 урона больше)",84658,null],[96139,"2026-07-06T18:49:33",42,"// 2 хп",84658,null],[96140,"2026-07-06T18:50:42",9,"*Два тяжелейших удара, в грудь и в плечо. Словно сбил поезд. Даниэль ударяет кулаком о кулак.*\n\nДаниэль — Ух, будет из тебя дело. Не полёг от первой двоечки.",84658,null],[96141,"2026-07-06T18:52:20",9,"*Он смотрит на тебя, продолжает ли Майло?*",84658,null],[96142,"2026-07-06T18:53:18",42,"°клюнул кровью из-за рта себе под ноги и снова стал в стойку через боль°\n— Не забывай что я Молокосос ещë, потенциала во мне хоть убавляй. Играем до потери сознания\n°встаëт опять в эту странную стойку и ударяет лишь раз, не привычно и не удобно°",84658,null],[96143,"2026-07-06T18:53:33",42,"°действие уклонение и удар°",84658,null],[96144,"2026-07-06T18:53:43",42,"/r +d20 +6",84658,null],[96146,"2026-07-06T18:53:55",42,"//позволь я это отыграю",84658,null],[96147,"2026-07-06T18:54:01",9,"//Го",84658,null],[96148,"2026-07-06T18:55:03",42,"°нанося удар по Даниэлю у Майло закатываются глаза и резко встаëт приходя в чувство поэтому удар не успех нанести и в той же стойке стоит°",84658,null],[96149,"2026-07-06T18:55:27",9,"/roll 1d20+9 захват",84658,null],[96151,"2026-07-06T18:55:41",42,"/r 1d20 +6",84658,null],[96153,"2026-07-06T18:56:01",9,"Даниэль — Какой юркий",84658,null],[96154,"2026-07-06T18:56:13",9,"/roll 1d20+9 второй атакой тоже захват",84658,null],[96156,"2026-07-06T18:56:19",42,"// это атлетикой)",96153,null],[96157,"2026-07-06T18:56:51",42,"/r 1d20 +6  Уж нет, я в сознании и значит готов драться",84658,null],[96159,"2026-07-06T18:57:28",9,"*Даниэль кажется улыбается под шлемлм. Но может кажется так как не видно.*",84658,null],[96160,"2026-07-06T18:57:32",9,"//Твой ход",84658,null],[96161,"2026-07-06T18:57:46",42,"// так у него эти были безрассудные если без помех?",84658,null],[96162,"2026-07-06T18:58:06",9,"//Не уклонялся бы ты он бы с преимуществом хватах)",84658,null],[96163,"2026-07-06T18:59:24",42,"— Спасибо друг, походу благодаря тебе я придумал новое боевое искусство. Назову Дани-кундо\n°в той же стойке и тот же удар°",84658,null],[96164,"2026-07-06T18:59:42",9,"Даниэль — Пхахахах",96163,null],[96165,"2026-07-06T18:59:54",42,"/r +d20 +4",84658,null],[96167,"2026-07-06T19:00:07",42,"/r 2d8 +4",84658,null],[96169,"2026-07-06T19:01:03",42,"//Ай мужик. Привык и он к слипингу",96166,null],[96170,"2026-07-06T19:01:06",9,"Даниэль — Ух... — *Он почувствовал последний удар, даже ошатнулся немного.*",84658,null],[96171,"2026-07-06T19:01:42",42,"//ход",84658,null],[96172,"2026-07-06T19:01:45",9,"/roll 1d20+9\n/roll 1d20+9 два резких захвата подряд если уклоняешься",84658,null],[96175,"2026-07-06T19:02:01",9,"//Уклонялся?",84658,null],[96176,"2026-07-06T19:02:15",42,"// да, конечно",96175,null],[96177,"2026-07-06T19:02:26",42,"/r 1d20 +6",96173,null],[96179,"2026-07-06T19:02:45",42,"// я ахуел. Аура фарм у майло",84658,null],[96180,"2026-07-06T19:02:51",9,"//Ахахах, ну будем щитать что то от его 26",84658,null],[96181,"2026-07-06T19:02:55",9,"//Второй. 15",84658,null],[96183,"2026-07-06T19:03:24",42,"/r 1d20 +6",96181,null],[96186,"2026-07-06T19:04:05",9,"*Видно что Даниэль не пытается тебя вырубить, он хочет схватить.*",84658,null],[96187,"2026-07-06T19:04:14",9,"Даниэль — Хорош.",84658,null],[96188,"2026-07-06T19:04:17",9,"//Ход",84658,null],[96189,"2026-07-06T19:04:25",42,"// слышали про последнее дыхание полуорков? Он вдохнул",96184,null],[96190,"2026-07-06T19:05:13",42,"°та же история, стойка (уклонение) и удар°",84658,null],[96191,"2026-07-06T19:05:39",42,"/r +d20 +6",84658,null],[96193,"2026-07-06T19:05:51",42,"/r 1d8 +4",84658,null],[96196,"2026-07-06T19:11:27",9,"/roll 1d20+9\n/roll 1d20+9 два резких захвата подряд",84658,null],[96198,"2026-07-06T19:12:27",42,"/r 1d20 +6\n/r 1d20 +6",84658,null],[96200,"2026-07-06T19:12:43",42,"// ладно я в захвате",84658,null],[96201,"2026-07-06T19:13:39",9,"*Майло скрутили, а потом Даниэль взял его помышку и пошёл в корму.*\n\nДаниэль — Всё, добегался. Не хочу чтобы ты помер, с меня пиво. — *Несёт тебя бухать.*",84658,null],[96202,"2026-07-06T19:14:37",42,"— О как, ну ты уже угоманил мою жажду битвы\n°нëсся куда понесëт Даниэль°",84658,null],[96203,"2026-07-06T19:14:53",9,"//100 опыта Майло за фарм ауры",84658,null],[96204,"2026-07-06T19:15:24",42,"// 2 хп такое раздал. Даже интересно сколько урона нанëс",84658,null],[96205,"2026-07-06T19:16:00",9,"*Бой с противником что намного сильнее тебя, хоть он и не срадался в полную силу, был познавательным.*",84658,null],[96206,"2026-07-06T19:16:52",42,"// заставил мастер использовать бокс в фэнтези)",96205,null],[96207,"2026-07-06T19:17:48",42,"// муай-тай тут бы мне не помог. Бесконечные мультиатаки, хотя сказал их 2 и преимущества справедливые",84658,null],[96208,"2026-07-06T19:18:52",42,"// у меня лвл ап)",84658,null],[96209,"2026-07-06T19:19:55",42,"// теперь у меня есть ци)",84658,null],[96212,"2026-07-06T19:42:30",42,"// 40 урона нанëс в сумме. Я доволен",84658,null],[96213,"2026-07-06T19:49:02",9,"//Короче:\n\nМайло: 300 опыта за квест ещё\n\nАрминар: тоже 300 опыта",84658,null],[96214,"2026-07-06T19:53:10",9,"// Ждите раздел с напарниками @Jak_Zak @Xaosick . Если что я немного готов поотыгрывать туда сюда. Если надо. Ну и Арминару прийдётся периодич5ски сюда возвращаться)))",96213,null],[96215,"2026-07-06T19:53:44",42,"// Оке, Иму. Я выбираю тебя",96214,null],[96217,"2026-07-06T19:54:52",32,"Я хотел к сыну кузнеца сходить и помочь справится с потерей. У меня для этого знамение 20 удачно было",96214,null],[96218,"2026-07-06T19:55:16",32,"//Но у меня только сейчас получилось зарядить телефон",84658,null],[96219,"2026-07-06T19:57:34",9,"//Го сходим если хочегь",96217,null],[96220,"2026-07-06T19:57:44",9,"//Тема не закрыта)",84658,null],[96221,"2026-07-06T19:58:29",32,"//да дай мне немного времени. Чуть вечерее, через часик. Я буду готов и да хочу",96219,null],[97217,"2026-07-07T14:21:09",32,"//не против сходить к сыну кузнеца как момент ещё до похода в виспераль",96219,null],[97302,"2026-07-07T14:53:48",9,"//Ты пиши а я буду отвечать. В принципе это сейчас твоя тема считай с драконом, так что ты будешь в этом месте частым гостем. Надеюсь ты не забываешь что у тебя траты 50 зм в день? Сегодня первый.",97217,null],[97311,"2026-07-07T14:57:40",32,"//У меня столько пока нет. Даже если всеми персами скинуться.\nМожно набор целителя засчитать место сегодняшней цены?",97302,null],[97319,"2026-07-07T15:00:16",32,"//как только столько заработаю так сразу оплачу",84658,null],[97330,"2026-07-07T15:03:45",5,"// кредит и проценты капают",84658,null],[97350,"2026-07-07T15:21:13",32,"//я знал что драконы самые жадные существа и любят золото но даже не подозревал что я буду это золото платить добровольно",97330,null],[97371,"2026-07-07T15:27:43",9,"//Ну это эпик, безвопросов 😂👍",97350,null],[97372,"2026-07-07T15:27:59",32,"(Арминар после того как попрощался с уходящим тифлингом двинулся к кузне так как дома нет то логично что подмастерье будет либо в кузне либо у соседей)",96219,null],[97376,"2026-07-07T15:29:55",9,"*Подмастерье трудился в поте лица, ему помогало пару каких-то мужиков, неумёхи. Похоже староста прислал ему помощ из дех долбо... — дураков что пошли на дракона. Коваля что это устороил поздно винить, он повел мужиков на дракона, он и помер там.*",84658,null],[97380,"2026-07-07T15:32:16",9,"Молодой подмастерье — Хадил на драка? Тошно помер ужик? Говоряд Темнейший сразиль яго. — *Видно злость, не на батю, на дракона что убил батьку. Как увидел Арминара — сразу спрашивать.*",84658,null],[97386,"2026-07-07T15:36:30",32,"я даже видел бой. Вся гора тряслась. Лорд сказал что уже издохнуть был должен.\n(Подошёл Арминар) А перед приходом лорда я даже с своим товарищем успели с драконом поговорить. \nЕх совершенно не агрессивный ящер был. И оказалось в деревню прилетел потому что воды попить захотелось. \n(Рассказывает историю) А его здесь и накуканили из-за чего и произошел бой и потом столько народу полегло",97380,null],[97396,"2026-07-07T15:39:13",9,"Молодой подмастерье — Не сказывай, сказки. — *Он не поверил в доброту ящера, а потом махнул рукой.* — Ну раз гор ега придавить, то добра. Хотел чаго, али как?",97386,null],[97401,"2026-07-07T15:40:26",32,"-Да.. даже не знаю честно.\n(Повинился драконид) Поддержать хотел а как-то не так все идёт как планировалось.",97396,null],[97423,"2026-07-07T15:47:57",32,"//эм Еклипсо а что смешного?",97386,null],[97439,"2026-07-07T15:54:04",8,"/если зайдёшь в таверну, дам взаймы 20 золотых без процентов, только верни потом (у моего персонажа нет фин. грамотности)",97423,null],[97444,"2026-07-07T15:56:37",9,"Молодой подмастерье — Да ладна. Батька сам пашол, я бы с ним да не пусчал. — *За работой не видно но парень был немного грустным, батька был хорош у него.* — Хади, еси нет дела. Работы пална. Батька за траих ковал, а эти и двоя за елиного не порают.\n\n*Явно ругал подмастерье своих горе помощников. Он теперь тут кузнец, раньше чем планировалось, но стал.*",97401,null],[97484,"2026-07-07T16:04:47",32,"//спасибо. Как только ток сразу",97439,null],[97489,"2026-07-07T16:05:33",9,"//Всем сервером будем на дракона скилываться 😂👍👍👍👍",97439,null],[97494,"2026-07-07T16:06:23",9,"//И правда, это в одиночку не потянуть",84658,null],[99155,"2026-07-08T00:32:41",32,"Ночь поздняя луна молодик.\nАрминар. Заползает в логово дракона. \nКое как заливает эму зелье лечения и начинает мазями обрабатывать раны",84658,null],[99156,"2026-07-08T00:33:33",32,"С утра ещё сходит на охоту, приготовит есть, и двинется дальше работать.",84658,null],[99157,"2026-07-08T00:33:42",42,"// уже скинулся",97489,null],[99166,"2026-07-08T01:05:11",32,"(Одно зелье лечения я оставлю себе на всякий случай а три у дракона в логове оставлю. Если станет хуже или я не прийду вовремя как нибудь выпьет.)",84658,null],[99167,"2026-07-08T01:08:21",42,"// тамагочи у тебя выходит",99166,null],[99168,"2026-07-08T01:08:50",32,"//что такое Тамагочи?",99167,null],[99169,"2026-07-08T01:09:25",9,"//Инет ожил, могу поотыгрывать если хочешь. Только описывай что делаешь",99168,null],[99170,"2026-07-08T01:10:07",32,"//Квархадрон ведь не совсем беспомощен. Потому как нибудь что-нибудь сделать способен. А ещё. Ты ведь ведешь какой-то учёт успеха исцеления?",99169,null],[99171,"2026-07-08T01:12:25",32,"Ну сначала Арминар обработал раны дракона потом ещё раз осмотрел Майло. А потом улёгся спать. \nС утра сел переписать заклинание волшебных стрел",84658,null],[99172,"2026-07-08T01:12:54",32,"И после двинул на охоту. Дракона надо покормить.",84658,null],[99173,"2026-07-08T01:13:46",9,"//А деньги на волшебные стрелы есть кстати? Там не бесплатно учится, напомню)",84658,null],[99174,"2026-07-08T01:15:15",32,"Да 25 золотых на чернила у меня есть",99173,null],[99175,"2026-07-08T01:15:29",32,"Займ зелий дал возможность купить чернил",84658,null],[99176,"2026-07-08T01:16:52",32,"//я помню 25 если учишься и 10 если сам пишешь уже известное. За уровень",99173,null],[99177,"2026-07-08T01:19:21",32,"После охоты (Арминар уже знает территорию)\nГотовит и немного тролит дракона и тифлинга кормя обоих.\n-Скажы ааа. Молодец! (Кормит дракона)\n-А теперь за папу, а теперь за маму(кормит тифлинга предварительно наложив на себя псевдожинь второй ячейкой)",99169,null],[99178,"2026-07-08T01:20:41",42,"// игра сложная где надо было ухаживать за животиной, проглядишь на секунду. Умрëт",99168,null],[99179,"2026-07-08T01:21:14",32,"//может быть",99178,null],[99180,"2026-07-08T01:22:14",42,"// не забывай что у тебя есть верный товарищ которому достаточно 3 золотых в день на своë проживание с Иму, остальной излишок не нужен",99179,null],[99181,"2026-07-08T01:22:47",32,"//Спасибо блин скоро нас будет четверо. Ну примерно скоро",99180,null],[99182,"2026-07-08T01:22:52",9,"*Дракон просто лежит делая глотательные движения. Если бы не это могло бы показаться что он умер, ведь с твоей стороны была часть лица с оголённым черепом и пустой глазницей.*",99177,null],[99183,"2026-07-08T01:23:48",9,"//25 это ток за свою школу",84658,null],[99184,"2026-07-08T01:24:13",32,"//ну там своими фразочками скорее себя развлекает",99182,null],[99185,"2026-07-08T01:24:29",32,"//тогда пардон. Не изучаю не хватит",99183,null],[99186,"2026-07-08T01:24:55",42,"°открыл рот и съел°\n— Если помру увы. За еду вернуть должок не смогу\n°болезнетворно кашляет°",99177,null],[99187,"2026-07-08T01:25:00",9,"//Ты с ним не разговариваешь, вот он и не реагирует особо)",99184,null],[99188,"2026-07-08T01:25:30",42,"// у меня ещë золотишко осталось (18), могу докинуть",99185,null],[99189,"2026-07-08T01:25:32",32,"+Не помрёшь",99186,null],[99190,"2026-07-08T01:25:44",32,"//Все равно не хватает",99188,null],[99191,"2026-07-08T01:26:22",42,"// Hard а сколько я получу если продам мой артефакт?",84658,null],[99192,"2026-07-08T01:27:04",9,"//Какой?",99191,null],[99193,"2026-07-08T01:27:17",42,"// медальëн силы",99192,null],[99194,"2026-07-08T01:27:35",9,"//Да там 15 золотых",84658,null],[99195,"2026-07-08T01:27:45",32,"-Квархадрон. Знакомься это Майло. А ну вы заочно знакомы но теперь ты знаешь его не заочно. \nЕсли что я вот здесь оставлю зелья лечения, пей если станет плохо или если я не прийду завтра.",99187,null],[99196,"2026-07-08T01:27:47",9,"//Но хардинт за 50 купит",84658,null],[99197,"2026-07-08T01:27:57",32,"//что за медальон?",99193,null],[99198,"2026-07-08T01:28:16",42,"// который пойдëт на твоë обучение",99197,null],[99199,"2026-07-08T01:28:27",42,"// ну давай",99196,null],[99201,"2026-07-08T01:29:27",32,"(Тогда точно хватит хе)",84658,null],[100919,"2026-07-08T21:13:19",32,"Мы с Майло под обед прибыли к логову Квархадрона",84658,null],[100944,"2026-07-08T21:17:04",9,"//Я не в состоянии, и во время кчеста нельзя",84658,null],[100959,"2026-07-08T21:18:48",32,"Мы можем попросить чтобы нас на отдыхе подождали и сбегать",100944,null],[100965,"2026-07-08T21:21:09",42,"// так не работает, если в квесте. То всë",100959,null],[100966,"2026-07-08T21:21:20",42,"// ты а этой точке",84658,null],[104071,"2026-07-09T21:58:29",32,"Так теперь сюда",84658,null],[104072,"2026-07-09T21:58:43",32,"@Jak_Zak",84658,null],[104073,"2026-07-09T21:58:47",42,"Тута",84658,null],[104074,"2026-07-09T21:58:49",32,"Hard",84658,null],[104075,"2026-07-09T21:58:53",9,"//Я щас занят ирл",84658,null],[104076,"2026-07-09T21:59:11",42,"Кстати Hard я выздоровел. Заметочка",84658,null],[104078,"2026-07-09T21:59:17",32,"//хорошо как будешь поотыгрываем",104075,null],[104084,"2026-07-09T22:00:34",42,"Но заболел другой заразой. Теперь он чешуйчатый, Змеиный язык, и пожирает врагов. И винит в этом Арми. Якобы укусил и эффект вампира",104076,null],[104090,"2026-07-09T22:02:10",32,"(Арми по пути купил чеснок и подсовывает к лицу напарника)\n(Сок для драконьего обоняния крайне неприятный)",104084,null],[104097,"2026-07-09T22:04:02",42,"— Убери эту гадость! Заразил меня. Ещë и издевается\n°шикнул на честнок с высунутым змеиным языком, а из-за рта течëт кислота°",104090,null],[104100,"2026-07-09T22:05:22",32,"(Арминар сам морщился от него но такая реакция вызвала приступ истерического хохота)\nХпхаха Майло! Ну ты выдал!",104097,null],[104106,"2026-07-09T22:07:47",42,"— Ага Ага.. Укусил меня ночью и рану восстановил магией хитрожоп, я читал что вампиры так делают, кусают и ещë один вампир. ИИИИИИ УБЕЕЕРИИИИ ЧЕЕЕЕСТНООООКК. А не то.. А не то.. \n°не может даже придумать угрозу из-за вони честнока и издëвок напарника°",84658,null],[104107,"2026-07-09T22:08:24",32,"/roll d20+4\nУбеждение мастера на излечение дракона",84658,null],[104109,"2026-07-09T22:08:24",32,"Ммммм....",84658,null],[104110,"2026-07-09T22:08:25",32,"Источник хня, но ты бля издеваешься",84658,null],[104111,"2026-07-09T22:08:25",32,"Из какой жопы вытащил результат 22)",84658,null],[104112,"2026-07-09T22:08:25",32,"Это как знамение, эх",84658,null],[104113,"2026-07-09T22:08:26",32,"Ты победил, за меня решила судьба, хотя не жди что это сработает в следующий раз",84658,null],[104115,"2026-07-09T22:08:26",32,"Любое другое число было бы отказом)",84658,null],[104117,"2026-07-09T22:08:27",32,"//ну ты играешь против псионика экстрасенсорики играющего за мага прорицателя. Двойной удар",104115,null],[104123,"2026-07-09T22:09:28",9,"*Дракон всё так же лежит на месте, его дыхание ели слышно.*\n\n//Чтож, но я щас ирл занят и буду на 2 фронта так что соре",84658,null],[104126,"2026-07-09T22:10:18",42,"// нечего, друг друга эти стоят, смогут развлечить друг друга",104123,null],[104127,"2026-07-09T22:10:23",32,"Арминар заходит в логово. И высыпает из сумки горку золота и гору серебра под лапы дракону",104123,null],[104128,"2026-07-09T22:10:41",32,"-Ты как здоровяк. Ещё жив, чертяка?",84658,null],[104131,"2026-07-09T22:11:24",42,"°смотрит на это и не понимает зачем°\n— Тааак, а зачем монеты высыпаешь?",84658,null],[104132,"2026-07-09T22:11:29",32,"-Так я нашёл чем тебе помочь.",84658,null],[104138,"2026-07-09T22:12:32",32,"(телепатией Майло)-Не хочу чтобы меня ещё раз гоблин обокрал.\n(В слух)\nКак зачем? Это подношения чтобы жажда золота тянула к нам",104131,null],[104145,"2026-07-09T22:14:09",42,"(Телепатией отвечаю) — ты же вкурсе, я здор и могу обогнать даже Лошадь под адреналином. Так что золото в безопасности и ты если тебя похитят. Налог платить не хочу за тебя. Ты и так скоко денег сожрал",104138,null],[104147,"2026-07-09T22:14:13",32,"Достает пузырьки с лунной водой. Расставил их рядом и начал пришывать кожу к изодранонэму крылу и шее. При помощи Майло по ремонтируем челюсти я лечением ран буду лечить после снятия швов где срослось вставил трофейный новый глаз и зальем водичку",84658,null],[104155,"2026-07-09T22:16:31",42,"— Набор травника есть у меня и несколько купил. Так что я присоеденюсь\n°помогает Арми делая большому дракону куча обезбола и микстуры на раслабон чтобы мясо с кожей было легче прошить°",104147,null],[104178,"2026-07-09T22:21:59",42,"°Варит настойки и болтает поперечно°\n— Укусил и сделал себе подобным со мной не согласовсвшись.. Теперь тут все драконы, хотя я.. Дампиры есть значит я Дамкон? А я ведь всем сердцем не мог терпеть драконов. Хотя эта стая исключение.. Гады создали мне преграду с Даниэлем, если же стану рыцарем, мне бы пришлось вас всех тут положить\n°говорит это с иронией и с шуткой, ибо братская любовь ему и помогла спасти от смерти Арми°",84658,null],[104201,"2026-07-09T22:28:02",32,"-драконид ты. Но ничего то что ещё недостаточно одраконился это поправимо",104178,null],[104209,"2026-07-09T22:29:44",42,"— Значит не отрицаешь что ты заразил? Ладно, это поправимо\n°заскалил улыбку и сменил облик на свой старый демонический°",104201,null],[104211,"2026-07-09T22:29:51",32,"Арминар проходился магией лечения ран по дракону буквально по КД. \nСнял все лишние швы и восстановив крыло. \nПересадка глаза была в его опыте первой и до этого он знал об этом только пару слов в теории но будем надеяться магия все спишет",84658,null],[104213,"2026-07-09T22:30:10",32,"-Я вообще заразный.",104209,null],[104216,"2026-07-09T22:30:45",32,"-Квархадрон. Ты как? Два там? Ответь",84658,null],[104223,"2026-07-09T22:31:35",42,"— Брат ещë называется. Пока я спал кусаешься. Мою прекрасную внешность задраконил",104213,null],[104227,"2026-07-09T22:31:42",32,"(Долгий отдых для восстановления ячеек)\n(после разбираемся почему у него челюсть не двигается и нах все ломаем и переделываем так чтобы работало)",84658,null],[104231,"2026-07-09T22:32:05",32,"-А на мой взгляд ты стал красивее",104223,null],[104232,"2026-07-09T22:32:19",32,"Тебе рога прямо идут",84658,null],[104235,"2026-07-09T22:32:36",32,"-Жаль только чешуйки не аметистовые.",84658,null],[104239,"2026-07-09T22:33:25",42,"— капитан очевидность. \n°постукивает рога те которые у него были с рождения иллюзорные, а настоящие стали лишь острее и агрессивнее формы°",84658,null],[104244,"2026-07-09T22:34:14",42,"— чешуя меняет цвет от настроения или если сконцентрируюсь на цвете",104235,null],[104439,"2026-07-09T23:10:16",9,"*Не реагирует почти, только слегка подвинулголрву что-то почуяв.*",104128,null],[104473,"2026-07-09T23:15:39",9,"//Вы его лечите, да?",84658,null],[104531,"2026-07-09T23:25:57",32,"Да два медика и капитально",104473,null],[104533,"2026-07-09T23:26:51",32,"(я эму дам не реагирует. Сейчас Майло эму сломанную челюсть будет вправлять посмотрим как он будет игнорировать)",104439,null],[104539,"2026-07-09T23:31:21",9,"*Вода будто потеряла часть своей целительной силы, но, кажется... кажется регенерация дракона начала работать снова, его дыхание медленно стало тяжелее а сердце биться сильнее. Квархадрон поднял голову, посмотрел мутным взглядом на Арминара, внимательно, прежде чем снова лечь.*",84658,null],[104540,"2026-07-09T23:31:29",42,"// Да-да, Майло помогает этому заразному драконорождëному",84658,null],[104542,"2026-07-09T23:33:00",32,"-Вот жыв! Теперь осталась сущая мелочь. \n(Оскалился драконорожденный)",104539,null],[104543,"2026-07-09T23:33:07",9,"//Жаль только кто-то игнорит свою же телепатию",84658,null],[104545,"2026-07-09T23:34:05",42,"// ыхых. Я нечего, я захватываю власть в цигании :)",84658,null],[104546,"2026-07-09T23:34:26",32,"(ну вообще-то не игнорю а к дракону телепатией и обращался все время)",104543,null],[104547,"2026-07-09T23:34:38",32,"Потому и все слышу",104543,null],[104549,"2026-07-09T23:35:29",9,"//Пиши тогда что телепатия. Нет заявки нет телепатии. А то она ток к Майло",84658,null],[104551,"2026-07-09T23:35:45",32,"Ок.",104549,null],[104552,"2026-07-09T23:36:11",32,"(телепатия)-квархадрон ты как себя чувствуешь?",104542,null],[104572,"2026-07-09T23:39:15",9,"??? — ... Квархадрон, ты всё ещё слышишь стук молотов... — *Он среагировал на телепатию, почувствовал её, подвинул ногу переминувшись.* — ... всё ещё слышу стук молов, удары, гордость коренастого народа.\n\n*Он не счео нужным отвечать на вопрос, просто поведал о мысли которой думал всё это время.*",84658,null],[104579,"2026-07-09T23:40:26",32,"(телепатия)-Если тебе станет от этого больше желания проснуться то у тебя под лапами почти 20 фунтов золота и 120 фунтов серебра.",104572,null],[104582,"2026-07-09T23:40:50",32,"-Так что давай к нам",104572,null],[104587,"2026-07-09T23:41:56",9,"Квархадрон — Хочешь подкупить меня золотом и драгоценностями или это дар? Есть ли граница твоей наглости когда меня не волнует злато.",84658,null],[104594,"2026-07-09T23:43:51",9,"*Отвечает мысленно на телепатию.*",84658,null],[104599,"2026-07-09T23:44:52",32,"(телепатия)-Хе знаю я как тебя злато не волнует. \nТы только телепата то это не говори. Да и за золото можно приобрести то что тебе надо а серебро отличный материал для ковки лично для этого столько и набрал",104587,null],[104605,"2026-07-09T23:45:45",32,"-Я не собираюсь тебя подкупать. Я просто дарю. И вообще просыпайся я задолбался тебя лечить.",104587,null],[104619,"2026-07-09T23:47:32",9,"Квархадрон — Ты так уверен в своих словах... подойди ближе. — *Он слегка меняет положение тела и пододвигает свою голову прямо к тебе.* — разрешаю ко мне коснутся, не разрывай связь ума.",104599,null],[104628,"2026-07-09T23:49:06",32,"Спокойно подхожу и говорю.\n-Ну вообще пока я собирал тебя по частям мы с Майло излапали тебя вдоль и поперек. Но опустим этот форс-мажор.\nЛожу руку на лоб",104619,null],[104650,"2026-07-09T23:52:54",32,"(Арминар начал нежно налаживать чешую)",84658,null],[104662,"2026-07-09T23:58:13",9,"*Мгновением в твоей голове проносятся воспоминание, дварфы куют металлллл, удары настолько громкие что словно бьют по голове. Расплавленное золото и обсидиан, закалённые в пламени дракона... дракона перед тобой, но моложе... он дитя гор, он знает что его украли яйцом, вырастили и заставили работать, но ему плевать.*\n\n??? — ... Квархадрон, я всё ещё помню стук молотов. В твоей кузне я словно возвращаюсь туда, на другую сторону веков...\n\nДварф отвечает незнакомцу — ... Великая кузня, без помощи драконьего огня не выковать мне легендарный меч. — *Он берёт в руки чёрный как уголь меч и разрубает им наковальню как масло.* — Правда, это не моя заслуга, а его. Малой всю жизнь, с первого огня закалял его, ценнее любого...\n\n*Воспоминания проносятся, названия мест, лик чёрного дракона что исчезает на глазах, смерть дварфа под камнями и как тот самый меч исчезает ищ под завала. Калькадаспа, Гриммилосерд, воля и имя, вознесение и время, смех, жуткий смех, улыбка из тьмы и золотые глаза ищущие в темноте.*",84658,null],[104664,"2026-07-09T23:58:26",9,"/roll 1d4 психический урон",84658,null],[104667,"2026-07-09T23:58:41",9,"*Игнорирует.*",104650,null],[104674,"2026-07-10T00:00:35",32,"Фигня для Арми",104664,null],[104675,"2026-07-10T00:00:39",9,"Квархадрон мысленно — Чего ты хочешь от меня, представитель клана, Арминар. — *Звучит словно официоз, он не отвечал, он уверен что дал ответ на вопрос.* — Зачем ты пытаешься спасти меня.",84658,null],[104679,"2026-07-10T00:01:29",32,"Вот тут Арминар капитально завис и транслирует недоумение.\n-Я просто хочу помочь. Будь моим товарищем.",104675,null],[104680,"2026-07-10T00:01:40",32,"Давай дружить во!",84658,null],[104686,"2026-07-10T00:03:52",9,"*Лишь смех мысленный в ответ.*\n\nКвархадрон мысленно отвечает — Ты сам выбрал эту судьбу. — *Видно что рвение Арминара его позабавило, но он настроен скептически. Дракона держит пиошлое и его опыт.*",84658,null],[104687,"2026-07-10T00:04:05",32,"-Зачем спасаю? Я просто эгоистично хочу и все! Комплексы у меня такие. Я в детстве всегда хотел помощи и потому оказываю всем кому могу",104675,null],[104690,"2026-07-10T00:04:49",32,"-Да я сам все решил и \nтвоя судьба отчасти \nСейчас в моей власти!",104686,null],[104691,"2026-07-10T00:05:01",9,"//Есть какие-то заявки ещё?",84658,null],[104694,"2026-07-10T00:05:44",32,"-Ну а ещё я... Хочу стать ещё чуть более похожим на дракона",104691,null],[104695,"2026-07-10T00:05:45",9,"*На это он не отвечает, лишь отголоски чувств в ответ что считает ситуацию забавной.*",104690,null],[104699,"2026-07-10T00:06:42",9,"Квархадрон мысленно — Так убей меня. Ты всё ещё можешь.",104694,null],[104701,"2026-07-10T00:08:01",32,"-Ты в своём уме? До этого ты говорил что не умрёшь, теперь сам хочешь смер... Бляя ты все это время хотел покончить с собой? Нет уж! Ты тут точно не умрёшь! Не по не вопреки моей воле",104699,null],[104706,"2026-07-10T00:08:58",9,"Квархадрон мысленно — Я не умру, никогда. — *Абсолютная уверенность.*",104701,null],[104710,"2026-07-10T00:09:40",32,"-ну значит вставай и живы.",104706,null],[104712,"2026-07-10T00:10:32",32,"Я сделал что мог чтобы ты не умер.",84658,null],[104714,"2026-07-10T00:11:32",9,"Квархадрон мысленно — Ты сам выбрал эту судьбу.",84658,null],[104716,"2026-07-10T00:12:02",32,"-Ещё до нашей первой встречи. И не собираюсь её менять",104714,null],[104717,"2026-07-10T00:12:56",9,"*Снова мысли не воспринимающее слова в серьёз.*",84658,null],[104721,"2026-07-10T00:14:01",32,"(просто показываю свои воспоминания в таверне с Майло как мы решили идти искать дракона и мое предвкушение увидеть величие старшего)",104717,null],[104722,"2026-07-10T00:14:36",32,"(показываю и воспоминание и эмоции от ритуала преклонения) и ещё шквал всего бухнул",104717,null],[104732,"2026-07-10T00:16:43",32,"-Ну что? Как тебе такое? Теперь ты понимаешь?\n(И показывает первое впечатление от ран дракона что это все надо лечить возмущение как он может быть так изуродован и желание исцелить)",84658,null],[104747,"2026-07-10T00:19:41",9,"Квархадрон мысленно — Ребячество, не собираюсь повторять. — *Он подмостил лапы под голову с намереньем отдохнуть, раз уж его тело снова возвращает свои силы.*",84658,null],[104761,"2026-07-10T00:21:22",32,"-Ладно. Дело твое как воспринимать мои мысли.\n(Просто улёгся под бок рядом)",104747,null],[104773,"2026-07-10T00:23:02",9,"//Хочу сейчас тебя крепко попросить подумать, не буду спешить. Поймёшь потом, надеюсь будет не поздно. Время до 12го числа даю.",84658,null],[104782,"2026-07-10T00:24:30",9,"//Или могу сейчас, решай сам",84658,null],[104785,"2026-07-10T00:24:55",32,"Давай сейчас",84658,null],[104787,"2026-07-10T00:25:40",32,"Я все равно уже не передумаю не чего. Кроме разве что идеи спать рядом с драконом",104773,null],[104788,"2026-07-10T00:26:00",32,"(придавит ещё)",104787,null],[104792,"2026-07-10T00:27:22",9,"*Дракон не покидал место и больше не пытался завести разговор. В следующий раз когда Арминар ушёл а после вернулся Квархадрона нигде небыло, а отсюда вела огромная разрытая дыра.*",84658,null],[104797,"2026-07-10T00:27:56",32,"//хмм прямо настолько?",104792,null],[104800,"2026-07-10T00:28:38",32,"Иду смотреть куда ведёт дыра?",104792,null],[104801,"2026-07-10T00:28:46",9,"//Я создал все условия, но вы их разрушили поспешив. К сожелению с Квархадроном вы едва знакомы.",84658,null],[104802,"2026-07-10T00:29:22",42,"// опять я виноват. А я даже нечего не делал",104801,null],[104803,"2026-07-10T00:30:05",9,"*Ход был свежим и вёл наружу, открывался вид на горы с него и следы уходящие в даль. Он скорей всего просто ушёл.*",84658,null],[104806,"2026-07-10T00:30:47",32,"//Ну что же квест последование будет",104803,null],[104808,"2026-07-10T00:31:31",9,"//Хорошо что он не летает, плохо что вы потеряете след. Прийдётся как то по другому его искать",84658,null],[104812,"2026-07-10T00:32:03",42,"/r 1d20 +5 выживание",84658,null],[104815,"2026-07-10T00:32:11",9,"//Я просто расчитывал на время и разговоры, он бы привык и мог не уйти а вы поспешили",84658,null],[104819,"2026-07-10T00:33:02",42,"// Арми слишком поспешил. Майло вообще не как не взаимодействовал с драконом",104815,null],[104820,"2026-07-10T00:33:03",9,"//Не абессудьте, сам щас расстроен. Что бля за дни пошли",84658,null],[104823,"2026-07-10T00:33:32",42,"// следы? Наводки я нашëл?",104813,null],[104832,"2026-07-10T00:36:12",9,"*Следы ведут в драконьи горы, Майло нашёл место охоты, всё ещё неспособныйнормально есть Квархадрон буквально распотрошил дичь на мягкие части и съел что смог. Он шёл почти отдыхая, с его выносливостью вы не поспеете.*",104823,null],[104834,"2026-07-10T00:36:20",32,"(Просто по запаху. Выслеживать будем)",104808,null],[104835,"2026-07-10T00:36:40",42,"//бля я прочëл. Чëто так, уэээ.. Арми минус респект",84658,null],[104836,"2026-07-10T00:36:57",32,"Скороход у меня есть",104832,null],[104839,"2026-07-10T00:37:37",42,"// 120 футов скорости в ход бэйба. Так я и арми на спине пронесу без потери скорости",104832,null],[104840,"2026-07-10T00:37:46",42,"//со скороходом 150 футов в ход",84658,null],[104842,"2026-07-10T00:38:16",42,"// я как гоночный балид",84658,null],[104843,"2026-07-10T00:38:44",9,"//Короче, он ушёл. Если на пальцах я думал о том чтобы вы медленно пока он болен наладили связь, лекарство отыскалось слишком быстро. Это не механ а история и она пошла вообще не так. Но на то они и нри",84658,null],[104849,"2026-07-10T00:39:25",9,"//Ещё никогда ничего не шло по плану, единственное вы не убили Иму и всё",84658,null],[104853,"2026-07-10T00:40:23",42,"//говоришь так как будто я это должен, а потом с психоза и пупсика прикончу",104849,null],[104856,"2026-07-10T00:40:32",42,"// я помню читал такой рассказ",84658,null],[104859,"2026-07-10T00:41:12",32,"//я мать его недоволен. Его вылечили а он так в душу плюнул. У меня начинает дёргаться глаз",104843,null],[104865,"2026-07-10T00:42:28",9,"//Ты на него потратился едва ли какна камень который у тебя остался)",104859,null],[104869,"2026-07-10T00:42:59",42,"// знаешь в такие моменты обычно подходит самый близкий человек и говорит что всë нормально и у него есть он. Но вот не задачка. Майло против толпы невероятно слаб",104859,null],[104871,"2026-07-10T00:43:09",42,"// подохнет чëрт",84658,null],[104878,"2026-07-10T00:44:26",32,"//я на него потратил легендарную живую воду! А он шука недоволен",104865,null],[104885,"2026-07-10T00:46:20",32,"Глаз пересадил крыло заштопал. И впринципе мы его в вменяемое сообщение привели",84658,null],[104886,"2026-07-10T00:46:30",42,"// вот смотрю и на кого-то потраченно 1100 золотых и только потому что браток не прощаю. + тебе воду не разрешил бы хард если бы не дракон",104878,null],[104888,"2026-07-10T00:46:55",9,"//Ох, вы ему пытались впихнуть запчасти другого дракона...",84658,null],[104893,"2026-07-10T00:47:32",42,"Привыкай. Это жизнь, Арми когда нибудь останется один",104885,null],[104896,"2026-07-10T00:47:39",9,"//Точно? Тогда точно иню кидать, и это не дракон Коли, он и присмерти опасный ~",84658,null],[104903,"2026-07-10T00:48:42",9,"//Типа, вы не описыаали тут вроде про пересадку",84658,null],[104904,"2026-07-10T00:48:49",9,"//Воду видел",84658,null],[104906,"2026-07-10T00:49:03",9,"//Так бы был бой насмерть",84658,null],[104908,"2026-07-10T00:49:10",42,"// @Xaosick умрëм вместе. В следующей жизни встретимся?",84658,null],[104915,"2026-07-10T00:51:16",42,"// Hard а что за агр? Типо за то что убили другого дракона?",84658,null],[104916,"2026-07-10T00:51:33",32,"Описывал сразу",104903,null],[104917,"2026-07-10T00:51:51",32,"Да кстати",104915,null],[104934,"2026-07-10T00:55:18",9,"//Тут я пропустил, сорян. Просил же не спешить пока не освобожусь",104916,null],[104938,"2026-07-10T00:55:54",9,"//Остановимся на действующем варианте, остатки дракона он не видел и вы их не шили.",84658,null],[104941,"2026-07-10T00:56:30",32,"Так стоп!",104938,null],[104947,"2026-07-10T00:58:13",32,"Давай отмотаем сцену тогда до начала лечения. Когда я достал заспиртованных глаз",84658,null],[104965,"2026-07-10T01:04:46",9,"//Зачем?",104947,null],[104968,"2026-07-10T01:05:28",9,"//Ещё и заспиртованный, ух, даже если бы лечение то не сработало бы. Я думал вы не портили ничего",104947,null],[104969,"2026-07-10T01:05:59",32,"Потому что я хочу знать что он будет делать. Тем более что это до того как напоили водой",104965,null],[104970,"2026-07-10T01:06:19",32,"//слишком долго бегали сгнил бы за больше чем трое суток",104968,null],[104971,"2026-07-10T01:07:04",9,"//Драконьи то остатки? Это не человеческий. Ладно.",104970,null],[104973,"2026-07-10T01:07:41",9,"//Я просто не вижу смысла, не хочу ни тпк ни месить грязь.",84658,null],[104974,"2026-07-10T01:08:00",9,"//Тем более вы у коли ща вродь",84658,null],[104976,"2026-07-10T01:08:51",32,"Почему? Квархадрон сбежал и почему он должен был нас убить?",104973,null],[104978,"2026-07-10T01:09:17",9,"//Почему он не должен вас убивать когда вы приносите остатки его собрата?",84658,null],[104980,"2026-07-10T01:09:52",9,"//Кто вы такие чтобы оставаться с вами когда ноги его уже держат?",84658,null],[104985,"2026-07-10T01:11:14",32,"А может я этот глаз у кого-то купил?",104978,null],[104987,"2026-07-10T01:11:47",32,"Мы ммм понятно. Выслежу и убью",104980,null],[104988,"2026-07-10T01:11:55",9,"Это что-то меняет? Он тебя сильно слушал?)",84658,null],[105001,"2026-07-10T01:15:48",32,"Мда. Короче я обиделся и теперь уже у меня дипресия. Только прошлая кончилась бля",84658,null],[105003,"2026-07-10T01:16:35",9,"То же самое",84658,null],[105004,"2026-07-10T01:17:05",9,"Это одна из причин почему я был против той воды, но сильнее я не люблю ток метагейм",84658,null],[105006,"2026-07-10T01:17:24",32,"Угу. Ладно у самого блин желание уйти нах",105003,null],[105009,"2026-07-10T01:18:58",32,"Да уж. Сам себе похерил спутника. А ведь из-за того что слишком эффективен.",105004,null],[105162,"2026-07-10T07:41:13",42,"Вот и ваши драконы. Получили свободу и независимость и сразу же бросили",84658,null],[106521,"2026-07-11T07:44:49",31,"Да, быть слишком эффективным это скучно. Никакой дракон не захочет связываться с таким компьютером//",105009,null]]);
